window.__SUM[22]={"LR000008":{"pair":"ADAM15 -> ITGA9","headline":"ADAM-15 disintegrin domain binds integrin alpha9beta1 in an RGD-independent manner in one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Recombinant ADAM-12 and ADAM-15 disintegrin domains bind integrin alpha9beta1 in an RGD-independent manner [PMID:10944520]; the interaction supports cell-cell interaction [PMID:10944520].","molecular_requirements":"Receptor is alpha9beta1; alpha9 alone not tested [PMID:10944520].","affinity_potency":[],"species_and_systems":"Recombinant domains; species not reported in our evidence.","localisation_and_range":"ADAM15 is flagged not secreted [flag]; cell-cell adhesion context [PMID:10944520].","caveats":"One paper, abstract only; the human pair is ortholog-inferred in the dossier.","key_references":[{"PMID":"10944520","why":"alpha9beta1 binding to ADAM-15 disintegrin domain"}],"covers":["LR000008","LR003558"]},"LR000017":{"pair":"ADAM2 -> ITGA6","headline":"Mouse egg alpha6beta1 is the receptor for sperm fertilin beta (ADAM2) by photoaffinity labelling and bead binding.","interaction_type":"direct binding","direction_and_effect":"A photoaffinity DECD peptide from fertilin beta's disintegrin domain covalently labelled an alpha6 integrin complexed with beta1 on mouse eggs; authors conclude fertilin beta binds alpha6beta1 directly, mediating sperm-egg fusion [PMID:9889149]. Alpha6beta1 interacts with ADAM 2 [PMID:10518536].","molecular_requirements":"alpha6 is complexed with beta1; CD9 is needed for high-avidity binding [PMID:9889149][PMID:10518536].","affinity_potency":[],"species_and_systems":"Mouse eggs and sperm; peptide probe, not full-length protein [PMID:9889149]. The human pair is ortholog-inferred.","localisation_and_range":"ADAM2 flagged non-secreted [flag]; sperm-egg contact.","caveats":"Both papers abstract only; direct binding relies on a peptide probe.","key_references":[{"PMID":"9889149","why":"DECD peptide photoaffinity labels egg alpha6beta1"},{"PMID":"10518536","why":"Fertilin beads bind eggs via alpha6beta1; CD9 involved"}],"covers":["LR000017","LR003567"]},"LR000026":{"pair":"ADCYAP1 -> ADCYAP1R1","headline":"PACAP binds and activates the PAC1 receptor with picomolar to low-nanomolar affinity; well supported by many papers and databases.","interaction_type":"direct binding","direction_and_effect":"PACAP-27 and PACAP-38 are agonists: PAC1 accepts PACAP as a high-affinity ligand but not VIP [PMID:10100920]; PACAP-38 raised cAMP and calcium, and drove catecholamine secretion in human fetal chromaffin cells via PAC1 [PMID:12429744]. A PAC1 antagonist (M65) abolished PACAP-stimulated ANP secretion in rat antrum [PMID:12488235]. GtoPdb lists Agonist [DB:GtoPdb].","molecular_requirements":"A 21-amino-acid N-terminal extracellular deletion variant changes PACAP-27 versus -38 selectivity and phospholipase C potency [PMID:8703026]; PAC1n bound both PACAP forms in the low nanomolar range [PMID:10583729]. Single receptor chain.","affinity_potency":[{"value":"Ki 4.6 pM","assay":"competitive binding, PACAP38","system":"purified PACAP receptor, bovine brain","cite":"PMID:8253796"},{"value":"Ki 30.0 pM","assay":"competitive binding, PACAP27","system":"purified PACAP receptor, bovine brain","cite":"PMID:8253796"},{"value":"Kd 25.8 pM","assay":"125I-PACAP27 binding","system":"purified receptor, bovine brain","cite":"PMID:8253796"},{"value":"Ki 37.3 nM","assay":"competitive binding, VIP","system":"purified PACAP receptor, bovine brain","cite":"PMID:8253796"}],"species_and_systems":"Human recombinant PAC1 in HEK293 and CHO cells [PMID:10583729][PMID:16930633]; rat AR4-2J cells [PMID:10100920]; bovine brain receptor [PMID:8253796]; human fetal chromaffin cells [PMID:12429744]. Mouse experiments are not shown in our evidence.","localisation_and_range":"Ligand flagged secreted [flag]; neuropeptide acting on a membrane receptor (paracrine or neurotransmitter-like) [PMID:12429744].","caveats":"All papers read as abstracts only. Picomolar values come from bovine receptor. Three further papers were abstract_insufficient. A caution: PACAP also acts at VIP receptors [DB:UniProt].","key_references":[{"PMID":"8253796","why":"purified PACAP receptor with pM affinity"},{"PMID":"10583729","why":"PAC1 splice variants, low nM binding"},{"PMID":"16930633","why":"cAMP and calcium potency at human PAC1"}],"covers":["LR000026","LR003576"]},"LR005021":{"pair":"ADGRB1 -> RTN4RL1","headline":"ADGRB1 ectodomain binds RTN4RL1 directly in a CRISPRa and AVEXIS study; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"ADGRB1 probe stained cells overexpressing RTN4R, RTN4RL1 and RTN4RL2 and ectodomains interacted directly in AVEXIS in both bait-prey orientations [PMID:30477585]. CRISPRa guides targeting RTN4RL1 and RTN4RL2 were enriched when ADGRB1 was used as the selection probe [PMID:30477585].","molecular_requirements":"The N-terminal thrombospondin type 1 repeats 1-3 of ADGRB1 were sufficient for binding; ADGRB1 but not ADGRB2 interacted [PMID:30477585].","affinity_potency":[],"species_and_systems":"Human cDNAs in HEK293 cells and recombinant ectodomains; four independent experiments for the staining result [PMID:30477585]. Mouse pair is ortholog-inferred.","localisation_and_range":"The receptor side is a GPI-linked membrane protein per the paper [PMID:30477585]; ADGRB1 is flagged secreted [flag] but the assay used its ectodomain, and its native range is not reported in our evidence.","caveats":"Single paper; binding only, no signalling or functional effect shown. No affinity value. No database support.","key_references":[{"PMID":"30477585","why":"CRISPRa screen and AVEXIS showing ADGRB1-RTN4R family binding"}],"covers":["LR001633","LR005021"]},"LR000035":{"pair":"ADM -> CALCRL","headline":"Adrenomedullin binds and activates CALCRL (CLR); six confirmed papers, with RAMPs defining receptor phenotype.","interaction_type":"direct binding","direction_and_effect":"CALCRL expressed in COS-7 cells mediates a cAMP response to adrenomedullin and binds 125I-adrenomedullin [PMID:7592696]. With RAMP2 or RAMP3, CLR is an ADM receptor [PMID:9620797][PMID:10347248]. GtoPdb lists ADM as full agonist [DB:GtoPdb]. Stimulatory.","molecular_requirements":"CALCRL needs a RAMP for surface transport; RAMP2 or RAMP3 yield an ADM receptor, RAMP1 a CGRP receptor [PMID:9620797]. RAMP2 and RAMP3 present CLR as core-glycosylated [PMID:10347248].","affinity_potency":[{"value":"KD 8.2 x 10(-9) M","assay":"125I-adrenomedullin binding","system":"COS-7 cells","cite":"PMID:7592696"},{"value":"EC50 7 x 10(-9) M","assay":"cAMP response","system":"COS-7 cells","cite":"PMID:7592696"},{"value":"pKi 8.3-9.2","assay":"GtoPdb record","system":"HEK-293 per paper","cite":"PMID:11693189"}],"species_and_systems":"Transfected HEK-293, HEK293T and COS-7 cells; human and porcine receptors [PMID:11693189]; the first paper cloned an orphan receptor originally isolated from rat lung [PMID:7592696].","localisation_and_range":"ADM flagged secreted [flag], so paracrine/endocrine.","caveats":"All papers read as abstracts only. The 1995 paper tested CALCRL without a RAMP, whereas later papers show a RAMP is required for ADM receptor phenotype [PMID:9620797].","key_references":[{"PMID":"7592696","why":"cloning, KD and EC50"},{"PMID":"9620797","why":"RAMP2 confers ADM receptor phenotype"},{"PMID":"10347248","why":"RAMP2/RAMP3 CRLR pharmacology"}],"covers":["LR000035","LR003585"]},"LR000044":{"pair":"AGRP -> SDC3","headline":"Syndecan-3 is reported to modulate AGRP action in feeding control in mice; a single abstract-only paper, with no direct binding shown.","interaction_type":"functional only","direction_and_effect":"Via their HS chains, syndecans potentiate the action of agouti-related protein and agouti signaling protein [PMID:11461706]. Syndecan-3 null mice showed markedly reduced reflex hyperphagia after food deprivation [PMID:11461706].","molecular_requirements":"HS chains are required [PMID:11461706]. Not reported otherwise.","affinity_potency":[],"species_and_systems":"Mouse in vivo [PMID:11461706]. Mouse pair is not ortholog-inferred; human is.","localisation_and_range":"Syndecan-3 is the predominantly neural syndecan, expressed in hypothalamic regions controlling energy balance and increased several-fold by food deprivation [PMID:11461706].","caveats":"Abstract-only. The syndecan-3 null phenotype shows a role in feeding but does not itself show an AGRP-syndecan-3 interaction; the AGRP potentiation statement is general for syndecans. Modulator rather than classical receptor.","key_references":[{"PMID":"11461706","why":"Syndecan-3 null mice have reduced fasting-induced hyperphagia; syndecans potentiate AGRP"}],"covers":["LR000044","LR003594"]},"LR005030":{"pair":"ALCAM -> L1CAM","headline":"Antibody blocking suggests L1cam is needed for ALCAM-promoted axon growth of mouse midbrain dopamine neurons; no direct binding shown in our evidence.","interaction_type":"functional only","direction_and_effect":"ALCAM promoted axon growth of mouse midbrain dopamine neurons, and neutralizing antibodies for L1cam abolished the effect; the authors propose a trans-heterophilic interaction [PMID:31300520]. ALCAM also abolished Sema3A's growth effect and induced branching with Sema3C [PMID:31300520].","molecular_requirements":"L1cam is described as one of three components of a Semaphorin receptor complex (Nrp1, Chl1, L1cam) [PMID:31300520]; which is needed alone is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Murine primary midbrain cultures [PMID:31300520]; curator records human for both partners.","localisation_and_range":"ALCAM acts as an extracellular substrate presented to cell-bound partners (juxtacrine/matrix-like) [PMID:31300520]. Reactome lists an L1:ALCAM complex [DB:Reactome R-HSA-443658].","caveats":"Single paper, abstract only; inhibition by antibodies is indirect and shows no binding. No affinity.","key_references":[{"PMID":"31300520","why":"Antibody blocking of Nrp1/Chl1/L1cam abolishes ALCAM growth effect"}],"covers":["LR001642","LR005030"]},"LR000053":{"pair":"ANGPT1 -> ITGA5","headline":"A truncated monomeric ANGPT1 fragment binds integrin alpha5beta1 in one abstract-only paper; native full-length ANGPT1 binding is not shown.","interaction_type":"direct binding","direction_and_effect":"Monomeric DeltaAng1 (isolated fibrinogen-like receptor-binding domain) bound alpha(5)beta(1) integrin with similar affinity compared with Tie2, and reproduced some full-length Ang1 effects in endothelial cells (reduced permeability, increased adhesion, MAPK activation); curator labels it agonist [PMID:15781448].","molecular_requirements":"The integrin tested is the alpha5beta1 heterodimer, so ITGA5 alone is not shown to be sufficient; ITGB1 is also required in the measured receptor [PMID:15781448]. The ligand was a truncated monomer, not the native oligomer.","affinity_potency":[],"species_and_systems":"Recombinant human DeltaAng1 made in insect cells; endothelial cells and chick chorioallantoic membrane; human ligand and receptor per curation [PMID:15781448]. The mouse pair is ortholog-inferred.","localisation_and_range":"ANGPT1 is flagged as secreted [flag]; ITGA5 is flagged as a receptor and not secreted [flag].","caveats":"Single paper, read as abstract only. A numerical affinity is not given in our evidence (only 'similar affinity compared with Tie2'). The fragment was monomeric and did not trigger Tie2 phosphorylation. No database support.","key_references":[{"PMID":"15781448","why":"Monomeric Ang1 fragment binds alpha5beta1 integrin"}],"covers":["LR000053","LR003603"]},"LR000062":{"pair":"ANGPTL3 -> ITGB3","headline":"ANGPTL3 binds integrin alphaVbeta3, of which ITGB3 is the beta chain; evidence is for the heterodimer.","interaction_type":"direct binding","direction_and_effect":"Recombinant ANGPTL3 bound alpha(v)beta(3) and drove alpha(v)beta(3)-dependent endothelial adhesion and migration with Akt, MAPK and FAK signalling [PMID:11877390]. UniProt agrees [DB:UniProt].","molecular_requirements":"Evidence is for the alphaVbeta3 heterodimer; ITGB3 alone is not tested in our evidence.","affinity_potency":[],"species_and_systems":"Endothelial cells and rat corneal assay; recombinant protein species not reported in our evidence [PMID:11877390]. The mouse pair is projected from human.","localisation_and_range":"ANGPTL3 is described as liver-specific and secreted [PMID:11877390].","caveats":"Abstract-only; no affinity. Chain-only attribution: a CCC tool scoring ITGB3 alone assumes the other chain is present.","key_references":[{"PMID":"11877390","why":"ANGPTL3 binds alphaVbeta3 integrin"}],"covers":["LR000062","LR003612"]},"LR002114":{"pair":"ANGPTL4 -> ITGB1","headline":"ANGPTL4 is reported to bind integrin \u03b21 directly and drive FAK-Src-PAK1 signalling; abstract-level.","interaction_type":"direct binding","direction_and_effect":"ANGPTL4 binds integrins \u03b21 and \u03b25, but not \u03b23, as novel binding partners; \u03b21-bound ANGPTL4 activates FAK-Src-PAK1 signalling for keratinocyte migration [PMID:20952587]. ANGPTL4-deficient or neutralised mice show delayed wound reepithelialisation with impaired integrin-mediated signalling [PMID:20952587].","molecular_requirements":"Integrin \u03b21 alone is named as the binding partner; \u03b1-chain pairing is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Keratinocytes and mouse wound healing; species of the binding experiments not recorded in our fields [PMID:20952587]. The mouse pair is ortholog-inferred, not tested directly.","localisation_and_range":"ANGPTL4 flagged secreted; ITGB1 flagged receptor, non-secreted [flag]; wound-site paracrine signalling is implied by the paper.","caveats":"Abstract only; no affinity; an IntAct surface plasmon resonance record exists (PMID 21397862) [DB:IntAct]. The 'not \u03b23' statement excludes \u03b23 only.","key_references":[{"PMID":"20952587","why":"ANGPTL4 binds integrins \u03b21 and \u03b25 and signals through FAK-Src-PAK1"}],"covers":["LR002114","LR005436"]},"LR002123":{"pair":"ANGPTL5 -> LILRB3","headline":"ANGPTL5 binds LILRB3-overexpressing cells with lower affinity than LILRB2; flow cytometry only.","interaction_type":"functional only","direction_and_effect":"GST-Angptl5 bound LILRB3-overexpressing cells, with lower affinity than to LILRB2-expressing cells [PMID:22660330]. Signalling effect is not reported in our evidence.","molecular_requirements":"not reported in our evidence; the evidence is cell binding, not a purified-protein assay.","affinity_potency":[],"species_and_systems":"Human LILRB3 overexpressed in cells; human ligand [PMID:22660330].","localisation_and_range":"ANGPTL5 flagged secreted; LILRB3 flagged receptor [flag].","caveats":"No affinity value in our evidence; binding is weaker than for LILRB2, whose affinity is not transferable.","key_references":[{"PMID":"22660330","why":"GST-Angptl5 binds LILRB3 cells at lower affinity than LILRB2"}],"covers":["LR002123"]},"LR010610":{"pair":"ANXA1 -> DYSF","headline":"Supported only by UniProt interaction statements; no paper evidence for a ligand-receptor role.","interaction_type":"database-asserted only","direction_and_effect":"UniProt records state that annexin A1 and DYSF interact [DB:UniProt]. No ligand-receptor direction or effect is reported in our evidence.","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species not reported; one UniProt line is marked 'By similarity' [DB:UniProt].","localisation_and_range":"ANXA1 is flagged secreted and receptor but not transmembrane; DYSF has no flags [flag].","caveats":"No papers judged; the only curated outcome is 'different_entity'. Likely a protein-protein association rather than a signalling pair.","key_references":[],"covers":["LR010610"]},"LR012140":{"pair":"APCDD1 -> FZD3:LRP5","headline":"APCDD1 interacts in vitro with LRP5 and inhibits Wnt signalling; no evidence for this specific FZD3 subunit.","interaction_type":"direct binding","direction_and_effect":"APCDD1 is described as a Wnt inhibitor: it inhibits Wnt signalling cell-autonomously and upstream of beta-catenin, and represses Wnt reporters and target genes [PMID:20393562]. The paper reports an in vitro interaction with WNT3A and LRP5 [PMID:20393562]; IntAct and UniProt record the LRP5 interaction [DB:IntAct, DB:UniProt].","molecular_requirements":"Only LRP5 is shown to interact with APCDD1; FZD3 is not mentioned in the evidence sentence or abstract, so the complex-level pair rests on the LRP5 chain alone. A CCC tool scoring by the least-expressed subunit would add a requirement for FZD3 that our evidence does not support.","affinity_potency":[],"species_and_systems":"Human genetics and human cells for the interaction in vitro; Wnt inhibition also in chick neural development and Xenopus embryos [PMID:20393562].","localisation_and_range":"APCDD1 is described as a membrane-bound glycoprotein [PMID:20393562]; it is not flagged as secreted in the dossier, so juxtacrine or cell-autonomous action is more likely than long-range signalling.","caveats":"Single paper, abstract plus excerpts. Chain-only evidence (LRP5); no data for FZD3. The interaction is 'in vitro' with no affinity. APCDD1 may act as a Wnt-pathway inhibitor rather than a classical ligand.","key_references":[{"PMID":"20393562","why":"APCDD1 interacts with LRP5 and WNT3A and inhibits Wnt signalling."}],"covers":["LR012140"]},"LR002132":{"pair":"APLP2 -> CNTN4","headline":"APLP2 binds CNTN4 in a single paper using binding assays, biolayer interferometry and a crystal structure; the affinity is weak.","interaction_type":"direct binding","direction_and_effect":"The paper reports APLP2 binding CNTN4 in extracellular binding assays and biolayer interferometry (BLI), and states that APLP2 only binds CNTN4 and CNTN5, not CNTN3 [PMID:34958801]. Signalling effect and agonist or antagonist role are not reported in our evidence; contactins are described as forming coreceptor complexes with transmembrane proteins [PMID:34958801].","molecular_requirements":"A zebrafish CNTN4-APLP2 crystal structure (PDB 7MQY) is listed; the conserved interface involves the second fibronectin type III repeat of CNTNs and the copper-binding domain of amyloid proteins [PMID:34958801]. Further co-receptors are not reported in our evidence.","affinity_potency":[{"value":"6.3 \u03bcM","assay":"biolayer interferometry","system":"human APLP2 with CNTN4","cite":"PMID:34958801"}],"species_and_systems":"Human and mouse proteins were tested, plus zebrafish proteins (APLP2 with CNTN4 about 21.4 \u03bcM) [PMID:34958801]. The mouse pair is ortholog-inferred. Recombinant protein assays.","localisation_and_range":"APLP2 carries transmembrane, secreted and receptor annotation flags [flag]. CNTNs are GPI-anchored to the plasma membrane [PMID:34958801], so contact (juxtacrine) signalling is suggested.","caveats":"Weaker than CNTN4-APP or APP-APLP1 pairs per the paper [PMID:34958801]. Single paper. The curated direction label is not supported by the text.","key_references":[{"PMID":"34958801","why":"BLI affinity, selectivity within the CNTN family and crystal structure"}],"covers":["LR002132","LR005449"]},"LR007100":{"pair":"APOA1 -> TREM2:TYROBP","headline":"Supported only by UniProt's statement about TREM2; the TYROBP complex is not tested.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states TREM2 is a receptor for apolipoproteins including APOA1 and enhances uptake in microglia [DB:UniProt]. Effect through the complex is not reported in our evidence.","molecular_requirements":"Complex members are TREM2 and TYROBP [flag]; whether TREM2 alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"TYROBP is flagged transmembrane and TREM2 flagged secreted [flag].","caveats":"One paper was judged abstract_insufficient; no curator-verified evidence for the complex. See the APOA1 -> TREM2 dossier.","key_references":[],"covers":["LR007100"]},"LR002141":{"pair":"APOB -> TREM2","headline":"TREM2 binds LDL and apolipoproteins in one study; apoB itself is inferred from the LDL result.","interaction_type":"direct binding","direction_and_effect":"A protein microarray screen identified lipoprotein particles including LDL, and apolipoproteins including CLU/APOJ and APOE, as TREM2 ligands; binding was abolished or reduced by disease-associated TREM2 mutations [PMID:27477018]. Trem2 knockout microglia showed reduced LDL internalization [PMID:27477018]. BioGRID lists a TREM2-APOB reconstituted complex [DB:BioGRID].","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins listed; mouse knockout microglia were used for uptake [PMID:27477018]. Mouse pair is ortholog-inferred.","localisation_and_range":"TREM2 is flagged secreted and receptor; APOB flagged secreted [flag].","caveats":"The abstract names LDL, not APOB, as the ligand; APOB itself is not named. Abstract only.","key_references":[{"PMID":"27477018","why":"TREM2 binds LDL and apolipoproteins"}],"covers":["LR002141","LR005458"]},"LR002150":{"pair":"APOE -> TREM2","headline":"Two independent abstract-level binding studies; apoE binds TREM2 and the R47H variant weakens it.","interaction_type":"direct binding","direction_and_effect":"ApoE showed high-affinity binding to human TREM2 and increased TREM2-dependent phagocytosis of apoE-bound apoptotic N2a cells by primary microglia [PMID:26374899]. A protein microarray screen found apolipoproteins including APOE as TREM2 ligands; TREM2 overexpression enhanced APOE uptake [PMID:27477018].","molecular_requirements":"Binding was reduced by AD-associated TREM2 variants (R47H vastly reduced) [PMID:26374899] [PMID:27477018]. TREM2 signals with adaptor DAP12 [PMID:26374899].","affinity_potency":[],"species_and_systems":"Human proteins in biochemical assays; microglia and heterologous cells [PMID:26374899] [PMID:27477018]. Mouse pair is ortholog-inferred.","localisation_and_range":"TREM2 flagged secreted and receptor; ApoE secreted [flag].","caveats":"Both abstract only; affinity described as high but no number in our evidence.","key_references":[{"PMID":"26374899","why":"apoE-TREM2 binding and R47H"},{"PMID":"27477018","why":"microarray screen of TREM2 ligands"}],"covers":["LR002150","LR005465"]},"LR000080":{"pair":"APP -> CD74","headline":"CD74 co-precipitates with APP in cell overexpression, and APP-CD74 is a predicted endothelium-to-macrophage axis in mouse kidney injury; support is limited.","interaction_type":"direct binding","direction_and_effect":"CD74 interacts with APP and acts as a negative regulator of Abeta, reducing secreted Abeta40 and Abeta42 without changing sAPPalpha or sAPPbeta, apparently by diverting APP to CD74-induced vacuoles [PMID:19849849]. In mouse kidney injury, cell-communication analysis placed APP-CD74 as the dominant endothelial-to-macrophage pair, and the paper reports a co-IP showing direct interaction [PMID:39351084].","molecular_requirements":"Mature APP, not the C-terminal fragments, bound CD74; the 33 kDa N-terminal CD74 fragment bound APP but not the 14 kDa one, and the luminal trimeric region (1-115 deletion lacks it) and the first 23 residues were required [PMID:19849849]. CD74 did not pull down Notch or APLP2 [PMID:19849849]. No complex partners reported for the kidney study.","affinity_potency":[],"species_and_systems":"Binding: human HeLa and HEK293APP cells, with both human and mouse CD74 isoforms binding APP [PMID:19849849]. Kidney: mouse UUO and IRI models plus macrophage-endothelial co-culture [PMID:39351084].","localisation_and_range":"APP and CD74 are both flagged transmembrane, and APP is also flagged secreted [flag]. The kidney paper describes endothelial APP signalling to macrophage CD74 across cells [PMID:39351084].","caveats":"The 2009 paper concerns APP processing and trafficking inside cells, not CD74 as a signalling receptor for APP [PMID:19849849]. The kidney inference rests mainly on scRNA-seq with limited validation, and the co-IP cell system is not specified in our excerpts [PMID:39351084]. Both curated papers were read from abstracts plus excerpts. IntAct lists one solid-phase assay record [DB:IntAct]. Affinity not reported in our evidence.","key_references":[{"PMID":"19849849","why":"Co-IP mapping of CD74-APP interaction and effect on Abeta"},{"PMID":"39351084","why":"APP-CD74 endothelial-macrophage axis in mouse kidney injury"}],"covers":["LR000080","LR003629"]},"LR000107":{"pair":"BMP10 -> BMPR1A","headline":"Functional evidence only: ALK3 (BMPR1A) overexpression and knockdown change BMP10 signalling in cell lines; no direct binding in our evidence.","interaction_type":"functional only","direction_and_effect":"Overexpressing ALK3 or ALK6 in COS7 cells conferred BMP10 signalling, and ALK3 shRNA in MC3T3 cells suppressed Smad signalling induced by BMP10 and two other ligands; BMP10 activated Smad1/5/8 but not Smad2/3 [PMID:16049014]. GtoPdb lists BMP10 as an agonist at BMPR1A [DB:GtoPdb].","molecular_requirements":"ALK3 or ALK6 was sufficient in COS7 cells; whether a type II partner is needed is not reported for this pair in our evidence (the same paper's shRNA implicates BMPRII and ActRIIA in BMP10 signalling [PMID:16049014]).","affinity_potency":[],"species_and_systems":"COS7 and MC3T3 cell lines, reporter assays; curators annotate human ligand and receptor. Mouse pair is ortholog-inferred.","localisation_and_range":"BMP10 is annotated as secreted and the receptor as transmembrane [flag], so signalling would be paracrine or autocrine; no paper in our evidence tests range.","caveats":"Abstract read only. The result is a signalling readout, not binding, so indirect effects cannot be excluded.","key_references":[{"PMID":"16049014","why":"ALK3 overexpression/knockdown and BMP10 signalling"}],"covers":["LR000107","LR003656"]},"LR000116":{"pair":"BMP2 -> ACVR1","headline":"Functional evidence only: knockdown of ALK2/3 blocks BMP2 signalling in human granulosa-lutein cells; ALK2 not separated from ALK3.","interaction_type":"functional only","direction_and_effect":"BMP2 stimulated SMAD1/5/8 phosphorylation, blocked by BMP type I receptor inhibitors dorsomorphin and dorsomorphin homolog 1 but not SB431542; ALK2/3 or BMPR2/ACVR2B knockdown reversed it and restored PTX3 expression [PMID:28977600]. Downstream, BMP2 suppressed PTX3. GtoPdb lists it as an agonist [DB:GtoPdb].","molecular_requirements":"ALK2 and ALK3 were knocked down as a pair in the abstract, together with type II BMPR2/ACVR2B [PMID:28977600]; the individual ACVR1 contribution is not isolated.","affinity_potency":[],"species_and_systems":"Primary and immortalised human granulosa-lutein cells [PMID:28977600]. Mouse pair is ortholog-inferred.","localisation_and_range":"BMP2 is annotated as secreted [flag].","caveats":"Abstract only; no binding data. Other database records shown name BMPR1B rather than ACVR1 (BioGRID) [DB:BioGRID], and Reactome gives a generic 'binds the receptor complex' [DB:Reactome]. One row is pending.","key_references":[{"PMID":"28977600","why":"ALK2/3 and BMPR2/ACVR2B knockdown reverses BMP2 signalling"}],"covers":["LR000116","LR003665"]},"LR000125":{"pair":"BMP3 -> ACVR2B","headline":"BMP3 binds ACVR2B directly by SPR (Kd ~53 nM) and acts through it to suppress osteoblast differentiation; two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"BMP3 binds ActRIIb with 30-fold higher affinity than ActRII [PMID:17924656]. In bone marrow stromal cells, Acvr2b knockdown reduces BMP3's suppressive effect on osteoblast differentiation, so BMP3 acts as an antagonist of osteogenic signalling through ACVR2B [PMID:22074949]. UniProt records BMP3 associating with type II receptor ACVR2B to activate SMAD2-dependent and SMAD-independent signalling [DB:UniProt].","molecular_requirements":"ACVR2B is the type II receptor; a type I partner is not reported in our evidence. Binding specificity is linked to Lys-30 interactions with residue 76 differences between ActRII and ActRIIb [PMID:17924656].","affinity_potency":[{"value":"Kd approximately 53 nM","assay":"surface plasmon resonance (BIAcore), BMP-3 with ActRIIb","system":"human proteins (curated experiment species)","cite":"PMID:17924656"},{"value":"Kd approximately 1.8 microM","assay":"SPR, BMP-3 with ActRII (ACVR2A), for comparison","system":"human proteins","cite":"PMID:17924656"}],"species_and_systems":"Binding paper: recombinant protein SPR plus Smad luciferase assays [PMID:17924656]. Functional paper: primary bone marrow stromal cell cultures; curators record human ligand and receptor, though the abstract mentions mouse knockout/transgenic models as background [PMID:22074949].","localisation_and_range":"BMP3 is flagged secreted and ACVR2B a transmembrane receptor [flag].","caveats":"Both papers were read as abstracts only. The functional paper shows knockdown reduces the effect, not direct binding. The pair's human record is ortholog-inferred per the dossier.","key_references":[{"PMID":"17924656","why":"SPR binding of BMP-3 to ActRII and ActRIIb with Kd values"},{"PMID":"22074949","why":"Acvr2b knockdown reduces BMP3 suppression of osteoblast differentiation"}],"covers":["LR000125","LR003674"]},"LR000134":{"pair":"BMP6 -> ACVR2A","headline":"BMP6 binds ActR-II (ACVR2A) in a 1999 cross-linking study, but the key data are 'not shown'; BioGRID and GtoPdb agree.","interaction_type":"direct binding","direction_and_effect":"Curators label the effect agonist. BMP-6 bound ActR-II and ActR-IIB in singly transfected cells [PMID:10504300]. GtoPdb lists BMP6 as agonist at ACVR2A [DB:GtoPdb].","molecular_requirements":"Type II receptor binding was seen without a type I receptor in this paper [PMID:10504300]; further requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Recombinant human BMP-6 with transfected COS-7 cells; endogenous binding in mouse MC3T3-E1 and C2C12 lines [PMID:10504300]. BioGRID has an affinity-capture-Western record from this paper and a reconstituted-complex record from another [DB:BioGRID][PMID:18070108]. Both species pairs are projected from this evidence.","localisation_and_range":"BMP6 is flagged secreted and ACVR2A transmembrane [flag].","caveats":"The binding result is marked 'data not shown' in the paper's text, so only the authors' statement supports it. Affinity not reported.","key_references":[{"PMID":"10504300","why":"cross-linking of BMP-6 to ActR-II/ActR-IIB"}],"covers":["LR000134","LR003683"]},"LR000143":{"pair":"BMP7 -> BMPR1B","headline":"BMP7 binds BMPR1B (ALK-6) efficiently; SPR KD 9 nM and COS-cell binding support it.","interaction_type":"direct binding","direction_and_effect":"OP-1 (BMP7) bound ALK-6 efficiently in transfected COS cells [PMID:8006002]. BMP7 bound the type I receptor BMPR-IB with comparable affinity to its type II receptors in SPR [PMID:19735544]. GtoPdb lists agonist action [DB:GtoPdb].","molecular_requirements":"BMPR1B is a type I chain. Binding in COS cells was seen without type II receptors and increased with co-transfected DAF-4 [PMID:8006002].","affinity_potency":[{"value":"KD(kin) 9.0 nM","assay":"SPR, immobilised BMPR-IB ECD, soluble BMP7","system":"recombinant proteins","cite":"PMID:19735544"}],"species_and_systems":"Human proteins, SPR and COS cells plus various nontransfected cell lines [PMID:19735544][PMID:8006002]. Mouse pair is ortholog-inferred.","localisation_and_range":"BMP7 is flagged secreted and the receptor transmembrane [flag], suggesting paracrine signalling to a cell-surface receptor; the papers do not address range.","caveats":"PMID 8006002 was read as abstract only. The BMPR-IB KD(eq) is reported as not evaluated; the 9 nM is the kinetic KD [PMID:19735544]. Other judged papers: three abstract_insufficient, one different_entity, one pending.","key_references":[{"PMID":"19735544","why":"SPR affinity of BMP7 for BMPR-IB"},{"PMID":"8006002","why":"OP-1 binds ALK-6 efficiently in COS cells"}],"covers":["LR000143","LR003692"]},"LR011204":{"pair":"BMP8B -> ACVR2B","headline":"BMP8B -> ACVR2B rests on GtoPdb agonist records only; no paper confirmed it.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP8B as an agonist at ACVR2B [DB:GtoPdb]; no verified paper supports the effect.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental system reported in our evidence.","localisation_and_range":"Not reported in our evidence; the ligand has no secretion flag in the dossier.","caveats":"Judged papers were abstract-insufficient, review-only or about a different entity; none confirmed this pair. No affinity.","key_references":[],"covers":["LR011204"]},"LR000152":{"pair":"C1QA -> CR1","headline":"Direct C1q-CR1 binding supported by BIAcore and cell adhesion assays, with a UniProt record naming the CR1 domains.","interaction_type":"direct binding","direction_and_effect":"E binding to immobilised C1q was specifically inhibited by anti-CR1 Fab fragments, and binding was confirmed by BIAcore to immobilised CR1; C1q and C4b bind simultaneously and additively support erythrocyte adhesion [PMID:10528211]. Effect on signalling not reported.","molecular_requirements":"UniProt lists CR1 interaction via Sushi 24 and Sushi 25 domains [DB:UniProt]. Intact C1 adhered poorly until C1r2C1s2 was removed, leaving C1q [PMID:10528211].","affinity_potency":[],"species_and_systems":"Human erythrocytes and transfected cells; BIAcore with immobilised CR1 [PMID:10528211].","localisation_and_range":"C1q annotated secreted [flag]; adhesion in the paper involves surface-bound C1q.","caveats":"Abstract only; no affinity values in our evidence.","key_references":[{"PMID":"10528211","why":"C1q binds CR1, supports erythrocyte adhesion"}],"covers":["LR000152"]},"LR002222":{"pair":"C1QTNF9 -> ADIPOR1","headline":"CTRP9 (C1QTNF9) signals through ADIPOR1 in endothelial cells; one full-text paper with knockdown and crosslink evidence.","interaction_type":"direct binding","direction_and_effect":"CTRP9 acted as an agonist: it caused vasorelaxation and increased AMPK/Akt/eNOS phosphorylation and NO production, and knockdown of AdipoR1 but not AdipoR2 blocked this [PMID:21836066]. A crosslink study showed AdipoR1 and CTRP9 directly interact, which the authors call first direct evidence that AdipoR1 may function as a CTRP9 binding protein [PMID:21836066].","molecular_requirements":"AdipoR1 alone was required; AdipoR2 knockdown had no significant effect. No co-receptor requirement reported in our evidence. CTRP9 was nearly three-fold more potent than adiponectin in NO production [PMID:21836066].","affinity_potency":[],"species_and_systems":"Murine CTRPs were tested on aortic rings; mechanism was in human umbilical vein endothelial cells (siRNA knockdown) and mouse aortic endothelial cells [PMID:21836066]. The mouse pair is ortholog-inferred.","localisation_and_range":"CTRP9 is flagged as secreted [flag]; range is therefore paracrine/endocrine by annotation only.","caveats":"Single paper; binding rests on a crosslink experiment, with no affinity reported. The authors describe AdipoR1 as a 'likely receptor' [PMID:21836066].","key_references":[{"PMID":"21836066","why":"Knockdown and crosslink evidence for CTRP9-AdipoR1"}],"covers":["LR002222","LR005534"]},"LR000161":{"pair":"C3 -> LRP1","headline":"Activated C3 binds LRP1 with a Kd of 17 nM in one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"125I-C3 bound a 600-kDa endosomal protein by ligand blotting, competed by receptor-associated protein, lactoferrin and Pseudomonas exotoxin, and uptake was abolished in LRP-deficient mouse fibroblasts [PMID:10608878].","molecular_requirements":"Binding was Ca2+-dependent [PMID:10608878]. Subunit requirements not reported in our evidence.","affinity_potency":[{"value":"Kd 17 nM","assay":"saturable uptake","system":"cells; human 125I-C3","cite":"PMID:10608878"}],"species_and_systems":"Human 125I-C3 on endosomal proteins; LRP-deficient mouse fibroblasts used as control [PMID:10608878]. Mouse pair is ortholog-inferred.","localisation_and_range":"LRP1 is an endocytic receptor; localisation is not described beyond the paper.","caveats":"Abstract only. Curator note: native plasma C3 is not internalised; binding applies to activated C3 [PMID:10608878]. Possible role is clearance rather than signalling.","key_references":[{"PMID":"10608878","why":"C3 binding and uptake via LRP1"}],"covers":["LR000161","LR003710"]},"LR002231":{"pair":"CADM2 -> CADM4","headline":"Direct CADM2-CADM4 binding stated by SPRi in one paper; no affinity or species label recorded.","interaction_type":"direct binding","direction_and_effect":"SPRi detected homophilic and heterophilic interactions of CADM2, CADM3 and CADM4 with all CADM family proteins [PMID:30131958].","molecular_requirements":"Ectodomain-Fc proteins; no other subunit reported [PMID:30131958].","affinity_potency":[],"species_and_systems":"Recombinant Fc ectodomains; the curator left species unrecorded, though the paper used an anti-human IgG-Fc antibody for Western blotting [PMID:30131958]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both flagged membrane-bound [flag].","caveats":"One paper; no Kd for this pairing in our evidence. Support is a blanket statement, not a pair-specific result.","key_references":[{"PMID":"30131958","why":"SPRi of CADM family"}],"covers":["LR002231","LR005541"]},"LR000170":{"pair":"CALCA -> CALCR","headline":"Alpha-CGRP acts as a weak agonist at CALCR alone and more potently at CALCR+RAMP; much of the binding evidence is for calcitonin.","interaction_type":"functional only","direction_and_effect":"Alpha-CGRP is an agonist (cAMP readouts). At CALCR alone it is weak: about 100-fold less potent than hCT [PMID:12565884]; CTR2/RAMP heterodimers gave cAMP responses approximately 50-fold greater than CTR2 alone [PMID:14722252]. It is far more potent at CALCR+RAMP1 (AMY1a) [PMID:15692146]; AMY1 (CALCR/RAMP1) was reported as a functional second CGRP receptor in rat trigeminal neurons [PMID:26125036]. GtoPdb records the pair as full agonist [DB:GtoPdb].","molecular_requirements":"RAMP co-expression is needed for physiologically relevant CGRP potency; the RAMP1 C-terminal domain increased CGRP potency over CTRa alone, the RAMP2 one did not [PMID:16531504]. RAMP1 and CTR2 form cell-surface complexes [PMID:11023820]. RAMP3 co-expression changed relative potency of hCTR to calcitonin and amylin [PMID:11033437].","affinity_potency":[{"value":"Kd 4.6 nM","assay":"calcitonin (human CT) binding to calcitonin receptor, not CGRP","system":"human ovarian carcinoma BIN-67 cells","cite":"PMID:1331173"},{"value":"IC50 8.1 nM","assay":"hCT inhibition of [125I]hCT binding (CGRP-I over 100 times less potent)","system":"human MCF-7 cells","cite":"PMID:9487987"}],"species_and_systems":"Mostly human proteins in transfected cells (HEK-293, COS-7, RAEC, Xenopus melanophores) [PMID:14722252][PMID:12565884][PMID:11033437]; trigeminal work used rat and human tissue [PMID:26125036]. Mouse pair is ortholog-inferred. PDB 7TYH and 7TYO contain CALCA and CALCR chains [DB:PDB 7TYH].","localisation_and_range":"CALCA is flagged secreted and CALCR transmembrane [flag]: paracrine/endocrine peptide acting on a membrane GPCR.","caveats":"All 11 papers shown were read as abstracts only. Several binding papers measure calcitonin (hCT), not CGRP [PMID:1331173][PMID:9487987][PMID:7588285]. Many cite CTR2 or isoforms, not the AMY1 complex. Reactome lists a CALCA(83-119) fragment binding CALCR [DB:Reactome]; UniProt lists calcitonin and CGRP1/CALCA as CALCR activators [DB:UniProt].","key_references":[{"PMID":"15692146","why":"alpha-CGRP weak at CALCR alone, potent at CALCR+RAMP1 (AMY1a)"},{"PMID":"12565884","why":"CGRP about 100-fold less potent than hCT at CTR alone; RAMP raises potency"},{"PMID":"26125036","why":"AMY1 (CALCR/RAMP1) as functional CGRP receptor in trigeminal neurons"}],"covers":["LR000170","LR003715"]},"LR002240":{"pair":"CALCB -> RAMP3","headline":"Not supported: the one paper checked found no CALCB-RAMP3 pairing; only GtoPdb agonist records assert it.","interaction_type":"database-asserted only","direction_and_effect":"A curator judged pair_absent for the one paper: knockdown of RAMP3 inhibited ADM-induced cAMP, and absence of both RAMP2 and RAMP3 further increased CALCB-induced cAMP synthesis, not the pattern expected for an agonist relationship [PMID:26423127]. GtoPdb lists agonist records [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"pIC50 7.0 to 7.5","assay":"GtoPdb agonist record","system":"database record","cite":"DB:GtoPdb"}],"species_and_systems":"Rat mesenteric artery smooth muscle cells [PMID:26423127].","localisation_and_range":"Ligand flagged secreted, RAMP3 transmembrane [flag].","caveats":"Verified negative from an abstract-only read. Database support only; remaining judged rows were different_entity or abstract_insufficient.","key_references":[{"PMID":"26423127","why":"RAMP3 linked to ADM, not CALCB, signalling"}],"covers":["LR002240","LR005550"]},"LR000206":{"pair":"CCL17 -> CCR8","headline":"CCL17 is reported as a CCR8 agonist in one chemotaxis study; a structural paper only asserts it. Secondary to CCR4.","interaction_type":"functional only","direction_and_effect":"TARC induced chemotaxis in CCR8 Jurkat stable transfectants [PMID:9521068]; a structure paper states TARC interacts primarily with CCR4 and to a lesser extent CCR8, without testing it [PMID:12832759].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor in Jurkat transfectants; abstract-only [PMID:9521068][PMID:12832759]. Mouse pair projected from human.","localisation_and_range":"Secreted ligand and transmembrane receptor according to entity annotation flags [flag]; paracrine/endocrine range implied by the secreted flag only.","caveats":"No binding or affinity for CCR8; the structural paper has no receptor assay. Evidence is limited to abstracts.","key_references":[{"PMID":"9521068","why":"TARC and MIP-1beta chemotaxis via CCR8"},{"PMID":"12832759","why":"Mentions CCR8 as a secondary receptor; structure only"}],"covers":["LR000206","LR003734"]},"LR000233":{"pair":"CCL2 -> ACKR4","headline":"One abstract-read paper shows high-affinity MCP-1 binding and chemotaxis response in cells expressing the receptor now called ACKR4.","interaction_type":"direct binding","direction_and_effect":"Receptor transfection gave responsiveness to MCP-4, MCP-2 and MCP-1 in chemotaxis assays; MCP-1 competed for binding with IC50 10.7 nM, and MCP-3 and eotaxin bound with greater affinity but acted as agonists only at 100-fold higher concentrations [PMID:10734104].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"IC50 10.7 nM","assay":"competition binding vs radiolabeled MCP-4","system":"receptor-transfected murine L1.2 cells","cite":"PMID:10734104"}],"species_and_systems":"Human ligand and receptor expressed in murine L1.2 cells [PMID:10734104]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged as secreted and not transmembrane [flag], so signalling is presumably paracrine or endocrine; receptor is flagged transmembrane [flag].","caveats":"Single paper, abstract only; the paper calls the receptor CCR11 (alias). No database record in our evidence.","key_references":[{"PMID":"10734104","why":"Chemotaxis and competition binding, MCP-1 IC50 10.7 nM"}],"covers":["LR000233","LR003754"]},"LR000215":{"pair":"CCL21 -> ACKR4","headline":"Well supported high-affinity CCL21 binding to the atypical receptor ACKR4 (CCX-CKR), which acts as a decoy/scavenger rather than a classical signalling receptor.","interaction_type":"direct binding","direction_and_effect":"ACKR4 (CCX-CKR) binds CCL21 and internalises it, acting as a decoy that prevents CCL21 reaching CCR7; it does not activate classical Gi signalling [PMID:23341447]. Beta-arrestin recruitment to ACKR4 occurred with CCL21 [PMID:23341447], and a screen of human chemokines also lists CCL21 as an ACKR4 agonist in a beta-arrestin assay [PMID:32480426]. GtoPdb lists an agonist [DB:GtoPdb].","molecular_requirements":"ACKR4 as a single receptor was sufficient for binding; no co-receptor is reported in our evidence. Beta-arrestin signalling to CRE needed an intact DRY motif [PMID:23341447].","affinity_potency":[{"value":"IC50 <15 nM","assay":"radiolabelled-ligand competition (SLC = CCL21 high-affinity ligand)","system":"cells expressing human CCX CKR","cite":"PMID:10706668"},{"value":"pKi 6.9","assay":"affinity recorded for CCX-CKR; ligand it applies to not stated in our evidence","system":"human CCX-CKR","cite":"PMID:23341447"}],"species_and_systems":"All experiments were human ligand and human receptor in recombinant cells [PMID:23341447][PMID:10706668][PMID:32480426].","localisation_and_range":"Ligand is flagged secreted and receptor flagged transmembrane [flag]; this is an annotation, not from the papers, and implies paracrine/endocrine signalling to a cell-surface receptor. ACKR4 is described as an internalising decoy [PMID:23341447].","caveats":"All three papers were read as abstracts only. The pKi 6.9 is not tied to CCL21 specifically in the dossier, and PMID:10706668 names CCL21 as SLC. The receptor appears as CCX CKR, CCX-CKR, and CCR11/CCR10 in different records.","key_references":[{"PMID":"23341447","why":"decoy function, internalisation and beta-arrestin recruitment"},{"PMID":"10706668","why":"CCL21 (SLC) is a high-affinity ligand, IC50 <15 nM"},{"PMID":"32480426","why":"independent beta-arrestin screen"}],"covers":["LR000215"]},"LR000224":{"pair":"CCL25 -> CCR9","headline":"CCL25 (TECK) is an agonist of CCR9, supported by calcium flux, migration and chemotaxis data in human and mouse systems.","interaction_type":"functional only","direction_and_effect":"Agonist: TECK provoked calcium mobilisation in HEK 293 cells expressing human or murine GPR-9-6 (CCR9) and induced migration of human GPR-9-6 cells [PMID:10229797]. TECK specifically induced calcium flux in CCR9-expressing cell lines and chemotaxis of human thymocytes [PMID:10498628]. Mouse CD8+ lymphocytes migrated to CCL25 in line with CCR9 expression [PMID:11159507].","molecular_requirements":"CCR9 alone was sufficient in transfectants [PMID:10229797][PMID:10498628].","affinity_potency":[],"species_and_systems":"Human and murine ligand and receptor in HEK 293 cells [PMID:10229797]; human thymocytes [PMID:10498628]; mouse lymphocytes [PMID:11159507]. The mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted, receptor transmembrane [flag]; thymus and lymphoid-organ expression is reported [PMID:10229797][PMID:11159507].","caveats":"No binding constants in our evidence; evidence is functional. Abstracts only. PMID 11159507 treats the pairing as established. Reactome and GtoPdb records agree [DB:Reactome][DB:GtoPdb].","key_references":[{"PMID":"10229797","why":"Deorphanised GPR-9-6 as TECK receptor"},{"PMID":"10498628","why":"CCR9 calcium and thymocyte chemotaxis"},{"PMID":"11159507","why":"Mouse CCR9+ lymphocyte migration to CCL25"}],"covers":["LR000224","LR003748"]},"LR000242":{"pair":"CCL3L1 -> CCR3","headline":"LD78beta (mapped to CCL3L1) binds CCR3 and mobilises calcium, but only in its full-length form; one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Full-length LD78beta(1-70) at 30 ng/ml competed with [125I]RANTES for CCR3 binding and mobilised calcium in CCR3 transfectants [PMID:11449371].","molecular_requirements":"The CD26-processed LD78beta(3-70) shows a 30-fold decrease in CCR3 affinity, so the intact N-terminus is needed [PMID:11449371]. LD78alpha is contrasted as not behaving the same way [PMID:11449371].","affinity_potency":[],"species_and_systems":"Human proteins, CCR3 transfectants [PMID:11449371]. BioGRID records a reconstituted complex [DB:BioGRID].","localisation_and_range":"CCL3L1 is flagged as secreted and CCR3 as transmembrane [flag].","caveats":"One paper, abstract only; no absolute affinity given. Processing state matters: CD26 cleavage improves CCR1/CCR5 binding but reduces CCR3 binding [PMID:11449371]. Gene mapping of LD78beta to CCL3L1 comes from curators.","key_references":[{"PMID":"11449371","why":"Full-length LD78beta binds CCR3; processed form loses 30-fold"}],"covers":["LR000242"]},"LR000251":{"pair":"CCL4 -> CCR1","headline":"CCL4 (MIP-1beta) binds CCR1 in recombinant assays; effect is reported as agonist in one paper and antagonist in GtoPdb.","interaction_type":"direct binding","direction_and_effect":"In hCCR1-transfected cells CCL4 displaced 125I-MIP-1alpha and acted as a full agonist in [35S]-GTPgammaS exchange [PMID:12381680]. In HL-60(Rx) cells potency was MIP-1alpha>MPIF-1>RANTES>or=MIP-1beta, with ligands differing in efficacy [PMID:12381680]. GtoPdb records the pair as Antagonist [DB:GtoPdb], which conflicts with the full-agonist result.","molecular_requirements":"Not reported in our evidence. Reactome lists a CCL4,(CCL4L):CCR5,CCR1 complex [DB:Reactome R-HSA-8865354].","affinity_potency":[{"value":"pKi 7.1 to 7.8","assay":"GtoPdb interaction record","system":"not stated","cite":"DB:GtoPdb"},{"value":"EC50 8.9 nM","assay":"murine MIP-1 beta on murine CCR-1 (binding and calcium response)","system":"COS cells, mouse","cite":"PMID:7594543"}],"species_and_systems":"Human: Ba/F3-hCCR1 membranes and HL-60 cells [PMID:12381680]. Mouse: COS cells expressing murine CCR-1 [PMID:7594543].","localisation_and_range":"CCL4/CCL5 carry a secreted flag [flag], so paracrine or endocrine range is implied; the receptor carries receptor and transmembrane flags [flag].","caveats":"Both papers were read as abstracts only. Agonist versus antagonist labels conflict between GtoPdb and the primary paper. The Kd values in PMID:7594543 are for MIP-1 alpha and RANTES, not CCL4.","key_references":[{"PMID":"12381680","why":"Radioligand and GTPgammaS data for CCL4 at human CCR1"},{"PMID":"7594543","why":"Murine CCR-1 binding and calcium response to MIP-1 beta"}],"covers":["LR000251"]},"LR000260":{"pair":"CCL5 -> ACKR1","headline":"CCL5 binds ACKR1 (DARC) with strong, direct binding in human erythrocytes; ACKR1 is a non-signalling chemokine-binding receptor.","interaction_type":"direct binding","direction_and_effect":"CCL5 is among inflammatory chemokines selectively bound by DARC, not lymphoid chemokines [PMID:13679391, PMID:15358176]. Curator notes describe DARC as a non-signalling atypical (scavenger/decoy) receptor, so CCL5 binding is not agonism [PMID:13679391]. In that paper DARC-bound CCL2 failed to give a significant Ca2+ signal [PMID:13679391].","molecular_requirements":"Not reported in our evidence; ACKR1 acts on its own in the binding assays.","affinity_potency":[{"value":"Ki 5.6 nM","assay":"competition displacement of 125I-CXCL8","system":"human erythrocytes, human DARC","cite":"PMID:15358176"}],"species_and_systems":"Human erythrocytes, lymph node high endothelial venules and inflamed synovial endothelium [PMID:15358176, PMID:13679391, PMID:12081195]. A mouse interaction is also listed but no mouse experiment is shown.","localisation_and_range":"ACKR1 is transmembrane [flag]; binding was seen on erythrocyte and endothelial surfaces, where it can present or clear chemokine (curator notes) [PMID:12081195].","caveats":"Papers other than PMID:15358176 were read as abstracts only. In PMID:12081195 RANTES evidence is indirect (cross-displacement of 125I-IL-8, with blocking anti-DARC antibody tested on IL-8 only). No database record supports the pair.","key_references":[{"PMID":"15358176","why":"Ki 5.6 nM, human erythrocyte displacement; CCL5 binds endothelium"},{"PMID":"13679391","why":"Competitive binding with 20 chemokines; CCL5 binds DARC"},{"PMID":"12081195","why":"In situ binding on synovial endothelium"}],"covers":["LR000260","LR003770"]},"LR000422":{"pair":"CCN1 -> ITGB2","headline":"CCN1 engages the beta2 integrin alphaMbeta2 on monocytes; evidence concerns the alphaM chain and heterodimer, not beta2 alone.","interaction_type":"direct binding","direction_and_effect":"Monocyte adhesion to Cyr61 (CCN1) was mediated primarily through integrin alphaMbeta2 [PMID:12036876]. Adhesion to the CCN1 H2 peptide was blocked by anti-alphaM mAb, and GST-alphaMI bound it [PMID:12736251].","molecular_requirements":"Binding was shown through the alphaM I-domain, so beta2 acts as the partner chain of alphaMbeta2; beta2 alone is not tested. HSPGs act as co-receptors [PMID:12036876].","affinity_potency":[],"species_and_systems":"Human THP-1 cells, monocytes and HEK293 transfectants; human CCN1. Mouse pair is ortholog-inferred.","localisation_and_range":"CCN1 is flagged secreted [flag] but described in the papers as matrix-associated, so adhesion-type contact with receptors on neighbouring cells is plausible.","caveats":"Chain-only evidence: the binding site is on alphaM, not beta2. Both papers abstract only. No affinity reported. Treat as the alphaMbeta2 complex when scoring.","key_references":[{"PMID":"12036876","why":"alphaMbeta2 as CCN1 monocyte adhesion receptor"},{"PMID":"12736251","why":"alphaM I-domain binding mapped to CCN1 H2 peptide"}],"covers":["LR000422","LR003919"]},"LR001700":{"pair":"CCN4 -> ITGA5","headline":"Functional evidence only: CCN4-driven fibroblast migration depends on alpha5beta1 integrin; direct ITGA5 binding not shown.","interaction_type":"functional only","direction_and_effect":"CCN4-induced migration of dermal fibroblasts appears to work via alpha5beta1 integrin receptors, further stimulating ERK/JNK signalling; the dossier labels CCN4 an agonist [PMID:29330021].","molecular_requirements":"The paper implicates the alpha5beta1 integrin heterodimer; whether one chain alone suffices is not reported in our evidence. Both ITGA5 and ITGB1 pairs rest on the same single paper [PMID:29330021].","affinity_potency":[],"species_and_systems":"Human adult dermal fibroblasts (siRNA knockdown or adenoviral CCN4) and Ccn4-knockout mouse dermal fibroblasts and wounds [PMID:29330021].","localisation_and_range":"CCN4 is flagged secreted and the integrin as a receptor [flag]; matrix-associated paracrine action is plausible but not stated in our evidence.","caveats":"No binding assay is reported; the link to the integrin is inferred from migration experiments, and the paper was read mainly as abstract plus excerpts. No database record supports this pair. The integrin subunit is a chain of a heterodimer.","key_references":[{"PMID":"29330021","why":"CCN4 wound healing via alpha5beta1 in dermal fibroblasts"}],"covers":["LR001700","LR005069"]},"LR002303":{"pair":"CDH1 -> ITGB1","headline":"E-cadherin binds integrin alpha2beta1 in vitro; one abstract-level paper, binding looks direct but is untested for beta1 alone.","interaction_type":"direct binding","direction_and_effect":"Pentameric E-cadherin specifically bound purified alpha2beta1 and the recombinant alpha2 A-domain in a divalent cation-dependent manner; HT1080 adhesion to E-cadherin was blocked by anti-alpha2 and anti-beta1 antibodies [PMID:12392763].","molecular_requirements":"The alpha2beta1 heterodimer is the binding unit: binding mapped to the alpha2 A-domain, and antibodies to other subunits did not block [PMID:12392763]. ITGB1 alone is not shown to be sufficient.","affinity_potency":[],"species_and_systems":"Solid-phase binding with purified protein and cell adhesion assays; species not stated in our evidence for the experiments. The mouse pair is ortholog-inferred.","localisation_and_range":"Both partners are membrane proteins (E-cadherin flagged transmembrane), so contact-dependent [flag].","caveats":"Abstract-only read. The pentameric construct was designed to detect low-affinity interaction; monomeric E-cadherin did not bind, which the curator treats as an avidity control [PMID:12392763]. No affinity reported.","key_references":[{"PMID":"12392763","why":"Binding of E-cadherin to alpha2beta1 and alpha2 A-domain"}],"covers":["LR002303","LR005601"]},"LR002312":{"pair":"CDH2 -> KLRG1","headline":"KLRG1 binds N-cadherin per one expression-cloning paper read as abstract; support is brief.","interaction_type":"direct binding","direction_and_effect":"KLRG1 bound N- and R-cadherins in addition to E-cadherin; KLRG1 is an inhibitory NK receptor [PMID:16461340].","molecular_requirements":"Not reported in our evidence beyond ectodomain tetramer binding.","affinity_potency":[],"species_and_systems":"The screen used a mouse KLRG1 tetramer on mouse and human cell lines; the syngeneic result in mouse is for E-cadherin, and N-cadherin binding is not resolved to species in our evidence [PMID:16461340].","localisation_and_range":"Both are membrane proteins [flag], so contact-dependent.","caveats":"Evidence rests on one paper and its abstract sentence; excerpts shown concern E-cadherin cell-line binding, not N-cadherin. Two other papers were abstract-insufficient. No affinity reported.","key_references":[{"PMID":"16461340","why":"KLRG1 binds N-cadherin among three classical cadherins"}],"covers":["LR002312","LR005610"]},"LR002321":{"pair":"CDH8 -> CDH8","headline":"Cadherin-8 homophilic binding is weaker than its binding to cadherin-11 in SPR on mouse proteins.","interaction_type":"direct binding","direction_and_effect":"Cadherin-8 binds itself: homophilic cadherin-8 binding followed heterophilic cadherin-11 binding on the cadherin-8 surface [PMID:29742438].","molecular_requirements":"Cadherin-8 and -11 form one specificity group preferring each other [PMID:29742438].","affinity_potency":[],"species_and_systems":"Type II cadherin binding was measured by SPR and AUC on purified mouse EC1-EC2 fragments, with A431D cell co-culture; the human pair is inferred by orthology [PMID:29742438].","localisation_and_range":"Membrane-bound adhesion molecules, so contact-dependent (juxtacrine); neither partner is flagged secreted [flag].","caveats":"Single paper; SPR heterophilic affinities could not be determined because of competing homodimerization, so only relative response levels are available [PMID:29742438]. Human result is ortholog-projected, not measured.","key_references":[{"PMID":"29742438","why":"Homophilic and heterophilic cadherin-8 SPR"}],"covers":["LR002321","LR005619"]},"LR005102":{"pair":"CEACAM1 -> HAVCR2","headline":"Direct CEACAM1-TIM-3 binding by biochemical, biophysical and crystallographic methods, with PDB structure; also cis expression effects.","interaction_type":"direct binding","direction_and_effect":"CEACAM1 and TIM-3 bind in trans through their N-terminal domains [PMID:25363763]; the paper describes biochemical, biophysical and X-ray crystallography binding characterisation. UniProt states CEACAM1 inhibits T cells through its interaction with HAVCR2 [DB:UniProt]. Co-expressed CEACAM1 enhanced cell surface expression of TIM-3 in HEK293T cells [PMID:25363763].","molecular_requirements":"Membrane-distal IgV-like N-terminal domains mediate binding [PMID:25363763] [DB:UniProt]. PDB 5DZL has a chain of each partner [DB:PDB 5DZL].","affinity_potency":[],"species_and_systems":"Mouse Ceacam1-/- T-cell tolerance experiments and human cells/HEK293T in the same paper [PMID:25363763]; curated pair covers human and mouse entries.","localisation_and_range":"Both are membrane proteins; interaction in trans and cis on T cells [PMID:25363763].","caveats":"Evidence read as abstract with excerpts; one primary paper. Counts also include a review-only row and two abstract-insufficient rows. No affinity in our evidence.","key_references":[{"PMID":"25363763","why":"CEACAM1-TIM-3 binding in trans and cis; crystal structure"}],"covers":["LR001738","LR005102"]},"LR002330":{"pair":"CEACAM6 -> CEACAM1","headline":"CEACAM6 acts through CEACAM1 on T cells as an immunosuppressive axis; one abstract-level paper with ELISA binding in a figure legend.","interaction_type":"functional only","direction_and_effect":"CEACAM6's immunosuppressive activity was mediated by binding to CEACAM1 on activated tumor-specific T cells; the blocking antibody BAY 1834942 increased T-cell cytokine secretion and killing [PMID:35141051]. A legend describes dose-dependent binding of CEACAM6-Fc to recombinant human CEACAM1 by ELISA [PMID:35141051].","molecular_requirements":"Not reported in our evidence beyond the two partners.","affinity_potency":[],"species_and_systems":"Human proteins and cell lines in vitro [PMID:35141051]. IntAct lists protein array and solid phase assays [DB:IntAct].","localisation_and_range":"Tumor-cell surface CEACAM6 contacting T-cell CEACAM1 [PMID:35141051].","caveats":"Curated as functional_in_vitro. Antibody EC50 values describe antibody binding, not ligand-receptor affinity.","key_references":[{"PMID":"35141051","why":"CEACAM6 acts through CEACAM1; antibody blockade"}],"covers":["LR002330"]},"LR011150":{"pair":"CGA:CGB3 -> LHCGR","headline":"Heterodimer CGB3 with CGA on LHCGR is supported only by database records, mostly for CGA; no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists CGA-LHCGR as a full agonist; pKd range 9.899999618530273 to 11.800000190734863 [DB:GtoPdb]. Reactome records LH receptor:LH complexes [DB:Reactome]. Cryo-EM structures of chorionic gonadotropin-LHCGR-Gs exist [DB:PDB 7FIG] [DB:PDB 7FII].","molecular_requirements":"Ligand is a CGA:CGB3 heterodimer; the records name CGA and LH or CG, not this specific beta gene; GtoPdb does include a CGB3-LHCGR agonist record [DB:GtoPdb].","affinity_potency":[],"species_and_systems":"Human; species of experiments not reported in our evidence.","localisation_and_range":"Secreted ligand, transmembrane receptor [flag].","caveats":"Two pending rows, no curated paper. Database records are not specific to CGB3. BioGRID lists LHCGR-CGA affinity capture-western [DB:BioGRID].","key_references":[],"covers":["LR011150"]},"LR008996":{"pair":"CLCF1 -> CRLF1","headline":"CLCF1 and CRLF1 form an obligate secreted heterodimer; this is a ligand-ligand composition, not a receptor interaction.","interaction_type":"direct binding","direction_and_effect":"CLC/CLF was identified as a stable secreted heteromeric complex acting as a CNTFR ligand [PMID:10966616]. Direction is not meaningful: both partners are secreted subunits of one ligand [PMID:10966616].","molecular_requirements":"Obligate heterodimer; curator notes say CLF is needed for CLC secretion [PMID:10966616]. Reactome records the CRLF1:CLCF1 complex [DB:Reactome]; BioGRID and IntAct list pull-down, co-IP and affinity capture [DB:BioGRID][DB:IntAct].","affinity_potency":[],"species_and_systems":"Human; paper read as abstract only [PMID:10966616]. Structure available [DB:PDB 8D7H].","localisation_and_range":"Both proteins are flagged secreted [flag].","caveats":"Single paper, abstract only. The interaction is ligand-ligand, so the CLCF1 -> CRLF1 receptor framing is questionable. No affinity reported.","key_references":[{"PMID":"10966616","why":"Identifies CLC/CLF as a stable secreted complex"}],"covers":["LR008996"]},"LR000305":{"pair":"CNTF -> CNTFR","headline":"CNTF is the canonical agonist of CNTFR (with gp130/LIFR); direct binding shown in vitro; three abstract-only papers plus GtoPdb and PDB.","interaction_type":"direct binding","direction_and_effect":"GtoPdb lists CNTF as an agonist at CNTFR [DB:GtoPdb]. CNTFR is a non-signaling alpha chain and signals through gp130 and LIFR [PMID:10966616].","molecular_requirements":"CNTFR alone does not signal; gp130 and LIFR are the signalling beta chains [PMID:10966616]. The CNTF/CNTFR heterocomplex bound gp130 with an affinity of 3-5 x 10(-10)M [PMID:8627290]. Tools scoring this by the least-expressed subunit should use CNTFR plus both gp130 and LIFR.","affinity_potency":[{"value":"IC50 29 nM (human CNTF)","assay":"nonradioactive competitive binding vs biotinylated CNTF","system":"soluble gp130 and soluble CNTFR","cite":"PMID:7810882"},{"value":"IC50 2 nM (rat CNTF)","assay":"nonradioactive competitive binding vs biotinylated CNTF","system":"soluble gp130 and soluble CNTFR","cite":"PMID:7810882"},{"value":"3-5 x 10(-10)M","assay":"binding of CNTF/alpha CNTF receptor heterocomplex to gp130","system":"transfected cells, human cell lines","cite":"PMID:8627290"}],"species_and_systems":"Human cell lines and recombinant soluble receptors; rat CNTF was also tested [PMID:7810882][PMID:8627290]. Mouse pair is ortholog-inferred.","localisation_and_range":"CNTF is flagged secreted [flag]; soluble paracrine cytokine.","caveats":"All three papers read as abstracts only. The 29 and 2 nM values are IC50s from a competition assay, not Kd. The Nat Neurosci paper concerns the CLF/CLC complex as a second CNTFR ligand and does not test CNTF itself [PMID:10966616]. PDB 8D74 has CNTF and CNTFR chains [DB:PDB 8D74].","key_references":[{"PMID":"7810882","why":"Competitive binding of human and rat CNTF to soluble CNTFR/gp130"},{"PMID":"8627290","why":"CNTF/CNTFR heterocomplex binds gp130 with 3-5 x 10(-10)M"},{"PMID":"10966616","why":"CNTFR as non-signaling alpha chain with gp130 and LIFR"}],"covers":["LR000305","LR003811"]},"LR005111":{"pair":"CNTN1 -> NOTCH2","headline":"Functional evidence that Notch2 relays a CNTN1 signal, plus a generic Notch ligand paper; no direct binding measurement.","interaction_type":"functional only","direction_and_effect":"F3/contactin acts as a functional ligand of Notch in oligodendrocyte cells [PMID:14567914]. In airway epithelial exosomes, siRNA and gamma-secretase inhibition characterised Notch2 as necessary for relaying the CNTN1 signal to dendritic cells [PMID:33957164].","molecular_requirements":"Notch2 is necessary for the CNTN1 signal [PMID:33957164]; gamma-secretase-dependent pathway is implicated [PMID:33957164]. Reactome lists a CNTN1:NOTCH2 complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"OLN-93 cells with unspecified species [PMID:14567914]; airway epithelial exosomes and dendritic cells in an asthma setting [PMID:33957164]. Both species are ortholog-inferred.","localisation_and_range":"CNTN1 delivered via exosomes in the asthma study [PMID:33957164]; flagged transmembrane [flag].","caveats":"Both papers abstract-only. 14567914 refers to Notch generally, not NOTCH2 specifically. No binding data; BioGRID affinity capture-Western rests on 14567914 [DB:BioGRID].","key_references":[{"PMID":"33957164","why":"Notch2 necessary for CNTN1 exosome signal"},{"PMID":"14567914","why":"F3/contactin as Notch ligand"}],"covers":["LR001753","LR005111"]},"LR000314":{"pair":"COL11A1 -> ITGA2","headline":"Only a cell-based report that integrin a2b1/DDR2 bind collagen XI; abstract-level and not chain-specific for COL11A1.","interaction_type":"functional only","direction_and_effect":"Integrin a2b1 and DDR2, but not a11b1, mediated high-affinity binding of cancer-associated fibroblasts to collagen type XI [PMID:36233024].","molecular_requirements":"The a2b1 heterodimer, not ITGA2 alone, is what the paper names [PMID:36233024].","affinity_potency":[],"species_and_systems":"CAFs; species not reported in our evidence [PMID:36233024]. The human pair is ortholog-inferred.","localisation_and_range":"COL11A1 is annotated secreted and not transmembrane [flag].","caveats":"Abstract-only; the paper says collagen type XI without naming a chain, and does not isolate individual integrin subunits [PMID:36233024].","key_references":[{"PMID":"36233024","why":"Integrin a2b1 and DDR2 binding to collagen XI in CAFs"}],"covers":["LR000314","LR003820"]},"LR000323":{"pair":"COL1A1 -> DDR1","headline":"DDR1 is a collagen-activated receptor tyrosine kinase; type I collagen binds and activates it in three papers.","interaction_type":"direct binding","direction_and_effect":"Type I collagen bound DDR1-Fc by slot blot, with binding detectable at 3 mg loading [PMID:9659900]. Collagen types I, III, IV and V induced DDR1b tyrosine phosphorylation in 293 cells, an agonist effect needing native triple-helical collagen [PMID:9659899]. Collagen I also stimulated saturable DDR1 ectodomain shedding in carcinoma and transfected cells, reduced by a Src inhibitor [PMID:16440311].","molecular_requirements":"Receptor activation requires the native triple-helical structure of collagen; denatured collagen did not activate [PMID:9659899]. Collagen type I is the COL1A1/COL1A2 heterotrimer, so the evidence is not chain-specific (curator note).","affinity_potency":[],"species_and_systems":"Bovine dermal and human or mouse collagen I with human DDR1 in 293 cells and T-47D cells [PMID:9659900] [PMID:9659899]; species for the shedding paper not reported [PMID:16440311].","localisation_and_range":"Receptor is a membrane-bound tyrosine kinase; collagen is matrix, so signalling is by contact.","caveats":"Binding was slower to detect for DDR1 than DDR2 and activation required prolonged stimulation [PMID:9659900] [PMID:9659899]. The shedding paper was read as an abstract only. No affinity reported.","key_references":[{"PMID":"9659900","why":"Collagen I binds DDR1 and DDR2 Fc proteins"},{"PMID":"9659899","why":"Collagens activate DDR1 and DDR2 phosphorylation"},{"PMID":"16440311","why":"Collagen I triggers DDR1 ectodomain shedding"}],"covers":["LR000323","LR003829"]},"LR000332":{"pair":"COL1A2 -> ITGA11","headline":"Integrin alpha11 (as alpha11beta1) binds collagen type I-Sepharose in one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"alpha11beta1 bound collagen type I-Sepharose [PMID:10464311]. Annotated effect is stimulatory.","molecular_requirements":"The binder shown is the alpha11beta1 heterodimer, not ITGA11 alone [PMID:10464311].","affinity_potency":[],"species_and_systems":"Human alpha11 integrin, muscle cells [PMID:10464311].","localisation_and_range":"COL1A2 is flagged secreted and not transmembrane [flag]; type I collagen is an extracellular matrix ligand, so signalling is by cell contact with matrix (inferred from the flag; not stated in the papers read).","caveats":"Abstract-only. Ligand is collagen I heterotrimer; COL1A2 not isolated. No database support.","key_references":[{"PMID":"10464311","why":"alpha11beta1 binds collagen type I-Sepharose"}],"covers":["LR000332","LR003838"]},"LR000350":{"pair":"COL4A3 -> ITGAV","headline":"Tumstatin/alpha3NC1 binds integrin alphaVbeta3 in two papers; one binding paper, one mouse genetics.","interaction_type":"direct binding","direction_and_effect":"Recombinant alpha3NC1 binds alphaVbeta3 and alphaVbeta5 predominantly via its RGD site [PMID:14610079]; tumstatin's suppression of pathological angiogenesis requires alphaVbeta3 [PMID:12842087].","molecular_requirements":"The receptor is the alphaV:beta3 heterodimer [PMID:14610079]. The active form is the NC1 domain / tumstatin fragment, not intact COL4A3 [PMID:12842087].","affinity_potency":[],"species_and_systems":"Recombinant human domain in HEK293 and endothelial adhesion [PMID:14610079]; Col4a3- and Mmp9-knockout mouse tumour models [PMID:12842087].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Both papers abstract only. Non-RGD peptides were about 10-fold less potent than native protein [PMID:14610079]. Functional paper does not show direct binding.","key_references":[{"PMID":"14610079","why":"alphaVbeta3/beta5 bind RGD site of alpha3NC1"},{"PMID":"12842087","why":"Tumstatin requires alphaVbeta3 in mouse angiogenesis"}],"covers":["LR000350","LR003856"]},"LR002420":{"pair":"COL5A1 -> ITGA2","headline":"Collagen V is linked to alpha2beta1 only through patient fibroblast genetics in an abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Fibroblasts from patients with COL5A1 mutations show reduced alpha2beta1, named as the functional receptor of collagens V and III; purified collagen V restored the control phenotype [PMID:14970208].","molecular_requirements":"Receptor is the alpha2beta1 heterodimer; blocking antibodies to alpha2beta1 induced an EDS-like phenotype in control cells [PMID:14970208].","affinity_potency":[],"species_and_systems":"Human dermal fibroblasts [PMID:14970208].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Disease genetics and antibodies, not a binding assay; abstract only.","key_references":[{"PMID":"14970208","why":"Fibroblasts with COL5A1 mutations lose alpha2beta1"}],"covers":["LR002420","LR005699"]},"LR005120":{"pair":"CRTAM -> CADM1","headline":"Well supported: CRTAM and CADM1 bind directly (SPR, expression cloning, structure); membrane-bound adhesion pair.","interaction_type":"direct binding","direction_and_effect":"CRTAM was identified as a CADM1 ligand by expression cloning; CRTAM+ T cells bound CADM1 (Necl2)-expressing cells, inhibited by CRTAM-Ig, with no clear change in cytotoxicity in that assay [PMID:16091383]. UniProt states that interaction with CADM1 promotes NK cell cytotoxicity and IFNG secretion by CD8+ T cells in vitro and tumour rejection in vivo [DB:UniProt]. Directionality is adhesion-like; both are annotated receptors [flag].","molecular_requirements":"Both single chains; CRTAM is a cell-surface dimer, and the interaction competes with CRTAM and CADM1 homodimerisation [PMID:16091383, DB:UniProt].","affinity_potency":[{"value":"KD 3.3 nM","assay":"SPR imaging, CADM1-Fc analyte on immobilised CRTAM-Fc","system":"recombinant human Fc fusions","cite":"PMID:30131958"}],"species_and_systems":"Human recombinant proteins and cells; a PDB structure of the pair exists [DB:PDB 4H5S]. Mouse pair is ortholog-inferred. IntAct has cosedimentation and solid-phase records [DB:IntAct].","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag]; interaction is membrane-to-membrane (juxtacrine, contact).","caveats":"Both partners are annotated as receptors, so the ligand/receptor direction is arbitrary [flag]. The 2005 paper was read as abstract only [PMID:16091383]. Affinity is from Fc-fusion SPR, not native cells.","key_references":[{"PMID":"30131958","why":"SPRi screen with CRTAM showing the highest affinity to CADM1"},{"PMID":"16091383","why":"expression cloning of CADM1 as CRTAM ligand"}],"covers":["LR001762","LR005120"]},"LR000404":{"pair":"CXCL13 -> CXCR5","headline":"Well-supported canonical pair: CXCL13 activates CXCR5 in several papers, with binding, chemotaxis and calcium data and curated database records.","interaction_type":"direct binding","direction_and_effect":"CXCL13 (BCA-1) induced chemotaxis and Ca2+ mobilisation in BLR1/CXCR5-transfected cells and attracted human blood B lymphocytes; no activity was seen with 10 CXC and 19 CC chemokines, lymphotactin, neurotactin/fractalkine and other peptide ligands [PMID:9463416]. An independent paper showed BLC stimulates calcium influx and chemotaxis in BLR-1-transfected cells [PMID:9486651]. GtoPdb lists CXCL13 as a full agonist [DB:GtoPdb].","molecular_requirements":"CXCR5 alone is sufficient in transfected cells [PMID:9463416][PMID:9486651]. EBI2 co-expression forms CXCR5/EBI2 heterodimers that reduce CXCL13 affinity and G-protein efficacy [PMID:22913878].","affinity_potency":[{"value":"KD 5.05\u00d710(-8) M","assay":"CXCL13 binding to CXCR5 alone","system":"HEK293T cells","cite":"PMID:22913878"},{"value":"KD 1.49\u00d710(-7) M","assay":"CXCL13 binding to CXCR5/EBI2 co-expressing cells","system":"HEK293T cells","cite":"PMID:22913878"}],"species_and_systems":"Murine pre-B 300-19 cells transfected with BLR1 and human blood B cells [PMID:9463416]; human HEK293T cells and primary activated murine B cells [PMID:22913878]; species not specified in [PMID:9486651]. Mouse pair is also listed as a direct (not projected) interaction.","localisation_and_range":"CXCL13 is flagged secreted [flag]; soluble chemokine acting on a cell-surface GPCR, guiding B cells to follicles [PMID:9486651].","caveats":"All three papers were read as abstracts only. Receptor heterodimerisation with EBI2 lowers apparent affinity, relevant where EBI2 is co-expressed [PMID:22913878]. Reactome records binding and complex [DB:Reactome].","key_references":[{"PMID":"9463416","why":"Identifies CXCL13 as selective BLR1/CXCR5 agonist with negative tests on 29 chemokines"},{"PMID":"9486651","why":"Independent report of BLC activating BLR-1 by calcium influx and chemotaxis"},{"PMID":"22913878","why":"KD values and CXCR5/EBI2 heterodimer effect on CXCL13 binding"}],"covers":["LR000404","LR003909"]},"LR000413":{"pair":"CXCL5 -> CXCR1","headline":"Weak, CXCR2-preferential agonism at human CXCR1; a mouse CXCR1 study reports no response to CXCL5.","interaction_type":"conflicting","direction_and_effect":"CXCL5 acts as a weak agonist at human CXCR1: three-fold higher concentrations were needed for a calcium response than at CXCR2 [PMID:9692902]. Truncated CXCL5 is more potent through CXCR1 and CXCR2 in neutrophils, monocytes and THP-1 [PMID:33688078].","molecular_requirements":"Not reported beyond N-terminal truncation increasing potency [PMID:33688078].","affinity_potency":[],"species_and_systems":"Human CXCR1-transfected cells [PMID:9692902]; human neutrophils, monocytes and THP-1 cells [PMID:33688078]. Negative result is in the mouse receptor [PMID:17197447]; the mouse pair here is ortholog-inferred.","localisation_and_range":"Ligand is flagged secreted and receptor flagged transmembrane [flag], so paracrine signalling to a cell-surface receptor is implied; paper text does not address range.","caveats":"ENA-78 did not compete for 125I-IL-8 binding to CXCR1 [PMID:9692902]. Murine CXCR1 was not responsive to CXCL5 [PMID:17197447]. GRO-family and ENA-78 competed weakly at IL8RA [PMID:8702798]. All abstract-only.","key_references":[{"PMID":"9692902","why":"Reduced CXCL5 activity at CXCR1 vs CXCR2"},{"PMID":"33688078","why":"Truncated CXCL5 acts through CXCR1 and CXCR2"},{"PMID":"17197447","why":"Mouse CXCR1 does not respond to CXCL5"}],"covers":["LR000413","LR003913"]},"LR000431":{"pair":"DEFB1 -> CCR6","headline":"DEFB1 is reported to bind CCR6 and signal; beta-defensin competes with LARC binding and drives sperm Ca2+ mobilisation.","interaction_type":"direct binding","direction_and_effect":"Agonist: beta-defensin displaced iodinated LARC from CCR6-transfected cells and drove pertussis-toxin-sensitive chemotaxis [PMID:10521347]; DEFB1 triggered Ca2+ mobilisation in sperm via CCR6 [PMID:25122636].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human CCR6-transfected cells and dendritic/memory T cells [PMID:10521347]; human sperm [PMID:25122636].","localisation_and_range":"DEFB1 flagged secreted; CCR6 transmembrane receptor [flag].","caveats":"Both papers read as abstracts; the first paper's beta-defensin is not specified to be DEFB1 in our evidence. Reactome and UniProt agree [DB:Reactome R-HSA-1471343] [DB:UniProt P51684]. Two pending rows not shown.","key_references":[{"PMID":"10521347","why":"LARC displacement at CCR6, chemotaxis"},{"PMID":"25122636","why":"DEFB1-CCR6 Ca2+ mobilisation in sperm"}],"covers":["LR000431"]},"LR000440":{"pair":"DKK1 -> KREMEN1","headline":"Well supported direct high-affinity binding and a crystal structure; Kremen1 acts with DKK1 to block Wnt signalling.","interaction_type":"direct binding","direction_and_effect":"Kremen1 and Kremen2 are high-affinity Dkk1 receptors that cooperate with Dkk1 to block Wnt/beta-catenin signalling [PMID:12050670]. Krm1 is described as a co-receptor for Dkk proteins [PMID:27524201].","molecular_requirements":"DKK1 CRD2 is required and sufficient for binding to KRM1; SPR measured low micromolar affinity between full-length DKK1 and KRM1ECD [PMID:27524201]. UniProt notes interaction with DKK1 [DB:UniProt].","affinity_potency":[{"value":"low micromolar","assay":"surface plasmon resonance","system":"full-length DKK1 and immobilized human KRM1ECD","cite":"PMID:27524201"}],"species_and_systems":"Recombinant human ectodomain structures [PMID:27524201]; the 2002 abstract does not name species [PMID:12050670]. Database: PDB 5FWW, IntAct [DB:PDB 5FWW] [DB:IntAct].","localisation_and_range":"KREMEN1 is flagged as a receptor, not secreted [flag].","caveats":"The 2002 paper's evidence sentence concerns both Kremen1 and Kremen2 and was read as abstract only. The structure paper's affinity is a low micromolar range, not a precise value. One row pending.","key_references":[{"PMID":"12050670","why":"Kremen1/2 are high-affinity Dkk1 receptors"},{"PMID":"27524201","why":"Kremen1 ectodomain structure; DKK1 CRD2 binding by SPR"}],"covers":["LR000440","LR003932"]},"LR002501":{"pair":"DSG2 -> DSC2","headline":"DSG2 -> DSC2: heterophilic desmosomal cadherin binding, supported by a single family-wide paper.","interaction_type":"direct binding","direction_and_effect":"The paper reports that all desmogleins form adhesive dimers with all desmocollins, with affinities characteristic of each Dsg:Dsc pair, so this pair is covered by the family-wise heterophilic result [PMID:27298358]. Binding is trans-cellular and heterodimers are called the fundamental adhesive unit of desmosomes [PMID:27298358].","molecular_requirements":"Ectodomains of one Dsg and one Dsc are sufficient for dimer formation in the reported solution biophysics and bead aggregation; binding uses a strand-swap mechanism with charge-based heterophilic preference [PMID:27298358]. No further subunits or co-receptors reported.","affinity_potency":[],"species_and_systems":"Experiments used human proteins (solution biophysics, SPR and coated-bead aggregation) [PMID:27298358]. Pair is recorded for: human, mouse (ortholog-projected). The mouse entry is projected from human evidence.","localisation_and_range":"Membrane-bound desmosomal cadherins acting in trans between adjacent cells (juxtacrine/contact) [PMID:27298358]; entity flags mark both as receptors and transmembrane where set [flag].","caveats":"Curators read only the abstract; the paper's family-wide statement is applied to this pair, one of 25 companion rows, and no pair-specific affinity is in our dossier. The crystal structures cited cover Dsg2, Dsg3, Dsc1 and Dsc2 only [PMID:27298358]. Database records also exist (BioGRID, IntAct, PDB, UniProt), which are not independent of the evidence above. [DB:BioGRID] [DB:IntAct] [DB:PDB 5J5J] [DB:PDB 7A7D] [DB:UniProt]","key_references":[{"PMID":"27298358","why":"Family-wise Dsg:Dsc heterophilic binding by biophysics, SPR, bead aggregation and crystal structures"}],"covers":["LR002501","LR005769"]},"LR000503":{"pair":"EFNA5 -> EPHA5","headline":"Ephrin-A5 is named as an EphA5 ligand in adult mouse hippocampus; weak paper support, database records add some.","interaction_type":"functional only","direction_and_effect":"EphA5 and ephrin-A ligands (2 and 5) are expressed in adult mouse hippocampus; receptor- and ligand-binding-site immunoadhesins were used to target EphA function [PMID:10531456]. UniProt says EFNA5-EPHA5 interaction mediates islet cell communication regulating glucose-stimulated insulin secretion [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Adult mouse hippocampus [PMID:10531456]; the human pair is ortholog-inferred.","localisation_and_range":"Both flagged membrane-bound [flag].","caveats":"The confirmed paper shows co-expression and immunoadhesin effects, not direct binding; abstract-only read. IntAct lists affinity chromatography and coimmunoprecipitation records [DB:IntAct].","key_references":[{"PMID":"10531456","why":"EphA5 and ephrin-A2/A5 in adult hippocampus with immunoadhesins"}],"covers":["LR000503","LR003994"]},"LR000512":{"pair":"EFNB1 -> EPHB4","headline":"Single functional mouse paper: EFNB1 promotes IL-21 in T follicular helper cells mainly through EPHB4; no binding data.","interaction_type":"functional only","direction_and_effect":"EFNB1 promoted interleukin-21 production from germinal-centre TFH cells by signalling predominantly through EPHB4; it also inhibited T-B adhesion through EPHB6 [PMID:28408722].","molecular_requirements":"Receptor usage is context-split: EPHB4 for IL-21, EPHB6 for repulsion [PMID:28408722].","affinity_potency":[],"species_and_systems":"Mouse germinal-centre TFH cells; the human pair is ortholog-inferred [PMID:28408722].","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine).","caveats":"Abstract only; one paper; no binding or affinity data. 'Predominantly' implies other receptors may contribute [PMID:28408722].","key_references":[{"PMID":"28408722","why":"EFNB1 acts via EPHB4 to promote IL-21 in GC TFH cells"}],"covers":["LR000512","LR004003"]},"LR004004":{"pair":"EFNB1 -> EPHB6","headline":"Ligand-induced EphB6 phosphorylation shown, but indirect: it needs a kinase-active partner such as EphB1.","interaction_type":"functional only","direction_and_effect":"Ephrin-B1 stimulation induced tyrosine phosphorylation of EphB6 despite its lack of kinase activity [PMID:11713248]. Annotated stimulatory.","molecular_requirements":"EphB6 is catalytically inactive; EphB1 transphosphorylated it in a ligand-dependent way requiring EphB1 catalytic activity, and the two formed a stable hetero-complex [PMID:11713248]. A complex-level (EphB1+EphB6) readout, so a single-subunit expression score may mislead.","affinity_potency":[],"species_and_systems":"Recombinant overexpression; curator annotation lists human [PMID:11713248].","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine). The receptor is flagged as secreted too [flag], which is unexplained.","caveats":"Abstract only. Direct ephrin-B1 binding to EphB6 was not shown; phosphorylation was mediated through EphB1 [PMID:11713248].","key_references":[{"PMID":"11713248","why":"Ephrin-B1 induces EphB6 phosphorylation via EphB1 cross-talk"}],"covers":["LR000513","LR004004"]},"LR000521":{"pair":"EFNB2 -> EPHB4","headline":"Best supported of this batch: sub-nanomolar binding, structure, and functional data in several systems.","interaction_type":"direct binding","direction_and_effect":"Ephrin-B2 expressing COS-7 cells induced tyrosine phosphorylation of Htk in 3T3 cells [PMID:7534404]. Ephrin-B2 stromal cells made EphB4+ progenitors detach and differentiate to erythroid cells [PMID:12051776]. Coexpressed (cis) ephrin-B2 inhibits EphB4 in cancer cells [PMID:24348920]. EphB4-Fc activation moved ephrinB2 to endothelial junctions [PMID:16357318].","molecular_requirements":"Trans activation needs ephrin-B2 on a neighbouring cell; cis coexpression attenuates it [PMID:24348920].","affinity_potency":[{"value":"Kd 535 pM","assay":"binding competition, Htk-Fc to Htk ligand","system":"ligand expression-cloned from a murine kidney mesangial cell line","cite":"PMID:7534404"}],"species_and_systems":"Mixed: murine-derived ligand [PMID:7534404], human umbilical cord blood cells [PMID:12051776], cultured endothelial cells [PMID:16357318]. Structure PDB 2HLE [DB:PDB 2HLE]; BioGRID and IntAct SPR records [DB:BioGRID] [DB:IntAct].","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine).","caveats":"Ten confirmed rows; five shown. The Kd paper does not name ephrin-B2 in its abstract (curator identification). ELISA quote was browser-read and unverified [PMID:22568954].","key_references":[{"PMID":"7534404","why":"Ligand cloned; Kd 535 pM; receptor phosphorylation"},{"PMID":"24348920","why":"cis inhibition of EphB4 by ephrin-B2"},{"PMID":"12051776","why":"Ephrin-B2 stroma drives EphB4+ erythroid differentiation"}],"covers":["LR000521","LR004012"]},"LR004013":{"pair":"EFNB2 -> EPHB6","headline":"Direct, saturable EphB6-Fc binding to ephrin-B2 (not ephrin-B1) in one paper, plus an ELISA.","interaction_type":"direct binding","direction_and_effect":"EphB6-Fc showed high-affinity saturable binding to ephrin-B2-transfected COS cells but not ephrin-B1 [PMID:10648835]. Ephrin-B2 Fc binds best to all EphB receptors in ELISA [PMID:22568954].","molecular_requirements":"not reported in our evidence. EphB6 is catalytically inactive in other work in this batch, so signalling likely needs partners (not shown here).","affinity_potency":[],"species_and_systems":"Human EphB6-Fc, COS cells, Reh pro-B leukemic line; EphB6 and ephrin-B2 expressed in human thymus [PMID:10648835]. Interaction class is Ligand-Receptor with no effect annotation.","localisation_and_range":"Both partners are annotated as transmembrane, non-secreted [flag], so signalling would be by cell-cell contact (juxtacrine). The receptor is also flagged secreted [flag].","caveats":"Abstract hedges: the ligand is called a 'candidate' and 'may be a physiological ligand' [PMID:10648835]. No numeric affinity. ELISA quote is unverified.","key_references":[{"PMID":"10648835","why":"EphB6-Fc binds ephrin-B2, not ephrin-B1"},{"PMID":"22568954","why":"ELISA across ephrin-Bs and EphB receptors"}],"covers":["LR000522","LR004013"]},"LR004022":{"pair":"EGF -> EGFR","headline":"EGF is the canonical, well-characterised agonist of EGFR, with structural, binding and functional evidence.","interaction_type":"direct binding","direction_and_effect":"EGF binds EGFR and induces receptor dimerisation and kinase activation [PMID:8639530]. A 2:2 crystal structure of human EGF with the EGFR extracellular region shows EGF docked between domains I and III, with receptor-mediated dimerisation [PMID:12297050]. In the unliganded autoinhibited structure, EGF binding must promote a large domain rearrangement to activate the receptor [PMID:12620237]. Downstream effects include EGFR polyubiquitination [PMID:10788520] and PLD1 activation (2.8-fold) [PMID:9837959].","molecular_requirements":"EGFR alone is sufficient; the extracellular region (domains I-IV) binds EGF and dimerises [PMID:12297050]. Native EGF does not gain high affinity for ErbB-2/ErbB-3 heterodimers unless its N-terminal region is replaced [PMID:12093292].","affinity_potency":[],"species_and_systems":"Human proteins and cells (A431, HEK293, 32D lines) [PMID:6289330][PMID:36505413]. Co-crystal structures, NanoBRET binding in HEK293 cells, sedimentation, cross-linking [PMID:36505413][PMID:8639530]. Also in BioGRID, IntAct, PDB, Reactome, GtoPdb [DB:GtoPdb].","localisation_and_range":"EGF is secreted and EGFR is transmembrane [flag]; paracrine or autocrine ligand to a membrane receptor.","caveats":"Many curated papers use EGF only as a trigger for EGFR activation rather than studying binding [PMID:11228164][PMID:15620700]. GtoPdb lists affinity in pKi but no value is given in our evidence [DB:GtoPdb]. Only 10 of 22 judged rows are shown here.","key_references":[{"PMID":"12297050","why":"Crystal structure of the EGF-EGFR extracellular complex"},{"PMID":"36505413","why":"NanoBRET EGF binding to full-length EGFR; nanobody competition"},{"PMID":"8639530","why":"EGF binding, dimerisation and kinase activation measured together"}],"covers":["LR000531","LR004022"]},"LR004031":{"pair":"F10 -> ITGB2","headline":"Factor X binds Mac-1 on stimulated human monocytes; ITGB2 is supported only through the Mac-1 heterodimer.","interaction_type":"direct binding","direction_and_effect":"125I-factor X bound saturably to stimulated human monocytes and was cross-linked to Mac-1, immunoprecipitated with the anti-alpha subunit antibody OKM10 [PMID:2835359].","molecular_requirements":"Evidence is for the Mac-1 receptor; the antibody targets the alpha subunit, so a role for ITGB2 specifically is not shown in our evidence. Requires Ca2+ [PMID:2835359].","affinity_potency":[{"value":"Kd 21.8-44.9 nM","assay":"saturable 125I-factor X binding","system":"ADP- or ionomycin-stimulated human monocytes","cite":"PMID:2835359"}],"species_and_systems":"Human factor X and monocytes [PMID:2835359]; mouse pair ortholog-inferred [flag].","localisation_and_range":"F10 flagged secreted [flag].","caveats":"Abstract-only single paper; beta-chain-only evidence absent. ITGB2 pairs with ITGAM here by inheritance.","key_references":[{"PMID":"2835359","why":"Factor X binds Mac-1 on monocytes"}],"covers":["LR000540","LR004031"]},"LR004040":{"pair":"F7 -> F3","headline":"Factor VIIa binds cell-bound tissue factor; well supported by structure and database records.","interaction_type":"direct binding","direction_and_effect":"Association of factor VIIa with cell-bound tissue factor initiates the extrinsic coagulation pathway [PMID:9925787]. Annotation lists the effect as stimulatory.","molecular_requirements":"In the 2.1 A crystal structure, TF-bound VIIa is extended, with its light chain wrapping around the two-domain TF cofactor; the complex was inhibitor-stabilised with a BPTI mutant [PMID:9925787]. Many PDB structures exist [DB:PDB 1DAN] [DB:PDB 1J9C].","affinity_potency":[],"species_and_systems":"Human proteins in the structure [PMID:9925787]; also IntAct X-ray and ELISA records [DB:IntAct P08709-P13726].","localisation_and_range":"Reactome places the complex at the plasma membrane [DB:Reactome R-HSA-140734]; F7 annotated secreted [flag].","caveats":"One paper judged, abstract-only; its structure includes an inhibitor and gives no affinity for F7-F3. TF acts as a cofactor, not a signalling-only receptor.","key_references":[{"PMID":"9925787","why":"2.1 A crystal structure of TF-VIIa-inhibitor complex"}],"covers":["LR000549","LR004040"]},"LR008978":{"pair":"FGB -> ITGB2","headline":"Functional-only support: one abstract-read paper shows fibrinogen adhesion of eosinophils blocked by anti-alphaMbeta2.","interaction_type":"functional only","direction_and_effect":"Airway eosinophils adhered to fibrinogen among other ligands, and adhesion was blocked by anti-alphaMbeta2; IL-5 reproduced the phenotype in blood eosinophils [PMID:16601240]. Effect direction is not reported in our evidence.","molecular_requirements":"The assayed receptor is the alphaMbeta2 (ITGAM:ITGB2) heterodimer, so ITGB2 acts together with ITGAM; the ligand is the fibrinogen heterohexamer (FGA/FGB/FGG), encoded here by its chains [PMID:16601240].","affinity_potency":[],"species_and_systems":"Eosinophils from airway and blood; species not stated in the abstract [PMID:16601240].","localisation_and_range":"FGB is flagged secreted [flag]; ITGB2 is flagged as a non-secreted receptor [flag].","caveats":"Adhesion assay, not binding. Abstract only. Same paper as the FGB -> ITGAM pair, so it is not independent evidence for ITGB2 alone. No database support.","key_references":[{"PMID":"16601240","why":"Only paper: eosinophil adhesion to fibrinogen blocked by anti-alphaMbeta2"}],"covers":["LR008978"]},"LR000611":{"pair":"FGF2 -> FGFR4","headline":"FGF2 binds FGFR4 with high affinity in human-protein assays; evidence is abstract-level.","interaction_type":"direct binding","direction_and_effect":"Basic FGF (FGF2) binds with high affinity to FGFR1, FGFR2 and FGFR4 [PMID:8530375]; confirmed as binding well in a second study [PMID:10950949]. BaF3 assays showed FGF2 activity on FGFR-expressing lines [PMID:8663044]. Dossier modulatory effect: stimulatory [flag].","molecular_requirements":"Not reported for FGFR4 specifically in our evidence (heparin, co-receptors).","affinity_potency":[],"species_and_systems":"Human ligand and receptor in binding studies [PMID:8530375][PMID:10950949]; BaF3 species not stated [PMID:8663044]. No database records.","localisation_and_range":"FGF2 and FGFR4 both annotated secreted and transmembrane-capable [flag].","caveats":"All three papers read as abstract only. The FGFR4-specific result in the BaF3 paper is not given in the evidence sentence. No affinity value reported.","key_references":[{"PMID":"8530375","why":"bFGF binds FGFR4 with high affinity"},{"PMID":"10950949","why":"FGF-2 binds FGFR4 well"}],"covers":["LR000611","LR004095"]},"LR000602":{"pair":"FGF22 -> FGFR2","headline":"FGF22 strongly activates FGFR2b in a BaF3 mitogenic screen; functional evidence only.","interaction_type":"functional only","direction_and_effect":"FGFs 7, 10 and 22 all strongly activated FGFR2b [PMID:16597617]; stimulatory.","molecular_requirements":"The b splice form of FGFR2 is the responsive isoform in the sentence cited [PMID:16597617].","affinity_potency":[],"species_and_systems":"BaF3 cells; species unspecified [PMID:16597617].","localisation_and_range":"FGF22 secreted [flag]; FGFR2 transmembrane [flag].","caveats":"Single paper, functional readout only, quote browser-read and unverified [PMID:16597617]. Two further rows (review_only, abstract_insufficient) not shown. Mouse pair is projected from human.","key_references":[{"PMID":"16597617","why":"BaF3 receptor-specificity screen of the FGF family"}],"covers":["LR000602","LR004086"]},"LR004103":{"pair":"FGF3 -> FGFR1","headline":"FGF3 binds FGFR1 IIIb with high affinity; weak or no binding to FGFR1c.","interaction_type":"direct binding","direction_and_effect":"Fgf3 bound the IIIb isoforms of FgfR1 and FgfR2 with high affinity by receptor binding competition [PMID:7592624]; FGF3 activates b splice forms of FGFR1 and 2 in BaF3 cells [PMID:8663044]. Curated agonist [PMID:7592624].","molecular_requirements":"IIIb isoform of FGFR1 only; no competition seen for FgfR1 IIIc [PMID:7592624]. Heparin dependence varied between cell lines [PMID:7592624].","affinity_potency":[{"value":"ID50 = approximately 0.8 nM","assay":"receptor binding competition vs 125I-Fgf1","system":"IIIb isoforms of FgfR1 and FgfR2 (shared value)","cite":"PMID:7592624"}],"species_and_systems":"Purified mouse fgf3 protein per the abstract [PMID:7592624]; BaF3 screen species unspecified [PMID:8663044].","localisation_and_range":"FGFR1 transmembrane [flag]; localisation otherwise not reported.","caveats":"Gene-level pair hides isoform specificity. The ID50 is shared with FgfR2 in the abstract. Abstract-only readings. Human pair is ortholog-inferred.","key_references":[{"PMID":"7592624","why":"High-affinity binding of Fgf3 to IIIb isoforms"},{"PMID":"8663044","why":"BaF3 mitogenic screen"}],"covers":["LR000619","LR004103"]},"LR000620":{"pair":"FGF3 -> FGFR2","headline":"FGF3 binds FGFR2 IIIb with high affinity and FGFR2 IIIc with lower affinity; direct binding plus mitogenic evidence.","interaction_type":"direct binding","direction_and_effect":"Fgf3 bound the IIIb isoforms of FgfR1 and FgfR2 with high affinity and FgfR2 IIIc with lower affinity [PMID:7592624]. FGF3 activates b splice forms of FGFR1 and 2 [PMID:8663044]. Stimulatory.","molecular_requirements":"IIIb preferred; IIIc weaker [PMID:7592624].","affinity_potency":[{"value":"ID50 = approximately 0.8 nM","assay":"binding competition","system":"IIIb isoforms of FgfR1 and FgfR2","cite":"PMID:7592624"},{"value":"ID50 = approximately 9 nM","assay":"binding competition","system":"FgfR2 IIIc","cite":"PMID:7592624"}],"species_and_systems":"Purified mouse fgf3 [PMID:7592624]; BaF3 screen species unspecified [PMID:8663044].","localisation_and_range":"FGFR2 transmembrane [flag].","caveats":"Abstract-only readings; ID50 values are approximate. Human pair is ortholog-inferred; mouse pair is direct.","key_references":[{"PMID":"7592624","why":"Affinity of Fgf3 for FgfR2 IIIb and IIIc"},{"PMID":"8663044","why":"BaF3 mitogenic screen"}],"covers":["LR000620","LR004104"]},"LR004112":{"pair":"FGF5 -> FGFR3","headline":"Only a BaF3 survey statement supports this pair; evidence for FGFR3 specifically is thin.","interaction_type":"functional only","direction_and_effect":"The BaF3 mitogenic survey states that FGFs 4, 5, 6 and 8 specifically activate c receptor splice forms [PMID:8663044]; whether FGFR3c was a responder is not shown in the quoted evidence.","molecular_requirements":"Splice-form (c) selectivity is described [PMID:8663044]; other requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"BaF3 mitogenic assays on FGFR-expressing cell lines; species of ligand and receptor listed as unspecified [PMID:8663044]. Mouse pair is projected from human.","localisation_and_range":"Localisation is not reported in our evidence.","caveats":"Single abstract-only paper with a browser-read quote pending spot-check; no binding data, no FGFR3-specific statement, no database records.","key_references":[{"PMID":"8663044","why":"BaF3 survey, FGF5 activates c splice forms"}],"covers":["LR000628","LR004112"]},"LR004121":{"pair":"FGF8 -> FGFR1","headline":"FGF8 activates FGFR1c in BaF3 assays; one other paper conflicts on binding; AIGF/FGFR1 functional support.","interaction_type":"conflicting","direction_and_effect":"FGF8 subfamily members specifically activated FGFRs 1c, 2c and 3c and FGFR4 (4\u0394) in BaF3 cells [PMID:16597617]. Mouse AIGF (FGF8) caused FGFR1-dependent inhibition of differentiation in L6 cells expressing an FGFR1 variant [PMID:8290257].","molecular_requirements":"c splice form of FGFR1 is the responsive isoform [PMID:16597617]. BioGRID, IntAct (surface plasmon resonance) and UniProt records exist [DB:BioGRID][DB:IntAct][DB:UniProt].","affinity_potency":[],"species_and_systems":"BaF3 cells, species unspecified [PMID:16597617]; mouse SC-3-derived FGFR1 variant in L6 cells, abstract only [PMID:8290257]. Human and mouse pairs are both non-inferred.","localisation_and_range":"Localisation is not reported in our evidence.","caveats":"The FGFR1 construct in PMID:8290257 is a variant, and the interaction is inferred from a functional assay.","key_references":[{"PMID":"16597617","why":"FGF8 activates FGFR1c in BaF3"},{"PMID":"8290257","why":"AIGF (FGF8) dependent FGFR1 effect in L6 cells"}],"covers":["LR000637","LR004121"]},"LR004130":{"pair":"FGG -> ITGAV","headline":"Fibrinogen is recognised by alphaVbeta3; support is one trophoblast paper plus structural database records.","interaction_type":"functional only","direction_and_effect":"Fibrinogen is recognised by alphaVbeta3 and alphaIIbbeta3 but not alpha5beta1 in trophoblast adhesion and migration [PMID:15031111].","molecular_requirements":"The receptor is the alphaV/beta3 heterodimer; ITGAV alone is not shown [PMID:15031111].","affinity_potency":[],"species_and_systems":"Human fibrinogen on mouse trophoblast cells [PMID:15031111]. Both pairs ortholog-inferred.","localisation_and_range":"FGG is flagged secreted [flag].","caveats":"The trophoblast sentence cites earlier work as background rather than showing it, so direct alphaV evidence is weak [PMID:15031111]. Database records (PDB 2VDO, IntAct ELISA) are for the integrin and fibrinogen [DB:PDB 2VDO][DB:IntAct][DB:BioGRID]; the PDB entries are alphaIIbbeta3-related and may not reflect alphaV.","key_references":[{"PMID":"15031111","why":"Trophoblast adhesion to fibrinogen via beta3 integrins"}],"covers":["LR000646","LR004130"]},"LR011015":{"pair":"FMOD -> TGFB1","headline":"Only a BioGRID reconstituted-complex record supports this pair; no curated paper confirms it.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID records a reconstituted complex between TGFB1 and FMOD [DB:BioGRID]. The entry is annotated inhibitory, but no paper in our evidence shows the mechanism or direction.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"TGFB1 is flagged secreted and not transmembrane [flag]; FMOD flags are absent.","caveats":"Seven papers were judged, none confirmed: 1 review-only, 2 different entity, 4 abstract-insufficient. Support is one database record. FMOD acts here as a ligand for another secreted ligand, so a conventional receptor role for TGFB1 is unsupported.","key_references":[{"PMID":"8093006","why":"PMID attached to the BioGRID reconstituted-complex record (not a curated paper)"}],"covers":["LR011015"]},"LR012113":{"pair":"FST -> INHA:INHBA","headline":"Follistatin binds activin A (INHBA); structural and database support, but this dossier targets the inhibin A complex.","interaction_type":"direct binding","direction_and_effect":"Reactome records follistatin binding activin [DB:Reactome R-HSA-2473184]; UniProt lists FST interaction with activin A/INHBA [DB:UniProt]. Follistatin acts as an inhibitor of activin signalling (modulatory flag Inhibitory) [flag].","molecular_requirements":"Co-crystal structures: follistatin:activin (PDB 2B0U) and activin:follistatin 315 (PDB 2P6A) [DB:PDB 2B0U, DB:PDB 2P6A]. Evidence concerns INHBA; INHA involvement is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human structures; BioGRID reconstituted complex [DB:BioGRID].","localisation_and_range":"Receptor-side entity flagged secreted [flag].","caveats":"Three papers pending; no verified papers. The ligand-binding partner is activin (INHBA homodimer), not demonstrated for the INHA:INHBA inhibin heterodimer. Affinity not reported.","key_references":[],"covers":["LR012113"]},"LR011213":{"pair":"GDF1 -> TGFBR1","headline":"Database-asserted only: GtoPdb lists an agonist action; no confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists GDF1 as an agonist at TGFBR1 [DB:GtoPdb]; no paper confirms it in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental system reported in our evidence.","localisation_and_range":"GDF1 is flagged secreted [flag].","caveats":"No confirmed paper. One paper was judged different_entity. Affinity and species are not reported in our evidence.","key_references":[],"covers":["LR011213"]},"LR000701":{"pair":"GDF5 -> ROR2","headline":"Indirect only: Ror2 forms a ligand-independent complex with GDF5's receptor BRI-b and modulates GDF5 signalling; no direct GDF5-Ror2 binding shown.","interaction_type":"functional only","direction_and_effect":"Ror2 modulates GDF5 signalling by inhibiting Smad1/5 signalling and activating a Smad-independent pathway, both needed for chondrogenic differentiation in ATDC5 cells [PMID:15569154]. Overall effect is modulatory rather than agonist.","molecular_requirements":"Ror2 and BRI-b (BMPR1B) form a ligand-independent heteromeric complex that needs Ror2's frizzled-like CRD domain, and Ror2 is transphosphorylated by BRI-b [PMID:15569154]. GDF5 acts through BRI-b in this model.","affinity_potency":[],"species_and_systems":"ATDC5 cells and Ror2, BRI-b and Gdf5 deficient mouse crosses [PMID:15569154]. The mouse pair is listed directly; the human pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged secreted [flag], so signalling is expected to be paracrine; not otherwise reported in our evidence.","caveats":"Only one paper, read as an abstract; it does not demonstrate GDF5 binding to Ror2. Treat as a co-receptor or modulator via BMPR1B, not as a direct receptor. No database records.","key_references":[{"PMID":"15569154","why":"Ror2/BRI-b complex modulates GDF5 signalling"}],"covers":["LR000701","LR004185"]},"LR011222":{"pair":"GDF7 -> ACVR1C","headline":"GDF7 -> ACVR1C rests on a GtoPdb agonist record alone; no paper evidence.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb records the interaction as Agonist, action Agonist, with no affinity units [DB:GtoPdb]. No curator-verified paper supports it.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted and the receptor chain(s) as receptor [flag], which would imply paracrine signalling to a membrane receptor; localisation is not otherwise reported in our evidence.","caveats":"Support is a database assertion only. No papers were judged.","key_references":[],"covers":["LR011222"]},"LR000710":{"pair":"GDNF -> GFRA1","headline":"Well supported direct binding: GFRA1 is the high-affinity GDNF binding receptor that then recruits RET.","interaction_type":"direct binding","direction_and_effect":"GDNFR-alpha (GFRA1) binds GDNF specifically and mediates Ret activation [PMID:8674117]. Both GDNF and neurturin bound GFR alpha1-Fc bodies with similar affinity [PMID:9883723]. Reactome, BioGRID, UniProt and PDB 6Q2N agree [DB:Reactome][DB:BioGRID][DB:UniProt][DB:PDB 6Q2N].","molecular_requirements":"GFRA1 acts as co-receptor for RET: UniProt describes a 2:2:2 GDNF:GFRA1:RET ternary complex [DB:UniProt]. Soluble GFRA1 plus GDNF activated Ret in cells lacking GFRA1 [PMID:8674117].","affinity_potency":[],"species_and_systems":"Expression cloning and Neuro-2a cells, with curators recording human ligand and receptor [PMID:8674117]; receptor-Fc binding assay in [PMID:9883723]. The mouse pair is ortholog-inferred.","localisation_and_range":"GFRA1 is GPI-linked [PMID:8674117]; GDNF is flagged secreted [flag], so the complex acts at the cell surface in paracrine fashion.","caveats":"No affinity value is in the dossier. PMID:9482105 is a gene-structure paper that only restates the binding. PMID:9883723 was read in a browser with the quote unverified.","key_references":[{"PMID":"8674117","why":"Cloning of GDNFR-alpha; binds GDNF and mediates Ret activation"},{"PMID":"9883723","why":"GDNF binds GFR alpha1-Fc"}],"covers":["LR000710","LR004194"]},"LR004202":{"pair":"GIP -> GIPR","headline":"GIP binds GIPR directly, shown by a crystal structure of the extracellular domain and binding assays.","interaction_type":"direct binding","direction_and_effect":"GIP(1-42) is an agonist of the GIP receptor; GtoPdb lists agonist [PMID:17715056][PMID:7589426][DB:GtoPdb]. Stably transfected cells showed coupling to adenylate cyclase [PMID:7589426].","molecular_requirements":"The receptor extracellular domain binds GIP in an alpha-helical conformation in a surface groove, mostly hydrophobic; N-terminal ligand residues stay free for other receptor parts [PMID:17715056]. The entire GIP(1-31) sequence is important for recognition, and hybrids with GLP-1 had minimal GIPR binding [PMID:8795084].","affinity_potency":[{"value":"Kd 1.93 +/- 0.2 x 10(-8) M","assay":"binding to cloned receptor, human GIP 1-42","system":"stably transfected fibroblast (CHL) cells, human receptor","cite":"PMID:7589426"},{"value":"Kd 1.13 +/- 0.1 x 10(-8) M","assay":"porcine truncated GIP 1-30","system":"same","cite":"PMID:7589426"}],"species_and_systems":"Human receptor and ligand in recombinant systems; RINm5F insulinoma cells in the hybrid study [PMID:8795084]. Mouse pair is ortholog-inferred. Structures: [DB:PDB 2QKH].","localisation_and_range":"Ligand secreted, receptor transmembrane [flag].","caveats":"All papers read as abstracts only. PMID 12627975 tests GIP analogues, with native GIP1-42 and GIP1-30 as references; PMID 8795084 is a negative-result style hybrid study.","key_references":[{"PMID":"17715056","why":"Crystal structure of GIPR ECD with GIP(1-42)"},{"PMID":"7589426","why":"GIPR cloned; Kd for GIP 1-42 and 1-30"},{"PMID":"8795084","why":"GIP sequence requirements for receptor binding"}],"covers":["LR000719","LR004202"]},"LR012005":{"pair":"GREM1 -> BMP4","headline":"Database-supported GREM1:BMP4 complex; five papers were judged but none gave usable evidence.","interaction_type":"database-asserted only","direction_and_effect":"Reactome records a GREM1:BMP4 complex [DB:Reactome]. The interaction is annotated as ligand-ligand with inhibitory modulatory effect [flag]; the direction is not otherwise shown in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Both partners flagged as secreted [flag].","caveats":"All five judged papers were abstract_insufficient, so nothing is curator-verified. Support is from a Reactome record only.","key_references":[],"covers":["LR012005"]},"LR004211":{"pair":"GRP -> NMBR","headline":"GRP is a weak agonist of NMBR, supported by mouse itch data and a simulation study.","interaction_type":"functional only","direction_and_effect":"In mice, GRP can signal through both NMBR and GRPR, though to NMBR to a much lesser extent [PMID:25209280]. Molecular dynamics simulation supports GRP(14-27) as a weak NMBR agonist [PMID:40579433]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse knock-out and itch behaviour [PMID:25209280]; MD simulation of the receptor-peptide complex (not experimental binding) [PMID:40579433]. Human pair is not experimentally covered by the curated papers; mouse pair is ortholog-inferred.","localisation_and_range":"GRP is flagged secreted; NMBR is flagged as a transmembrane receptor [flag].","caveats":"No direct binding assay in the curated papers; both read as abstracts only. GtoPdb gives pIC50 6.83-6.91 [DB:GtoPdb], well below GRP's GRPR potency in other pairs.","key_references":[{"PMID":"25209280","why":"Mouse itch: GRP signals through NMBR weakly"},{"PMID":"40579433","why":"GRP(14-27) as weak NMBR agonist in simulation"}],"covers":["LR000729","LR004211"]},"LR004220":{"pair":"HBEGF -> ERBB4","headline":"HB-EGF binds and activates HER4 (ERBB4) in transfected cells and cardiac myocytes; supported by IntAct and Reactome records.","interaction_type":"direct binding","direction_and_effect":"HB-EGF bound NIH 3T3 cells overexpressing HER4 alone, independent of HER1, and induced HER4 tyrosine phosphorylation, PI3-K association and chemotaxis [PMID:9135143]. In mouse cardiac myocytes HB-EGF induced ErbB2 and ErbB4 phosphorylation [PMID:12621152]. It was not mitogenic for HER4-expressing cells [PMID:9135143].","molecular_requirements":"HER4 alone was sufficient for binding; HER2 or HER3 alone did not bind [PMID:9135143]. Coreceptor needs for signalling are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human NIH 3T3 transfectants, MDA-MB-453 cells and astrocytes [PMID:9135143]; mouse in vivo [PMID:12621152]. Mouse pair ortholog-inferred.","localisation_and_range":"Secreted and transmembrane flags on HB-EGF [flag]; chemotactic factor acting on cells [PMID:9135143].","caveats":"Abstracts only. Reactome entry is generic ERBB4 binding of NRGs or EGF-like ligands [DB:Reactome R-HSA-1236398]; GtoPdb lists no action or affinity [DB:GtoPdb].","key_references":[{"PMID":"9135143","why":"HB-EGF binds and activates HER4"},{"PMID":"12621152","why":"HB-EGF induces ErbB4 phosphorylation in vivo"}],"covers":["LR000738","LR004220"]},"LR011105":{"pair":"HLA-DQB1 -> CD4","headline":"Class II binding to CD4 is structurally shown, but with murine I-A(k), not HLA-DQB1.","interaction_type":"direct binding","direction_and_effect":"Crystal structure of human CD4 N-terminal two-domain fragment bound to a class II MHC [PMID:11535811].","molecular_requirements":"Only the top corner of CD4 contacts peptide-MHC II, with Phe-43 inserting into a hydrophobic pocket [PMID:11535811]. Contribution of the beta chain: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human CD4 with murine I-A(k), purified proteins, X-ray crystallography [PMID:11535811].","localisation_and_range":"Not reported in our evidence.","caveats":"HLA-DQB1 itself was not tested; abstract only; one more paper was review-only.","key_references":[{"PMID":"11535811","why":"Crystal structure of CD4 with class II MHC"}],"covers":["LR011105"]},"LR005999":{"pair":"HSPA1A -> LRP1","headline":"HSP70 binds CD91 on cells (2001) and docks to CD91 in silico (2025); binding is cell-level or computational.","interaction_type":"direct binding","direction_and_effect":"FITC-labelled hsp70 binds RAW264.7 and related cell lines via CD91, competed by alpha2-macroglobulin and anti-CD91 [PMID:11290339]. Docking suggests strong, stable binding of full-length HSPA1A to CD91 [PMID:40813535].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse cell lines [PMID:11290339]; in silico docking, no experimental species for the docking paper [PMID:40813535]. The human pair is ortholog-inferred.","localisation_and_range":"HSPA1A is flagged as secreted [flag].","caveats":"The 2001 evidence sentence concerns gp96; the hsp70 result comes from the curator's detail. The 2025 evidence is computational and abstract only. One further row was abstract_insufficient.","key_references":[{"PMID":"11290339","why":"hsp70 binds cells via CD91, competed by alpha2-macroglobulin"},{"PMID":"40813535","why":"In silico docking of HSPA1A to CD91"}],"covers":["LR002751","LR005999"]},"LR006002":{"pair":"HSPG2 -> CSPG4","headline":"Human melanoma-cell evidence that CSPG4 forms a complex with perlecan via protein-protein interactions; abstract only.","interaction_type":"direct binding","direction_and_effect":"CSPG4 immunopurified from melanoma lines formed a complex with perlecan made by the same cells, and the interaction supported cell adhesion and actin polymerization [PMID:29462330].","molecular_requirements":"Binding was via hydrophobic protein-protein interactions at multiple sites on perlecan, including the C-terminal region [PMID:29462330]. Chondroitin sulphate decoration of CSPG4 differed between cell lines [PMID:29462330].","affinity_potency":[],"species_and_systems":"Human melanoma cell lines MM200 and Me1007, immunopurification and adhesion assays [PMID:29462330]. Mouse pair is ortholog-inferred.","localisation_and_range":"CSPG4 is flagged transmembrane and also secreted [flag]; it is on the cell surface and shed into conditioned medium [PMID:29462330]. Perlecan is a matrix partner, so interaction is contact or matrix-mediated.","caveats":"Abstract only; no affinity. Co-purification does not alone prove direct binding, though the abstract reports mechanistic studies. The curator's 'agonist' label has no signalling evidence behind it in the abstract.","key_references":[{"PMID":"29462330","why":"CSPG4-perlecan complex in melanoma cells; hydrophobic multi-site binding"}],"covers":["LR002755","LR006002"]},"LR000800":{"pair":"ICAM4 -> ITGB1","headline":"Single abstract-only study shows beta1-integrin (alpha4beta1, alphaVbeta1) mediated adhesion to ICAM-4-Fc; no direct binding assay.","interaction_type":"functional only","direction_and_effect":"Cell adhesion to ICAM-4-Fc was inhibited by LDV peptide and antibodies, identifying alpha4beta1, and alphaV integrins (notably alphaVbeta1) on alpha4beta1-negative cells [PMID:11435317]. UniProt lists ITGA5:ITGB1 among ICAM4 partners in vitro [DB:UniProt].","molecular_requirements":"beta1 acts with alpha4 or alphaV; the dossier gives no beta1-alone evidence. Neither the LETS nor LDV motif in ICAM-4 domain 1 was critical [PMID:11435317].","affinity_potency":[],"species_and_systems":"Human cell lines with an ICAM-4-Fc construct [PMID:11435317]; mouse pair ortholog-inferred.","localisation_and_range":"ICAM4 carries both secreted and transmembrane flags [flag], so range is unclear; the papers used recombinant ICAM-4-Fc and cell-surface ICAM-4, consistent with contact-dependent adhesion.","caveats":"One paper, abstract only; antibody and peptide inhibition rather than binding. Affinity not reported.","key_references":[{"PMID":"11435317","why":"alpha4beta1 and alphaV integrins bind ICAM-4-Fc"}],"covers":["LR000800","LR004254"]},"LR005201":{"pair":"IFNK -> IFNAR1","headline":"Recombinant human IFN-kappa binds IFNAR1 with affinity similar to other type I IFNs; single abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"IFN-kappa is an agonist on IFNAR; GtoPdb lists Agonist [DB:GtoPdb]. It is a type I interferon family member that signals through the common IFNAR1/IFNAR2 receptor complex and has about 1000-fold lower cellular potency than IFNalpha2 and IFNomega [PMID:30171073].","molecular_requirements":"IFN-kappa shows affinities for the IFNAR1 chain that are similar to other IFN subtypes, but weak affinity for IFNAR2 [PMID:30171073]. The functional receptor is the IFNAR1/IFNAR2 complex.","affinity_potency":[],"species_and_systems":"Recombinant human IFN-kappa, protein-affinity characterisation [PMID:30171073]. The mouse pair is projected from human (ortholog inferred), not tested. Numeric Kd values are not in the abstract.","localisation_and_range":"IFNK is flagged secreted and non-transmembrane [flag].","caveats":"Abstract-only read; no numeric affinity is given in our evidence. One other row was review_only.","key_references":[{"PMID":"30171073","why":"affinity characterisation of IFN-kappa and IFN-epsilon"}],"covers":["LR001853","LR005201"]},"LR006011":{"pair":"IGF1 -> ITGA6","headline":"Integrin alpha6beta4 directly binds IGF1 in one verified study; ITGA6 is the alpha chain of that integrin.","interaction_type":"direct binding","direction_and_effect":"Integrin alpha6beta4 directly bound IGF1, forming an alpha6beta4-IGF1-IGF1R ternary complex, and IGF1 signaling and survival depended on alpha6beta4 under low adhesion [PMID:22351760]. UniProt states ITGA6:ITGB4 binding is essential for IGF1 signaling [DB:UniProt].","molecular_requirements":"The heterodimer was tested, not ITGA6 alone. The beta4 sequence WPNSDP (residues 167-172) grafted onto beta1 enhanced IGF1 binding; the IGF1 R36E/R37E mutant did not bind or form the ternary complex [PMID:22351760].","affinity_potency":[],"species_and_systems":"Human proteins; assay details beyond a direct binding assay are not reported in our evidence [PMID:22351760].","localisation_and_range":"IGF1 is flagged secreted [flag]; the integrin acts at the cell surface in ternary complex with IGF1R [PMID:22351760].","caveats":"Abstract-only read. Evidence concerns the ITGA6:ITGB4 heterodimer, with the recognition determinant on beta4, so ITGA6 alone is not shown.","key_references":[{"PMID":"22351760","why":"Direct alpha6beta4 binding to IGF1 and ternary complex"}],"covers":["LR002765","LR006011"]},"LR006020":{"pair":"IGFBP3 -> TMEM219","headline":"One abstract-level study reports TMEM219 as a membrane receptor binding IGFBP-3 and mediating caspase-8-dependent apoptosis.","interaction_type":"direct binding","direction_and_effect":"TMEM219 (IGFBP-3R) binds IGFBP-3 specifically but not other IGFBP species; it mediates IGFBP-3-induced caspase-8-dependent apoptosis, and knockdown attenuated while overexpression enhanced the effect [PMID:20353938]. Curator labels it antagonist-direction in effect; UniProt describes IGF-independent antiproliferative and apoptotic effects via TMEM219 [DB:UniProt].","molecular_requirements":"IGFBP-3R is a single-span membrane protein that physically interacts with and activates caspase-8 [PMID:20353938]. Co-receptors: not reported.","affinity_potency":[],"species_and_systems":"Human proteins; cancer cells in vitro and breast and prostate cancer xenografts in athymic nude mice [PMID:20353938]. The mouse pair is marked as projected from human evidence.","localisation_and_range":"IGFBP3 is annotated as secreted and TMEM219 as transmembrane [flag]; the paper calls the receptor a single-span membrane protein [PMID:20353938].","caveats":"Abstract-only read; the abstract is truncated in the dossier. IntAct and Reactome records trace to the same paper (co-immunoprecipitation, solid phase assay) [DB:IntAct][DB:Reactome], so they are not independent. No affinity reported.","key_references":[{"PMID":"20353938","why":"Identifies IGFBP-3R (TMEM219) as IGFBP-3-specific death receptor"}],"covers":["LR002774","LR006020"]},"LR004301":{"pair":"IL17B -> IL17RB","headline":"IL-17B binds IL-17RB (SPR, flow cytometry, co-IP) in one human-protein study, read from the abstract only.","interaction_type":"direct binding","direction_and_effect":"Direction: IL-17B binds IL-17RB [PMID:10749887]. IL-17B injected in mice caused neutrophil migration in a dose-dependent manner, suggesting a proinflammatory cytokine [PMID:10749887]. GtoPdb lists an agonist interaction [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence beyond single IL-17RB, a type I transmembrane protein [PMID:10749887]. BioGRID lists a reconstituted complex [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Human protein binding; neutrophil migration was in mice with CHO-derived IL-17B [PMID:10749887]. Mouse pair is ortholog-inferred.","localisation_and_range":"IL-17RB described as a type I transmembrane protein [PMID:10749887]; IL-17B annotated as secreted [flag].","caveats":"Single study, abstract only, with no affinity. IL-17B in vivo effect was not shown to be via IL-17RB.","key_references":[{"PMID":"10749887","why":"SPR, flow cytometry and co-IP binding of IL-17B to IL-17BR"}],"covers":["LR000871","LR004301"]},"LR004310":{"pair":"IL1A -> IL1RAP","headline":"IL1RAP is an essential co-receptor for IL-1 signalling; direct IL-1alpha-IL1RAP binding is not shown, only a mouse knockout effect on affinity.","interaction_type":"functional only","direction_and_effect":"IL-1 agonists bound AcP-deficient cells through IL1R1 but failed to signal [PMID:9820540]; GtoPdb lists IL1A-IL1RAP as agonist [DB:GtoPdb].","molecular_requirements":"IL1RAP acts with IL1R1 and the pair is required for signalling by all IL-1 agonists [PMID:9820540]. Lack of AcP only moderately reduced murine IL-1alpha affinity, so IL1RAP is a minor contributor to IL-1alpha binding [PMID:9820540].","affinity_potency":[],"species_and_systems":"Mouse (AcP-deficient mice and fibroblasts, murine IL-1alpha) [PMID:9820540]. The mouse pair is the directly evidenced one; the human pair is ortholog-inferred.","localisation_and_range":"Ligand carries the secreted annotation flag [flag], which implies paracrine/endocrine range; receptor localisation beyond the receptor flag is not reported in our evidence.","caveats":"Abstract only. The paper does not show direct IL-1alpha-IL1RAP binding; IL1R1 is also needed. Co-receptor evidence only.","key_references":[{"PMID":"9820540","why":"IL1RAP-deficient mice and fibroblasts"}],"covers":["LR000880","LR004310"]},"LR005210":{"pair":"IL36RN -> IL1RL2","headline":"IL-36Ra binds IL-36 receptor (IL1RL2) and is an antagonist; one binding paper plus GtoPdb.","interaction_type":"direct binding","direction_and_effect":"Immobilized ectodomain screen: IL-36Ra bound only the IL-36 receptor among IL-1 receptor family members [PMID:22315422]. GtoPdb: Antagonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human recombinant ectodomains; human PBMC assays [PMID:22315422]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand annotated as secreted [flag]; receptor-side localisation not otherwise reported.","caveats":"Abstract only. The paper is mainly about IL-38; IL-36Ra is a comparator. Dose-response was non-classical and both increased LPS-induced IL-6 twofold in dendritic cells [PMID:22315422]. No affinity.","key_references":[{"PMID":"22315422","why":"IL-36Ra and IL-38 bind only IL-36 receptor"}],"covers":["LR001865","LR005210"]},"LR004400":{"pair":"LAMA1 -> ITGA7","headline":"Recombinant alpha7 integrin binds laminin-111 with Kd 0.97 nM; confirmed by one full-text and one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Recombinant alpha7beta1 binds laminin-111 in solid-phase assay [PMID:16413178]. Alpha7beta1 is described as a receptor for laminin-1 that mediates myoblast migration on it [PMID:11278916]. Record labelled Stimulatory [flag].","molecular_requirements":"The alpha7X2beta1 splice variant bound laminin-111; the alpha7X1beta1 variant only partially saturated (ND(+)) for laminin-111 [PMID:16413178]. The receptor was a heterodimer with beta1 [PMID:16413178].","affinity_potency":[{"value":"Kd 0.97 nM","assay":"solid-phase saturation binding","system":"recombinant human alpha7X2beta1 ectodomain with laminin-111","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant integrins [PMID:16413178]; human transfected myoblasts and HEK293 cells on laminin [PMID:11278916].","localisation_and_range":"Ligand flagged secreted [flag]; matrix ligand.","caveats":"Evidence is for the assembled laminin heterotrimer, not the single alpha chain alone [PMID:16413178]. The second paper states receptor identity as background and is abstract-only [PMID:11278916].","key_references":[{"PMID":"16413178","why":"Kd 0.97 nM for alpha7X2beta1 and laminin-111"},{"PMID":"11278916","why":"Alpha7beta1 mediates myoblast migration on laminin-1"}],"covers":["LR000979","LR004400"]},"LR011042":{"pair":"LAMA4 -> ITGA6:ITGB1","headline":"Separate papers implicate ITGA6 (renal cancer macrophages) and ITGB1 (mouse brain) with LAMA4; no complex-level test.","interaction_type":"functional only","direction_and_effect":"Tumour-secreted LAMA4 engaged macrophage surface ITGA6 to trigger GATA3 activation, and disrupting LAMA4-ITGA6 binding attenuated metastasis [PMID:41610310]. LAMA4 and ITGB1 overlapped by immunofluorescence in E14.5 mouse brain [PMID:31677479].","molecular_requirements":"Each paper names one chain; neither tests the alpha6beta1 heterodimer [PMID:41610310][PMID:31677479].","affinity_potency":[],"species_and_systems":"Renal cell carcinoma/macrophage system [PMID:41610310]; mouse E14.5 brain [PMID:31677479].","localisation_and_range":"LAMA4 flagged secreted [flag].","caveats":"Both papers read from abstract (31677479 with full-text excerpts); chain-level evidence only; co-localisation is not binding. Three papers were abstract-insufficient.","key_references":[{"PMID":"41610310","why":"LAMA4-ITGA6 axis on macrophages"},{"PMID":"31677479","why":"LAMA4-ITGB1 overlap in brain"}],"covers":["LR011042"]},"LR011123":{"pair":"LAMA4 -> ITGA6:ITGB4","headline":"Only an abstract naming LAMA4 with ITGA6; the ITGB4 partner is not examined.","interaction_type":"functional only","direction_and_effect":"Tumour-secreted LAMA4 engaged macrophage surface receptor ITGA6 in renal cell carcinoma, and disrupting LAMA4-ITGA6 binding reduced metastatic burden [PMID:41610310].","molecular_requirements":"Only ITGA6 is named; ITGB4 is not mentioned [PMID:41610310].","affinity_potency":[],"species_and_systems":"ccRCC tumour and macrophage system; species not stated in the abstract [PMID:41610310].","localisation_and_range":"LAMA4 flagged secreted [flag].","caveats":"Abstract-only, chain-level evidence; alpha6beta4 pairing not tested. Five papers were abstract-insufficient.","key_references":[{"PMID":"41610310","why":"LAMA4-ITGA6 axis"}],"covers":["LR011123"]},"LR011006":{"pair":"LAMB2 -> ITGA2:ITGB1","headline":"Complex row for laminin beta2 and integrin alpha2beta1; only a PDB record, no judged paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence. A PDB entry has a chain of P11047 and a chain of P05556 [DB:PDB 7CEC].","molecular_requirements":"Receptor is the ITGA2:ITGB1 heterodimer per the entity record; the PDB chains listed do not include ITGA2 [DB:PDB 7CEC].","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"LAMB2 is flagged secreted [flag] and ITGA2:ITGB1 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"No papers judged (three abstract_insufficient). Support is one structure record.","key_references":[],"covers":["LR011006"]},"LR006101":{"pair":"LAMB2 -> ITGA6","headline":"LAMB2 (as part of laminin-511/521) binds integrin alpha6 with sub-nanomolar to nanomolar affinity; chain-level, assembled-laminin evidence.","interaction_type":"direct binding","direction_and_effect":"Laminin-511/521, which contains LAMB2, binds the integrin alpha6beta1 ectodomain in solid-phase assays [PMID:16413178]. A second paper reports radioligand-binding and cell-adhesion assays showing alpha6beta4 is a receptor for several laminin isoforms [PMID:7721947]. Direction: laminin ligand to integrin receptor; effect is adhesion/binding, nothing more reported.","molecular_requirements":"The binder tested is the alpha6beta1 heterodimer, and the ligand is the assembled laminin heterotrimer; LAMB2 alone and ITGA6 alone were not tested [PMID:16413178]. PDB 7CEC lists a structure with chains of P11047 and P23229 [DB:PDB 7CEC].","affinity_potency":[{"value":"Kd 0.73 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoform; integrin alpha6beta1 vs laminin-511/521","system":"recombinant human integrin, purified laminin","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant proteins in the solid-phase study [PMID:16413178]. The 804G bladder epithelial cell study used rat cells with laminin of unstated origin [PMID:7721947]. Mouse pair is projected from human.","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"Kd values are for the whole laminin heterotrimer, not the single chain; the paper never tests individual chains. The second paper was read as an abstract only and concerns alpha6beta4, with laminin 4 only inferred as LAMA2/LAMB2/LAMC1 by the curator.","key_references":[{"PMID":"16413178","why":"Kd for alpha6beta1 vs laminin-511/521, full text"},{"PMID":"7721947","why":"alpha6beta4 binds several laminins, abstract only"}],"covers":["LR002867","LR006101"]},"LR011051":{"pair":"LAMB3 -> ITGA6:ITGB1","headline":"LAMB3 co-precipitates with ITGA6 in human keratinocytes; support is one 2026 paper plus a Reactome record for another integrin.","interaction_type":"direct binding","direction_and_effect":"Endogenous immunoprecipitation showed ITGA6 co-precipitates with LAMB3 in HOK cells; a predicted ITGA6-LAMB3 structure model was also reported [PMID:41960183]. LAMB3 knockdown reduced ITGA6 and overexpression raised it [PMID:41960183].","molecular_requirements":"The paper reports ITGA6 with LAMB3, not the ITGA6:ITGB1 complex specifically; ITGB1 involvement is not reported in our evidence. The Reactome record concerns alpha2beta1 [DB:Reactome R-HSA-349626].","affinity_potency":[],"species_and_systems":"Human oral keratinocyte (HOK) cells; a mouse wound model was also used for LAMB3 overexpression [PMID:41960183].","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"Co-immunoprecipitation does not establish direct binding or which integrin partner is used; the paper links LAMB3 to the hemidesmosomal alpha6beta4 context. One pending and one abstract_insufficient paper are not shown.","key_references":[{"PMID":"41960183","why":"IP and structural model of LAMB3-ITGA6, full text"}],"covers":["LR011051"]},"LR001007":{"pair":"LAMB3 -> ITGB1","headline":"LAMB3 (in laminin-332) binds integrin beta1-containing alpha3beta1 at Kd 14 nM; chain-level mapping of an assembled-laminin result.","interaction_type":"direct binding","direction_and_effect":"Laminin-332, which contains LAMB3, bound recombinant alpha3beta1 in solid-phase assays [PMID:16413178]. Annotated effect is Stimulatory [flag]. Reactome records integrin alpha2beta1 binding laminin-332 [DB:Reactome R-HSA-349626].","molecular_requirements":"Binder tested is an alpha-beta1 heterodimer (alpha3beta1 for this value); ITGB1 alone was not tested, and the ligand is the whole heterotrimer [PMID:16413178].","affinity_potency":[{"value":"Kd 14 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoform; alpha3beta1 vs laminin-332","system":"recombinant human integrin, purified laminin","cite":"PMID:16413178"}],"species_and_systems":"Recombinant human proteins [PMID:16413178]; mouse pair is projected from human.","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"Kd values are for the whole laminin heterotrimer, not the single chain and with an alpha-beta heterodimer. Three further papers were abstract_insufficient.","key_references":[{"PMID":"16413178","why":"Kd of alpha3beta1 for laminin-332"}],"covers":["LR001007","LR004425"]},"LR001016":{"pair":"LAMC2 -> ITGB1","headline":"Recombinant alpha3beta1 binds laminin-332 (contains LAMC2) with Kd 14 nM; ITGB1 is shared by the heterodimer.","interaction_type":"direct binding","direction_and_effect":"Recombinant alpha3beta1 bound laminin-332 in solid-phase assays [PMID:16413178]. Recorded effect: stimulatory [flag]. Reactome also lists alpha2beta1 binding laminin-332 [DB:Reactome R-HSA-349626].","molecular_requirements":"Binding was by integrin heterodimers and the assembled laminin-332 heterotrimer; beta1 alone and LAMC2 alone were not tested [PMID:16413178].","affinity_potency":[{"value":"Kd 14 nM","assay":"solid-phase saturation binding of recombinant integrin to laminin-332","system":"human recombinant alpha3beta1","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant proteins [PMID:16413178]. Mouse pair is ortholog-projected.","localisation_and_range":"LAMC2 flagged secreted; ITGB1 flagged not secreted [flag].","caveats":"Chain-level assignment inferred from complex-level binding; the Kd belongs to alpha3beta1.","key_references":[{"PMID":"16413178","why":"Recombinant integrin binding to laminin-332"}],"covers":["LR001016","LR004434"]},"LR006110":{"pair":"LEFTY1 -> ACVR2A","headline":"Lefty is proposed to antagonise Nodal by competing for ActRIIA/ActRIIB; evidence is functional, from one abstract.","interaction_type":"functional only","direction_and_effect":"Processed Lefty proteins inhibited Nodal signalling, and this was rescued by excess ActRIIA or ActRIIB, suggesting competitive binding as an antagonist [PMID:11952836].","molecular_requirements":"Receptor identity is shared with Nodal: ActRIIA or ActRIIB acts as type II receptor [PMID:11952836]. Either could mediate rescue.","affinity_potency":[],"species_and_systems":"Frog animal cap assays, with genetic interaction of lefty2 and ActRIIB in mouse [PMID:11952836]. Human pair is ortholog-projected.","localisation_and_range":"LEFTY1 is flagged secreted [flag]; the paper discusses diffusion.","caveats":"Abstract only; binding is inferred from rescue, not measured; LEFTY1 specifically is not distinguished from other Lefty proteins in the abstract.","key_references":[{"PMID":"11952836","why":"Lefty inhibition rescued by excess ActRIIA/B"}],"covers":["LR002876","LR006110"]},"LR001025":{"pair":"LIF -> IL6ST","headline":"LIF signals through gp130 (IL6ST) as the shared signalling chain; evidence is functional and computational, plus structures.","interaction_type":"functional only","direction_and_effect":"LIF signals through a gp130(IL6ST)/LIFR receptor complex, gp130 being a shared signal-transducing subunit; agonist [PMID:16051226]. GtoPdb records an agonist [DB:GtoPdb]. UniProt says ligand binding to LIFR induces heterodimerization with IL6ST and JAK activation [DB:UniProt].","molecular_requirements":"IL6ST works with LIFR; the receptor complex has two signalling subunits, IL6ST and LIFR [DB:UniProt]. A homology model suggests gp130 and the membrane-proximal LIFR CBD heterodimerize and bind LIF [PMID:9568895]. PDB structures 1PVH and 8D6A contain chains of both proteins [DB:PDB 1PVH][DB:PDB 8D6A].","affinity_potency":[],"species_and_systems":"Human receptors in cell-based signalling [PMID:16051226]; the 1998 study is computational [PMID:9568895]. The mouse pair is ortholog-inferred.","localisation_and_range":"LIF is flagged secreted and IL6ST as transmembrane [flag].","caveats":"Neither paper directly measures LIF binding to IL6ST alone: one is signalling in cells, the other homology modelling, both abstract-read. IL6ST alone is not shown to be sufficient; LIFR is needed.","key_references":[{"PMID":"16051226","why":"LIF signals through gp130/LIFR complex in cells"},{"PMID":"9568895","why":"Homology model of gp130-LIFR dimer binding LIF"}],"covers":["LR001025","LR004442"]},"LR008888":{"pair":"LIN7C -> ABCA1","headline":"Only a database holdup-assay record; the one paper judged was a different entity.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. LIN7C is an intracellular scaffold and this is likely not a secreted ligand-receptor pair.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond an IntAct record of direct interaction by holdup assay [DB:IntAct].","localisation_and_range":"No localisation flags in dossier.","caveats":"Rests on a single IntAct record [DB:IntAct]; no curated paper supports it, one paper was judged as a different entity.","key_references":[],"covers":["LR008888"]},"LR001034":{"pair":"LPL -> VLDLR","headline":"LPL binds purified VLDLR with high affinity and is internalised by VLDLR-expressing cells; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"LpL bound with high affinity to purified VLDL receptor in vitro [PMID:7592875]. Fibroblasts lacking VLDLR and LRP that were given VLDLR by adenovirus internalised and degraded 125I-LpL, whereas uninfected or lacZ-infected cells did not [PMID:7592875]. VLDLR acts as an endocytic clearance receptor here.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins in vitro; murine embryonic fibroblasts used for the internalisation assay [PMID:7592875].","localisation_and_range":"LPL is annotated secreted and VLDLR transmembrane [flag].","caveats":"Single paper read as abstract only; numeric affinity not stated in the abstract. BioGRID lists a reconstituted complex record from the same paper [DB:BioGRID].","key_references":[{"PMID":"7592875","why":"LpL binds purified VLDLR and is internalised via VLDLR in fibroblasts"}],"covers":["LR001034","LR004448"]},"LR007979":{"pair":"MADCAM1 -> ITGA4:ITGB7","headline":"Complex-level pair resting on database records only, including a cryo-EM structure of alpha4beta7 bound to MAdCAM-1; no curated papers.","interaction_type":"database-asserted only","direction_and_effect":"MADCAM1 is the ligand and integrin alpha4beta7 the receptor. UniProt states alpha4/beta7 is a receptor for MADCAM1 [DB:UniProt]. Reactome has a binding reaction 'MADCAM1-1 binds Integrin alpha4beta7' [DB:Reactome].","molecular_requirements":"Both ITGA4 and ITGB7 are members of the receptor complex [flag]; the PDB entry has a chain of each [DB:PDB 9P95].","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond the database records (human entities).","localisation_and_range":"MADCAM1 is flagged transmembrane, not secreted; the complex is flagged transmembrane [flag]. Adhesion (juxtacrine) class.","caveats":"No paper was judged for this entry. Support comes from a cryo-EM structure of integrin alpha4beta7 bound to MAdCAM-1 [PMID:40929264][DB:PDB 9P95], IntAct electron microscopy [PMID:22232704][DB:IntAct], BioGRID reconstituted complex [PMID:9233649][DB:BioGRID], Reactome and UniProt. Binding affinity and effect direction are not reported in our evidence.","key_references":[{"PMID":"40929264","why":"cryo-EM structure of alpha4beta7 bound to MAdCAM-1 (PDB 9P95)"},{"PMID":"9233649","why":"BioGRID reconstituted complex record"}],"covers":["LR007979"]},"LR001052":{"pair":"MATN1 -> ITGB1","headline":"Matrilin-1 adhesion is blocked by anti-beta1 antibody; functional evidence only, from one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Monoclonal antibody to integrin beta1 abolished CMP (matrilin-1)-induced cell adhesion and spreading [PMID:10196235].","molecular_requirements":"Beta1 is the likely partner of alpha1 (alpha1beta1); the alpha1 subunit co-precipitated labeled CMP, not beta1 [PMID:10196235].","affinity_potency":[],"species_and_systems":"Rabbit and human chondrocytes and fibroblasts on CMP-coated dishes [PMID:10196235]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"MATN1 is flagged secreted; ITGB1 flagged not secreted [flag]. Matrix adhesion.","caveats":"No direct binding to beta1 shown; antibody blockade only, abstract only, single paper. No database records.","key_references":[{"PMID":"10196235","why":"anti-beta1 blocks matrilin-1-induced adhesion"}],"covers":["LR001052","LR004465"]},"LR001061":{"pair":"MDK -> SDC1","headline":"Midkine binds syndecan-1 through its heparan sulfate and chondroitin sulfate chains; two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"Midkine bound both HS and CS chains of syndecan-1 by BIAcore [PMID:15226297]. Syndecan-1 isolated from 10-day rat fetus bound midkine strongly [PMID:9089390].","molecular_requirements":"Binding is glycosaminoglycan-mediated; the core protein also contributes for syndecan-1 [PMID:15226297]. CS removal changed association and dissociation rates, suggesting simultaneous HS and CS engagement [PMID:15226297].","affinity_potency":[],"species_and_systems":"Murine mammary epithelial cell syndecans with midkine (BIAcore) [PMID:15226297]; rat fetal syndecan-1 [PMID:9089390]. Curators record human ligand/receptor species, but the abstracts describe murine and rat material. Both species pairs are ortholog-inferred.","localisation_and_range":"Syndecan-1 is flagged secreted and transmembrane [flag]; the papers describe an ectodomain proteoglycan, so shed or membrane forms are both possible.","caveats":"Abstract-only reads. Syndecan-1 binding is a proteoglycan chain interaction and not a classic protein receptor; syndecan-3 and -4 bind similarly. No affinity reported.","key_references":[{"PMID":"15226297","why":"BIAcore: midkine binds HS and CS chains of syndecan-1"},{"PMID":"9089390","why":"Fetal rat syndecan-1 binds midkine"}],"covers":["LR001061","LR004474"]},"LR001070":{"pair":"MFNG -> NOTCH2","headline":"Manic fringe modifies Notch2 and reduces Jagged1 binding and signalling; enzyme-substrate, not a classic ligand.","interaction_type":"functional only","direction_and_effect":"Manic fringe decreased Jagged1 binding to Notch2 and Jagged1-triggered signalling, more than lunatic fringe, with no effect on Delta1 [PMID:11346656].","molecular_requirements":"Fringe is a glycosyltransferase acting on Notch2 EGF-repeat O-fucose; the two fringes act on different sites of the Notch2 extracellular region [PMID:11346656].","affinity_potency":[],"species_and_systems":"Human proteins in cell assays [PMID:11346656]. Human pair ortholog-inferred.","localisation_and_range":"MFNG is flagged secreted [flag]; it acts on the Notch ectodomain.","caveats":"Abstract only. It modulates Jagged1-Notch2 and is not itself an activating ligand, so it shouldn't be scored as a ligand-receptor pair in CCC tools.","key_references":[{"PMID":"11346656","why":"Manic fringe reduces Jagged1-Notch2 binding and signalling"}],"covers":["LR001070","LR004483"]},"LR011132":{"pair":"NGFR -> NTRK3","headline":"Receptor-receptor association: p75NTR co-precipitates with trkC in co-transfected cells; a single abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"p75NTR was co-precipitated with trkC in cells transfected with both receptor types [PMID:9927421]; the interaction is annotated stimulatory [flag].","molecular_requirements":"Domain mapping was done on trkB, not trkC [PMID:9927421]; requirements for trkC are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Co-immunoprecipitation in doubly transfected cells; species not reported in our evidence; abstract only [PMID:9927421]. No database records.","localisation_and_range":"Both membrane receptors in close proximity [PMID:9927421].","caveats":"Single paper, abstract only, and no database support; co-IP may be indirect.","key_references":[{"PMID":"9927421","why":"p75NTR co-precipitates with trkA, trkB and trkC"}],"covers":["LR011132"]},"LR001106":{"pair":"NLGN2 -> NRXN2","headline":"Supported by a general neurexin-binding paper and a mutation study; NRXN2-specific binding not individually shown.","interaction_type":"direct binding","direction_and_effect":"All three neuroligins bind beta-neurexins [PMID:8576240]. A truncated NRXN2 protein from an ASD patient failed to bind NLGN2 in cell binding assays and to promote synaptic differentiation [PMID:21424692].","molecular_requirements":"Tight binding needs beta-neurexins lacking a splice site 4 insert [PMID:8576240].","affinity_potency":[],"species_and_systems":"Human cell binding and neuron coculture (curator: human) [PMID:21424692]; species unspecified for 8576240. Mouse pair is not ortholog-inferred; the human pair is.","localisation_and_range":"Neither partner is secreted; both carry transmembrane flags [flag], so this is a membrane-bound, contact-dependent (trans-synaptic) pair. BioGRID lists a reconstituted complex [DB:BioGRID].","caveats":"Abstract only. The mutation paper's evidence is loss-of-binding in a truncated protein, not wild-type NRXN2 binding. 8576240 speaks of beta-neurexins as a class. No affinity.","key_references":[{"PMID":"8576240","why":"Neuroligin binding to beta-neurexins"},{"PMID":"21424692","why":"Truncated NRXN2 fails to bind NLGN2"}],"covers":["LR001106","LR004517"]},"LR001115":{"pair":"NMU -> NMUR1","headline":"Strongly supported direct agonist-receptor pair: radioligand binding, calcium and signalling assays in recombinant human cells, and Reactome, BioGRID, GtoPdb and PDB records.","interaction_type":"direct binding","direction_and_effect":"NMU is an agonist of NMU1R; it raises intracellular Ca2+ and inositol phosphate and inhibits forskolin-stimulated cAMP in HEK-293 cells [PMID:15292653]. The receptor couples to Galpha(q/11) and Galpha(i) [PMID:15331768]. NMU potently activates FM3 with subnanomolar potency, while neuromedins B, C, K and N are inactive [PMID:10811630].","molecular_requirements":"Single receptor chain is sufficient in recombinant cells; no co-receptor reported. Binding to the receptor is described as essentially irreversible, followed by internalisation [PMID:15331768].","affinity_potency":[{"value":"EC50 0.50 nM","assay":"intracellular Ca2+ release (stated in abstract for NmU isopeptides)","system":"human NmU1R/NmU2R in HEK-293 cells","cite":"PMID:15292653"},{"value":"EC50 1.6 nM","assay":"inositol phosphate formation","system":"human recombinant receptor in HEK-293 cells","cite":"PMID:15292653"}],"species_and_systems":"Human recombinant receptors in HEK-293 cells [PMID:15292653][PMID:15331768]; transient FM3 in HEK-293 [PMID:10811630]; endogenous receptors in isolated rat smooth muscle cells [PMID:15331768]. The mouse pair is inferred from human by orthology.","localisation_and_range":"NMU is flagged secreted and the receptor transmembrane [flag]; the papers do not address range.","caveats":"Almost all papers were read as abstracts only. PMID:10899166 does not state species. PMID:10894543 names no specific binding assay or affinity.","key_references":[{"PMID":"10811630","why":"NMU potently activates FM3 (NMUR1) in HEK-293 cells; other neuromedins inactive"},{"PMID":"15292653","why":"Radioligand binding and signalling of both human receptors"},{"PMID":"15331768","why":"G protein coupling and near-irreversible binding"}],"covers":["LR001115","LR004526"]},"LR001124":{"pair":"NPFF -> NPFFR1","headline":"NPFF binds NPFFR1 with nanomolar affinity and acts as a full agonist; four confirming papers and GtoPdb.","interaction_type":"direct binding","direction_and_effect":"NPFF specifically bound NPFF1, and both receptors were activated by NPFF [PMID:11024015]. In human NPFF1 CHO cells it inhibits forskolin-induced cAMP [PMID:12242085], and GTPgammaS assays showed agonist behaviour [PMID:17011599]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Receptor alone sufficient in CHO cells. Galpha(i3) and Galpha(s) are the main transducers of NPFF1 [PMID:17011599].","affinity_potency":[{"value":"Kd 1.13 nM","assay":"radioligand binding","system":"heterologous expression, human and rat clones","cite":"PMID:11024015"},{"value":"pKi 8.5 to 9.899999618530273","assay":"GtoPdb affinity range","system":"not specified in dossier","cite":"DB:GtoPdb"}],"species_and_systems":"Human and rat receptor clones in heterologous systems [PMID:11024015]; human NPFF1 in CHO cells [PMID:12242085, PMID:17011599]. Abstracts only. Mouse pair ortholog-inferred.","localisation_and_range":"NPFF is flagged secreted [flag].","caveats":"Peptides from both precursors bind both receptors; NPFF2 is also bound with high affinity, so NPFF is not selective [PMID:11024015, PMID:12242085]. The PMID:11481330 result compares NPVF peptides against NPFF peptides and gives no NPFF number.","key_references":[{"PMID":"11024015","why":"Kd 1.13 nM binding of NPFF to NPFF1"},{"PMID":"12242085","why":"Peptide affinities at human NPFF1 and NPFF2"},{"PMID":"17011599","why":"GTPgammaS agonist activity at NPFF1"}],"covers":["LR001124","LR004534"]},"LR001133":{"pair":"NPPC -> NPR2","headline":"CNP is the canonical, selective agonist of NPR2 (GC-B), supported by binding, functional and in vivo papers.","interaction_type":"direct binding","direction_and_effect":"CNP potently and selectively activated human ANPR-B guanylyl cyclase and did not raise cGMP in ANPR-A cells [PMID:1672777]; CNP was most potent at GC-B [PMID:1309330]. In mice CNP induces cGMP signalling via Npr2 needed for sensory axon bifurcation [PMID:19805384].","molecular_requirements":"Receptor-only guanylate cyclase; a splice variant NPR-Bi lacking a functional cyclase domain mediates a tyrosine-kinase-dependent K+ channel inhibition in IHKE-1 cells [PMID:12709393].","affinity_potency":[{"value":"50-fold higher than ANP","assay":"affinity of CNP for ANPR-B","system":"human ANPR-B","cite":"PMID:1672777"},{"value":"500-fold higher than BNP","assay":"affinity of CNP for ANPR-B","system":"human ANPR-B","cite":"PMID:1672777"}],"species_and_systems":"Human cells [PMID:1672777][PMID:12709393]; mouse in vivo genetics [PMID:19805384]. Both species are directly supported. GtoPdb lists agonist [DB:GtoPdb].","localisation_and_range":"CNP is annotated secreted [flag]; paper calls it a secreted molecule acting on sensory axons [PMID:19805384].","caveats":"All four papers read as abstracts. PMID:12709393 concerns a non-canonical variant, not canonical signalling.","key_references":[{"PMID":"1672777","why":"CNP selectively activates human ANPR-B"},{"PMID":"1309330","why":"Rank order at GC-B"},{"PMID":"19805384","why":"CNP/Npr2 in sensory axon bifurcation in mice"}],"covers":["LR001133","LR004543"]},"LR001142":{"pair":"NPY -> NPY2R","headline":"NPY is a high-affinity agonist of NPY2R, supported by three cloning papers, PDB structures and database records.","interaction_type":"direct binding","direction_and_effect":"NPY binds Y2 with high affinity and acts as an agonist: cloned human Y2 cells bind NPY [PMID:7559383], NPY inhibited forskolin-stimulated cAMP and induced calcium mobilization in Y2 CHO cells [PMID:7559383], and human PYY decreased cAMP [PMID:7592910].","molecular_requirements":"Single receptor chain; PDB complexes (7X9B, 7YOO, 8K6N) list one NPY chain and one NPY2R chain [DB:PDB 7X9B].","affinity_potency":[{"value":"pKi 9.27","assay":"125I-PYY displacement by NPY","system":"transiently expressed human Y2","cite":"PMID:7592910"},{"value":"pKd 10.17","assay":"saturation binding of 125I-PYY (not NPY)","system":"human Y2","cite":"PMID:7592910"}],"species_and_systems":"Human receptor in COS-7, CHO, 293 cells [PMID:7559383][PMID:7592910]; human brain library in [PMID:8632753]. Mouse pair is projected from human.","localisation_and_range":"NPY is flagged secreted, NPY2R transmembrane [flag].","caveats":"All papers read as abstracts only. NPY and PYY have similar affinity, and PP is much weaker [PMID:7592910]. The pKd is for the radioligand 125I-PYY.","key_references":[{"PMID":"7592910","why":"pKi 9.27 for NPY at human Y2"},{"PMID":"7559383","why":"Human Y2 cloning; NPY high-affinity binding and signalling"},{"PMID":"8632753","why":"Independent Y2 cloning from human brain"}],"covers":["LR001142","LR004551"]},"LR003005":{"pair":"NRG1 -> ITGAV","headline":"Single abstract-level report that NRG1 binds integrin alphaV (ITGAV); one paper, stored per subunit, not the dimer.","interaction_type":"direct binding","direction_and_effect":"NRG1 (isolated EGF-like domain or native multi-domain form) binds integrins; Lys-to-Glu mutants suppressed integrin binding and ErbB3 phosphorylation, so integrin binding appears to support NRG1-ErbB3 signalling [PMID:20682778]. UniProt states this binding is essential for NRG1-ERBB signalling [DB:UniProt].","molecular_requirements":"NRG1 binds the integrin heterodimers alphavbeta3 and alpha6beta4; the dossier stores them per subunit [PMID:20682778]. alpha6beta4 was functionally dominant for forming the integrin-NRG1-ErbB3 ternary complex [PMID:20682778]. A UniProt record says the ternary complex includes ERBB3 [DB:UniProt]. This row names only one chain; the evidence concerns the heterodimer.","affinity_potency":[{"value":"KD 136 nM (1.36 x 10(-7) m), to alphavbeta3","assay":"direct binding","system":"purified integrins","cite":"PMID:20682778"}],"species_and_systems":"Human ligand and human receptor, purified proteins; the mouse pair is projected from human evidence [PMID:20682778].","localisation_and_range":"NRG1 is flagged both secreted and transmembrane [flag]; range not addressed in the paper text we have.","caveats":"Only one paper, read as abstract only. The KD is for alphavbeta3, not for this individual chain. Chain-only row for a heterodimeric receptor; the integrin dimer should be the unit scored.","key_references":[{"PMID":"20682778","why":"Direct NRG1-integrin binding and integrin-NRG1-ErbB3 ternary complex"}],"covers":["LR003005","LR006229"]},"LR001151":{"pair":"NRG3 -> ERBB4","headline":"NRG3 binds and activates ERBB4; two papers, the primary one showing binding to cells and in vitro.","interaction_type":"direct binding","direction_and_effect":"NRG3 EGF-like domain binds the ErbB4 extracellular domain in vitro, binds ErbB4 on cells and stimulates its tyrosine phosphorylation, an agonist effect [PMID:9275162]. NRG-3 also activated erbB4 when expressed individually [PMID:9772300].","molecular_requirements":"ErbB4 acts as a single chain: activation occurred when expressed individually, unlike erbB2 and erbB3 [PMID:9772300].","affinity_potency":[],"species_and_systems":"Human ligand and receptor; in vitro binding, ErbB4-expressing cells, breast cancer cells and 32D transfectants [PMID:9275162][PMID:9772300]. Mouse pair is projected from human.","localisation_and_range":"Annotated secreted and transmembrane [flag]; expression restricted to the nervous system [PMID:9275162].","caveats":"Both papers abstract only; no affinity. GtoPdb record lists no action or affinity [DB:GtoPdb].","key_references":[{"PMID":"9275162","why":"NRG3 binds and activates ErbB4"},{"PMID":"9772300","why":"NRG-3 activates erbB4 individually"}],"covers":["LR001151","LR004560"]},"LR003014":{"pair":"NRXN1 -> ADGRL1","headline":"Direct high-affinity binding of neurexin ectodomains to latrophilin-1 shown for neurexins in general; one paper, NRXN1 not named in our evidence.","interaction_type":"direct binding","direction_and_effect":"CL1 (ADGRL1) and neurexins bind directly through their extracellular domains, and CL1 competed with neuroligin-1 for neurexin binding [PMID:22262843]. Cells expressing each partner formed a stable intercellular adhesion complex, so the interaction can act in trans [PMID:22262843]. Which partner is ligand or receptor is not defined; both are membrane proteins.","molecular_requirements":"Neurexins lacking an insert at splice site 4 (SS4) bind CL1 with nanomolar affinity; neurexins with an SS4 insert do not bind. The olfactomedin-like domain of CL1 mediates binding by deletion mapping [PMID:22262843].","affinity_potency":[],"species_and_systems":"Purified ectodomains and cell adhesion assays; species listed as human in the curation, mouse pair is ortholog-inferred, and the abstract does not specify NRXN1.","localisation_and_range":"Both are transmembrane proteins [flag]; trans-cellular, contact-dependent adhesion, with CL1 possibly postsynaptic [PMID:22262843].","caveats":"Evidence is stated for neurexins as a class; the abstract does not name NRXN1 specifically and no numeric affinity is in our evidence. Evidence sentence in the dossier is truncated.","key_references":[{"PMID":"22262843","why":"direct neurexin-CL1 binding, SS4-regulated, produces an adhesion complex"}],"covers":["LR003014","LR006238"]},"LR003023":{"pair":"NRXN1 -> NLGN2","headline":"Direct binding of beta-neurexin-1 to neuroligins measured by SPR; NLGN2 affinity not separately reported in our evidence.","interaction_type":"direct binding","direction_and_effect":"Neuroligins 1-4 are postsynaptic proteins that initiate presynaptic maturation via beta-neurexin, and individual neuroligins were tested against beta-neurexin-1 by surface plasmon resonance and affinity chromatography [PMID:17042500].","molecular_requirements":"Neuroligin and beta-neurexin form a 2:2 complex; splice insert 4 in beta-neurexin acts as a modulator [PMID:17042500]. BioGRID lists a reconstituted complex [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Recombinant ectodomains; species unspecified. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"Both transmembrane [flag]; trans-synaptic.","caveats":"Abstract only; the abstract reports affinities spanning more than 2 orders of magnitude across neuroligins but gives no NLGN2 value.","key_references":[{"PMID":"17042500","why":"SPR and affinity chromatography of neuroligin-beta-neurexin-1 recognition code"}],"covers":["LR003023","LR006247"]},"LR001160":{"pair":"NTF4 -> NGFR","headline":"NT-4 retrograde transport depends on p75 (LNR) in vivo in rat; no direct binding evidence.","interaction_type":"functional only","direction_and_effect":"Anti-LNR antibody or soluble LNR extracellular domain completely blocked retrograde transport of NT-4 and BDNF to sensory neurons, with minimal effect on NGF; transport was dramatically reduced in LNR-null mice [PMID:7541633].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Adult rats and LNR-null mice [PMID:7541633]. The pair is listed as human.","localisation_and_range":"NT-4 flagged secreted, NGFR transmembrane [flag]; transport is axonal retrograde in vivo.","caveats":"Abstract only; transport dependence is not binding. GtoPdb record has no action or affinity [DB:GtoPdb].","key_references":[{"PMID":"7541633","why":"p75 needed for NT-4 retrograde transport in vivo"}],"covers":["LR001160"]},"LR003032":{"pair":"NTM -> NTM","headline":"Neurotrimin homophilic interaction is supported by structural, proteomic and adhesion data.","interaction_type":"direct binding","direction_and_effect":"Ntm mediates homophilic adhesion shown by reaggregation of transfected cells and binding of an Ntm-Fc chimera [PMID:9801370]. IgLONs interact as homo- and heterodimers [PMID:30956130].","molecular_requirements":"Dimerization occurs through the first Ig domain of each monomer and is Ca2+ independent; IgLONs keep an extended conformation [PMID:30956130]. Cross-linking shows noncovalent homodimers and multimers [PMID:9801370].","affinity_potency":[],"species_and_systems":"Human rows per curator; transfected cells [PMID:9801370]; crystal structures of NTRI and other IgLONs, cell aggregation for NTRI and NEGR1 [PMID:30956130]. IntAct lists a protein array record [DB:IntAct].","localisation_and_range":"Neither partner flagged secreted or transmembrane [flag]; Ntm is described as GPI-anchored at the cell surface [PMID:9801370], so trans, contact-mediated adhesion.","caveats":"Self-interaction: ligand and receptor are the same protein, so scoring in CCC tools is homotypic. Abstracts only; the crystal structures cover NTRI, IgLON5 and NEGR1/IgLON5 per the abstract.","key_references":[{"PMID":"9801370","why":"Ntm homophilic adhesion and Ntm-Fc binding"},{"PMID":"30956130","why":"IgLON homo- and heterodimer structures"}],"covers":["LR003032","LR006256"]},"LR003041":{"pair":"NTN4 -> NEO1","headline":"Netrin-4 binds neogenin directly (abstract-only), and antiangiogenic function requires neogenin plus Unc5B recruitment.","interaction_type":"direct binding","direction_and_effect":"Netrin-4 bound neogenin but not Unc5B or Unc5C in endothelial cells; blocking antibodies to neogenin abolished its chemotactic effect [PMID:18719102]. Netrin-4 acts as an antiangiogenic factor [PMID:18719102].","molecular_requirements":"Silencing either neogenin or Unc5B abolished the netrin-4 inhibitory effect on endothelial migration; netrin-4 increased the association between Unc5B and neogenin [PMID:18719102].","affinity_potency":[],"species_and_systems":"Human endothelial cells; Matrigel and laser-induced choroidal neovascularization models and a xenograft [PMID:18719102]. IntAct records a co-immunoprecipitation [DB:IntAct].","localisation_and_range":"Netrin-4 is secreted [flag].","caveats":"Abstract only, no affinity reported.","key_references":[{"PMID":"18719102","why":"Netrin-4 binds neogenin and recruits Unc5B in endothelial cells"}],"covers":["LR003041","LR006265"]},"LR008969":{"pair":"PCSK9 -> VLDLR","headline":"No curated paper supports this pair; it rests on database records of PCSK9 binding VLDLR.","interaction_type":"database-asserted only","direction_and_effect":"Reactome records VLDLR binding PCSK9 and a VLDL:PCSK9 complex at the plasma membrane [DB:Reactome]. UniProt states PCSK9 binds LDLR family members including VLDLR and promotes their degradation [DB:UniProt]. No effect reported by a verified paper.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species not stated beyond the human entity record; no experiments curated.","localisation_and_range":"VLDLR is annotated transmembrane [flag].","caveats":"No verified paper; the only paper-level outcome is different_entity and one review_only row. Support is from databases alone.","key_references":[],"covers":["LR008969"]},"LR001205":{"pair":"PENK -> OGFR","headline":"One abstract-only paper: [Met5]-enkephalin (OGF) and OGFR form an inhibitory growth axis in human pancreatic cancer cells.","interaction_type":"functional only","direction_and_effect":"OGF is described as forming an inhibitory axis with OGFr; receptor overexpression and exogenous OGF reduced cell growth, and naltrexone or anti-OGF antibodies raised cell number [PMID:17332915].","molecular_requirements":"Not reported in our evidence beyond OGFr itself.","affinity_potency":[],"species_and_systems":"Human MIA PaCa-2 cells transfected with OGFr cDNA; OGFr overexpression raised OGF binding capacity 2.3- to 5.6-fold with comparable binding affinity [PMID:17332915]. Pair is human; mouse pair is ortholog-inferred.","localisation_and_range":"PENK is flagged secreted [flag]; the paper describes an autocrine loop [PMID:17332915].","caveats":"Single paper read as abstract only. The ligand is [Met5]-enkephalin, a PENK-derived peptide, not full-length proenkephalin. Effect is growth-inhibitory; the curator labels it antagonist. No database records.","key_references":[{"PMID":"17332915","why":"OGF/OGFr inhibitory axis in pancreatic cancer cells"}],"covers":["LR001205","LR004614"]},"LR001214":{"pair":"PF4 -> THBD","headline":"PF4 binds GAG-bearing thrombomodulin with Kd 31 nM by SPR; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"PF4 binds thrombomodulin and may enhance protein C activation by the thrombin-thrombomodulin complex; the curator labels it agonist [PMID:9395524].","molecular_requirements":"Binding needed the chondroitin sulfate GAG-containing form of thrombomodulin; GAG- thrombomodulin showed no measurable interaction [PMID:9395524].","affinity_potency":[{"value":"KD 31 nM","assay":"surface plasmon resonance (BIAcore)","system":"PF4 with GAG+ thrombomodulin","cite":"PMID:9395524"}],"species_and_systems":"Purified proteins and human plasma; recorded as human [PMID:9395524].","localisation_and_range":"PF4 is flagged secreted [flag].","caveats":"Abstract only. Activation effect is a hypothesis ('may enhance'). BioGRID and UniProt agree [DB:BioGRID] [DB:UniProt].","key_references":[{"PMID":"9395524","why":"PF4 binds GAG+ thrombomodulin, KD 31 nM"}],"covers":["LR001214"]},"LR003104":{"pair":"PLA2G2A -> EGFR","headline":"sPLA2-IIa co-immunoprecipitates with EGFR in human cancer cells; one abstract-only paper plus BioGRID.","interaction_type":"direct binding","direction_and_effect":"sPLA2-IIa binds EGFR and HER3 by co-immunoprecipitation, and the authors suggest it acts as a ligand for both [PMID:28440478]. Curated direction: agonist; sPLA2-IIa activates EGFR-family signalling in a positive feedback loop with HER/ERBB-PI3K-Akt-NF-kB signalling [PMID:28440478]. BioGRID lists affinity capture-Western [DB:BioGRID 2524052].","molecular_requirements":"Not reported in our evidence; HER2 interaction is indirect [PMID:28440478].","affinity_potency":[],"species_and_systems":"Human lung (A549, H1975) and prostate (22Rv1) cancer cells; xenografts in nude mice [PMID:28440478]. Mouse pair is ortholog-inferred.","localisation_and_range":"Secreted and raised in tumour interstitial fluid and blood [PMID:28440478]; secreted flag on PLA2G2A [flag].","caveats":"Abstract only; co-IP in cells does not prove direct binding or exclude intermediaries, and no affinity is reported.","key_references":[{"PMID":"28440478","why":"sPLA2-IIa binds EGFR and HER3 by co-IP and supports cancer stem cell phenotype"}],"covers":["LR003104","LR006325"]},"LR001223":{"pair":"PLAU -> LRP1","headline":"LRP binds the uPAR:uPA:PAI-1 complex and affects myogenic cell motility; complex-level, functional evidence only.","interaction_type":"functional only","direction_and_effect":"Interference with [uPAR:uPA:PAI-1] complex formation, or with LRP binding to it, decreased myogenic cell motility [PMID:10896774]. UniProt says LRP1 interacts with uPA/PLAU alone or in complex with SERPINE1 [DB:UniProt Q07954].","molecular_requirements":"The bound unit is the complex of uPAR, uPA and PAI-1 [PMID:10896774]; uPA alone as a LRP1 ligand: not reported in our evidence in the paper.","affinity_potency":[],"species_and_systems":"Human myogenic cells in vitro [PMID:10896774]. Mouse pair listed as non-inferred in our data but with no mouse evidence shown.","localisation_and_range":"Secreted uPA per flag [flag]; receptor-bound uPA and matrix-bound PAI-1 per the abstract [PMID:10896774].","caveats":"Abstract only; no binding measurement. Three other judged papers were abstract_insufficient and one was review_only.","key_references":[{"PMID":"10896774","why":"LRP interaction with uPAR:uPA:PAI-1 supports myogenic cell motility"}],"covers":["LR001223","LR004626"]},"LR003113":{"pair":"PLAUR -> ITGAV","headline":"Direct cell-based binding of soluble uPAR to alphaV (ITGAV) integrin chain in one paper; no affinity.","interaction_type":"direct binding","direction_and_effect":"Soluble uPAR (suPAR D2D3) bound integrin-transfected CHO cells in a cation-dependent manner, blocked by anti-integrin and anti-uPAR antibodies [PMID:11053440]. It acts as a ligand, signalling consequence not reported in our evidence.","molecular_requirements":"Evidence is for the heterodimer; the integrin chain alone was not tested separately [PMID:11053440]. Paired with beta3 in the paper [PMID:11053440].","affinity_potency":[],"species_and_systems":"Human uPAR on hamster (CHO) cells [PMID:11053440].","localisation_and_range":"uPAR is described as a GPI-anchored protein lacking a transmembrane structure that acts as an integrin ligand, in trans between apposed cells, as well as an associated protein in cis [PMID:11053440]. Cell-cell contact range.","caveats":"Single paper (abstract only); no affinity.","key_references":[{"PMID":"11053440","why":"uPAR binds integrins alpha4beta1, alpha6beta1, alpha9beta1, alphavbeta3 on CHO cells"}],"covers":["LR003113","LR006334"]},"LR001232":{"pair":"PLG -> PLGRKT","headline":"Plg-RKT is reported as a plasminogen receptor promoting surface activation; direct binding not in the judged paper.","interaction_type":"functional only","direction_and_effect":"Plg-RKT markedly promoted cell-surface plasminogen activation, was a differentiation-induced integral membrane protein with a C-terminal lysine, and colocalised with uPAR [PMID:19897580]. Role is agonist/promoter of activation.","molecular_requirements":"A C-terminal lysine exposed on the surface is described; cooperates with uPAR and apparently tPA [PMID:19897580].","affinity_potency":[],"species_and_systems":"Human proteins and cells; abstract only [PMID:19897580]. IntAct lists an ELISA record [DB:IntAct]. Human pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted; receptor integral membrane [PMID:19897580].","caveats":"Abstract only; the evidence sentence is functional. One additional row was review-only.","key_references":[{"PMID":"19897580","why":"Plg-RKT discovery and surface plasminogen activation"}],"covers":["LR001232","LR004635"]},"LR003122":{"pair":"PODXL2 -> SELE","headline":"Endoglycan (PODXL2) from B cells binds E-selectin in a sialylation-dependent way and supports rolling; a single paper.","interaction_type":"direct binding","direction_and_effect":"Immunopurified endoglycan from a B-cell line, a monocyte line and human tonsils bound P-selectin and, where tested, E-selectin; an endoglycan construct supported slow rolling of E- and P-selectin bearing cells [PMID:18606703].","molecular_requirements":"Binding was divalent cation-dependent and required sialylation of endoglycan; rolling depended on sialic acid and fucose [PMID:18606703]. Blocking antibodies or EDTA reduced rolling by 90-100% [PMID:18606703].","affinity_potency":[],"species_and_systems":"Human cells and tonsil-derived protein [PMID:18606703]; mouse pair is ortholog-inferred.","localisation_and_range":"Endoglycan flagged transmembrane, not secreted [flag]; contact-dependent (rolling) adhesion.","caveats":"One paper only. E-selectin was tested in fewer assays than P-selectin ('where tested'). No affinity reported. No database records.","key_references":[{"PMID":"18606703","why":"endoglycan binds E- and P-selectin; supports rolling"}],"covers":["LR003122","LR006343"]},"LR001241":{"pair":"POMC -> MC3R","headline":"POMC-derived melanocortin peptides bind and activate MC3R in binding and functional assays; abstract-level evidence, mostly peptide analogues.","interaction_type":"direct binding","direction_and_effect":"POMC-derived melanocortin peptides act as full agonists at MC3R [PMID:10493100][PMID:10358030]. Radioligand competition shows MC3R prefers desacetyl-alpha-MSH, gamma-MSH and beta-MSH over alpha-MSH [PMID:7774675]. GtoPdb records an agonist action [DB:GtoPdb]. Structures of POMC with MC3R are in the PDB [DB:PDB 8IOC].","molecular_requirements":"MC3R acts as a receptor for POMC-derived peptides; subunit or co-receptor requirements are not reported in our evidence.","affinity_potency":[{"value":"Kd 396 +/- 65 pmol/l","assay":"[125I][Nle4,D-Phe7]alpha-MSH saturation binding","system":"COS cells expressing MC3R","cite":"PMID:7774675"},{"value":"pKd 8.5","assay":"affinity of gamma-MSH-derived peptide, assay method not explicit","system":"human MC3R","cite":"PMID:10358030"},{"value":"pKi 8.0-8.4","assay":"GtoPdb affinity range","system":"not specified","cite":"PMID:10358030"}],"species_and_systems":"Rat MC3R/MC4R [PMID:10493100]; human receptor with synthetic gamma-MSH derivatives [PMID:10358030]; COS cell binding with species unspecified [PMID:7774675]. Mouse pair is ortholog-inferred. All read as abstracts.","localisation_and_range":"POMC flagged secreted, MC3R transmembrane [flag]; range not tested in the papers.","caveats":"Ligands tested are mostly synthetic analogues and individual peptides, not full-length POMC. Rat receptor in one paper despite the human tag [PMID:10493100]. Assay for the pKd value is not explicit [PMID:10358030]. The 396 pmol/l Kd is for the radiolabelled analogue, not a POMC peptide [PMID:7774675].","key_references":[{"PMID":"7774675","why":"Radioligand binding at MC3R with peptide rank order"},{"PMID":"10358030","why":"Peptide determinants of MC3R vs MC4R selectivity"},{"PMID":"10493100","why":"Rat MC3R/MC4R affinity and potency of nine ligands"}],"covers":["LR001241","LR004643"]},"LR001250":{"pair":"PPY -> NPY2R","headline":"Weak support: one abstract-only paper uses PP as a Y2 reference; UniProt says Y2 binds PP with lower affinity.","interaction_type":"conflicting","direction_and_effect":"The confirmed paper says PP is highly selective for Y4 while NPY has highest affinities at Y1, Y2 and Y5; no PP effect at Y2 is described [PMID:15966750]. UniProt says Y2 can also bind PP with lower affinity [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human peptides and receptors per the curator; chimeric-peptide affinity studies [PMID:15966750]. Mouse pair is projected from human.","localisation_and_range":"PPY is flagged secreted and NPY2R transmembrane [flag].","caveats":"Abstract-only and indirect: the sentence is a selectivity statement, not a PP-Y2 measurement [PMID:15966750]. No affinity value reported in our evidence. Reactome only records a generic reaction that NPY receptors bind NPY-related peptides [DB:Reactome].","key_references":[{"PMID":"15966750","why":"PP/NPY chimera affinity study; PP selective for Y4"}],"covers":["LR001250","LR004651"]},"LR003131":{"pair":"PRLH -> NPFFR1","headline":"Weak support: a full-text RF-amide panel reports NPFF1R binding the peptide set at 0.1-10 nM, with no PrRP-specific value in our evidence.","interaction_type":"direct binding","direction_and_effect":"In a binding panel, NPFF1R bound the whole set of RF-amide peptides with affinity constants in the 0.1-10 nM range [PMID:23911743]; the curator marks this as agonist.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human peptides and receptor, membranes from receptor-expressing cells with [3H]-FFRF-NH2 radioligand [PMID:23911743]. Mouse pair is projected.","localisation_and_range":"PRLH is flagged secreted and NPFFR1 transmembrane [flag].","caveats":"The quoted sentence is a group statement; the PRLH (PrRP) value is not given in our evidence, and the paper says RF-amide peptide selectivity is low [PMID:23911743]. NPFFR1 is not PrRP's canonical receptor in the paper's list [PMID:23911743].","key_references":[{"PMID":"23911743","why":"RF-amide peptide binding profile at five receptors"}],"covers":["LR003131","LR006352"]},"LR003140":{"pair":"PRTN3 -> CD177","headline":"PRTN3 (PR3) is displayed on neutrophils via CD177 per database records and a mouse paper that treats this as background.","interaction_type":"database-asserted only","direction_and_effect":"CD177 acts as a receptor for membrane-bound PR3 in a neutrophil subset, which the paper cites from earlier work rather than testing [PMID:30236159]. UniProt says CD177 receptors display mature PRTN3 on the neutrophil surface [DB:UniProt]; Reactome lists a PRTN3:CD177 plasma membrane complex [DB:Reactome R-HSA-5610107].","molecular_requirements":"CD177 binds the mature form of PRTN3 [DB:UniProt].","affinity_potency":[],"species_and_systems":"The curated paper used mouse neutrophils; databases are human [PMID:30236159][DB:UniProt]. A PDB structure 9IGO contains a chain of each partner [DB:PDB 9IGO].","localisation_and_range":"CD177 is flagged secreted and transmembrane [flag]; UniProt describes membrane display of PRTN3 on neutrophils [DB:UniProt]; the dossier does not give soluble versus membrane PR3 binding detail.","caveats":"The paper does not test PR3-CD177 binding; its own results concern PECAM-1 acting through CD177 [PMID:30236159]. One further abstract was insufficient. Direction (CD177 as presenter rather than signalling receptor) is not established.","key_references":[{"PMID":"30236159","why":"Context: CD177 as mPR3 receptor; PECAM-1/CD177 effect on neutrophils."}],"covers":["LR003140","LR006361"]},"LR001304":{"pair":"RNASE2 -> TLR2","headline":"EDN (RNASE2) activates TLR2 signalling in functional assays; no direct binding shown in our excerpts.","interaction_type":"functional only","direction_and_effect":"EDN triggers the TLR2-MyD88 pathway in myeloid dendritic cells and is proposed as an endogenous TLR2 ligand [PMID:18195069]. In HEK293 cells, EDN increased NF-\u03baB luciferase only in cells expressing TLR2, not TLR3 or TLR4 plus MD-2 [PMID:18195069].","molecular_requirements":"EDN activates TLR2 independently of TLR1 or TLR6 [PMID:18195069].","affinity_potency":[],"species_and_systems":"Human cells (HEK293 and monocyte-derived DCs) were used; the experiment also included DCs from wild-type and TLR2 knockout mice, and mice immunised with ovalbumin plus EDN showed Th2-biased responses [PMID:18195069].","localisation_and_range":"Ligand flagged as secreted [flag]; receptor membrane status not given in our evidence.","caveats":"Evidence is a reporter and cytokine readout, so physical binding is not shown in our evidence. One paper only.","key_references":[{"PMID":"18195069","why":"EDN activates TLR2-MyD88 signalling in dendritic cells"}],"covers":["LR001304"]},"LR001313":{"pair":"RSPO2 -> LGR5","headline":"RSPO2 binds and activates LGR5, with binding, functional and genetic evidence.","interaction_type":"direct binding","direction_and_effect":"R-spondins function as ligands of LGR4 and LGR5 [PMID:21693646]. Human RSPO2 mutants show impaired binding to LGR4/5/6 and RNF43/ZNRF3 [PMID:29769720]. GtoPdb lists full agonist [DB:GtoPdb].","molecular_requirements":"LGR5 associates with the Frizzled/Lrp complex [PMID:21727895]. RSPO2 limb function acted independently of LGR4/5/6 via RNF43/ZNRF3 [PMID:29769720].","affinity_potency":[{"value":"pEC50 12.0","assay":"Wnt reporter assay","system":"intestinal crypts / reporter assays","cite":"PMID:21693646"}],"species_and_systems":"Human proteins in intestinal crypts and reporter assays [PMID:21693646]; human tetra-amelia mutations [PMID:29769720]; mouse gut deletion [PMID:21727895].","localisation_and_range":"RSPO2 secreted per flag [flag].","caveats":"All papers abstract only. The 21727895 evidence sentence concerns Lgr5/Lgr4 co-expression, not RSPO2 binding. One review-only row. BioGRID has affinity-capture and reconstituted records [DB:BioGRID].","key_references":[{"PMID":"21693646","why":"R-spondins as LGR4/5 ligands, pEC50"},{"PMID":"29769720","why":"RSPO2 mutants lose LGR4/5/6 binding"},{"PMID":"21727895","why":"LGR4/5 mediate R-spondin signalling"}],"covers":["LR001313","LR004710"]},"LR003203":{"pair":"RTN4RL2 -> ADGRB1","headline":"Direct binding of RTN4RL2 to BAI1 shown by CRISPRa, AVEXIS and SPR, supported by two full-text papers.","interaction_type":"direct binding","direction_and_effect":"ADGRB1 probes stained RTN4RL2-transfected HEK293 cells and the ectodomains interacted directly in both bait-prey orientations [PMID:30477585]. The Cell paper identifies RTN4R, RTN4RL1 and RTN4RL2 as high-affinity receptors/ligands for BAI1 and BAI3 [PMID:34758294]. Signalling effect is not reported; RTN4RL2 loss changed neuronal synapse and axon morphology [PMID:34758294].","molecular_requirements":"ADGRB1 TSR1-3 were sufficient for RTN4R-family binding [PMID:30477585]. ADGRB2 did not interact [PMID:30477585].","affinity_potency":[{"value":"Kd = 30.0 nM","assay":"surface plasmon resonance, BAI1-RTN4RL2 (lowest affinity of the pairs tested, still nanomolar)","system":"purified recombinant ectodomains","cite":"PMID:34758294"}],"species_and_systems":"HEK293 cells, recombinant ectodomains, human neurons [PMID:30477585][PMID:34758294].","localisation_and_range":"RTN4RL2 is described as a GPI-linked membrane protein, with trans-cellular adhesion shown, so juxtacrine; yet RTN4RL2 and ADGRB1 carry secreted flags in the dossier [PMID:30477585][flag].","caveats":"Single CRISPRa screen per bait; one RTN4R family member was not enriched in the screen [PMID:30477585]. Secreted flags conflict with the membrane description.","key_references":[{"PMID":"34758294","why":"SPR Kd and neuronal function"},{"PMID":"30477585","why":"CRISPRa and AVEXIS binding"}],"covers":["LR003203","LR006423"]},"LR003212":{"pair":"S100A12 -> TLR4","headline":"S100A12 activates human monocytes through TLR4; functional blockade evidence from one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"S100A12 induces inflammatory gene expression in monocytes via TLR4; blocking S100A12 binding to TLR4 abrogates the signal, while blocking RAGE has no significant effect [PMID:23611140].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human monocytes, TLR4-expressing HEK-TCM cells, and patient sepsis samples [PMID:23611140].","localisation_and_range":"S100A12 is flagged secreted [flag]; released from granulocytes on inflammatory challenge [PMID:23611140].","caveats":"Abstract only. Curated as direct_binding, but the abstract reports blocking experiments and no binding assay.","key_references":[{"PMID":"23611140","why":"S100A12 activates monocytes via TLR4, not RAGE"}],"covers":["LR003212"]},"LR011231":{"pair":"S100A4 -> PGLYRP1","headline":"No verified paper; only UniProt notes an S100A4-PGLYRP1 interaction and complex chemoattractant function.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states PGLYRP1 acts with S100A4 as a chemoattractant complex inducing lymphocyte movement [DB:UniProt].","molecular_requirements":"The two proteins act as a complex [DB:UniProt]. Whether PGLYRP1 is a receptor or a co-ligand is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"S100A4 is flagged secreted [flag].","caveats":"Three papers are still pending curation; no verified evidence. This may be a ligand-ligand complex rather than ligand-receptor.","key_references":[],"covers":["LR011231"]},"LR003221":{"pair":"S100A4 -> TLR4","headline":"S100A4 drives cytokine production in RA PBMCs partly through TLR4; functional evidence only, abstract only.","interaction_type":"functional only","direction_and_effect":"S100A4 raised IL-1beta, IL-6 and TNF-alpha in rheumatoid arthritis PBMCs; this was at least partly mediated via TLR4, not RAGE, and by NF-kappaB, p38 and ERK1/2 [PMID:24643522].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human PBMCs from RA patients [PMID:24643522].","localisation_and_range":"S100A4 is flagged secreted [flag].","caveats":"No binding data; TLR4 involvement is partial. Abstract only. Cytokine induction was lower than S100A9 but greater than S100A8 and S100A12 [PMID:24643522].","key_references":[{"PMID":"24643522","why":"S100A4 proinflammatory effect partly via TLR4"}],"covers":["LR003221","LR006439"]},"LR003230":{"pair":"S100A8 -> NPTN","headline":"Neuroplastin-beta identified as an S100A8 receptor in keratinocytes (abstract-only).","interaction_type":"functional only","direction_and_effect":"Neuroplastin-beta is identified as an unreported S100A8 receptor; on S100A8 stimulation it recruited GRB2 and activated ERK, driving keratinocyte proliferation [PMID:27388991]. Agonist.","molecular_requirements":"Neuroplastin-beta forms homodimers and a heterodimer with EMMPRIN; the authors propose the heterodimer as a functional receptor for the S100A8/A9 heterodimer [PMID:27388991]. Knockdown of both receptors suppressed proliferation and cytokine induction [PMID:27388991].","affinity_potency":[],"species_and_systems":"Cultured normal human keratinocytes; S100A8-transgenic mice and atopic dermatitis skin were also examined [PMID:27388991]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged as secreted [flag]; secreted, so paracrine/endocrine range is plausible. Neuroplastin-beta and EMMPRIN are co-localized on the keratinocyte surface [PMID:27388991].","caveats":"Abstract only; curator row says direct_binding but the abstract does not describe a binding measurement. No affinity reported. Not clear that NPTN acts alone without EMMPRIN.","key_references":[{"PMID":"27388991","why":"Identifies neuroplastin-beta as S100A8 receptor, with EMMPRIN heterodimer"}],"covers":["LR003230","LR006447"]},"LR005012":{"pair":"Sbpl -> Tlr4","headline":"PAUF binds TLR4 ectodomain by ELISA and co-IP, but the receptor-pool screen was positive for TLR2 only; moderately supported.","interaction_type":"direct binding","direction_and_effect":"ELISA with purified TLR2 and TLR4 ECDs was dose dependent, and co-IP with full-length TLR4 in HEK293T cells confirmed the interaction, indicating direct binding without cofactors [PMID:20802527]. PAUF did not activate NF-kappaB in HEK293T cells overexpressing TLR4 [PMID:20802527].","molecular_requirements":"Not reported in our evidence beyond TLR4 itself.","affinity_potency":[],"species_and_systems":"Recombinant proteins and HEK293T cells; The paper calls the protein PAUF; curators mapped it to Sbpl, and the mouse pair is ortholog-inferred. [PMID:20802527]","localisation_and_range":"PAUF is secreted [flag].","caveats":"The pool screen gave a positive signal for TLR2 only, so TLR4 evidence rests on follow-up assays. Single paper, abstract plus excerpts; no affinity.","key_references":[{"PMID":"20802527","why":"PAUF binding to TLR2 and TLR4"}],"covers":["LR005012"]},"LR001340":{"pair":"SEMA3A -> NRP1","headline":"Sema3A binds neuropilin-1 with strong literature and database support; signalling uses plexin co-receptors.","interaction_type":"direct binding","direction_and_effect":"Neuropilin-1 binds Sema III with high affinity [PMID:9331348]. Sema3A repels axons by binding NRP1 [PMID:15721238]. Upon Sema3A binding to NP-1, L1 and NP-1 are co-internalized [PMID:15121181]. Sema3A with NP-1/Plex 1 complexes induces adherent cells to round up [PMID:10520994].","molecular_requirements":"Plexin 1 alone does not bind Sema3A, but the NP-1/Plex 1 complex has a higher affinity for Sema3A than NP-1 alone (6-fold higher in the full text) [PMID:10520994]. Plexin-A4 mainly mediates signalling via Neuropilin-1 [PMID:15721238]. L1 associates with NP-1 and is required for repulsive responses [PMID:15121181].","affinity_potency":[],"species_and_systems":"Human labelled in one binding paper [PMID:9331348]; mouse in another [PMID:10520994]; 2005 and 2004 papers used neurons from mouse mutants and COS7/neuronal cultures [PMID:15721238][PMID:15121181].","localisation_and_range":"Sema3A is a secreted ligand and NRP1 is flagged transmembrane [flag]; paracrine signalling.","caveats":"No affinity value for the Sema3A-NRP1 pair is reported in our evidence. Several papers were read as abstracts only; one confirmed row cites the pairing as background [PMID:15721238]. Database records exist [DB:BioGRID 2563623] [DB:Reactome R-HSA-399933].","key_references":[{"PMID":"9331348","why":"NRP1 binds Sema III with high affinity; NRP2 does not"},{"PMID":"10520994","why":"NP-1/Plexin complex is the physiological Sema3A receptor"},{"PMID":"15721238","why":"Plexin-A4 transduces Sema3A signalling via NRP1 in vivo"}],"covers":["LR001340","LR004736"]},"LR008000":{"pair":"SEMA4D -> PLXNB3","headline":"Only an IntAct surface plasmon resonance record supports this pair; no curator-confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"No verified paper. IntAct lists a surface plasmon resonance record for Q9ULL4 with Q92854 [DB:IntAct].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence beyond the human entities.","localisation_and_range":"SEMA4D flagged secreted and transmembrane [flag].","caveats":"Two papers were abstract_insufficient and none confirmed. Based on a single database record.","key_references":[],"covers":["LR008000"]},"LR005300":{"pair":"SEMA6B -> PLXNA2","headline":"One abstract-only chick study reports Sema6B binding floorplate PlxnA2, with Sema6B acting as the receptor side.","interaction_type":"direct binding","direction_and_effect":"Sema6B binds floorplate-derived plexin A2 for post-crossing commissural axon navigation; a truncated Sema6B lacking the intracellular domain could not rescue, so Sema6B itself signals as a receptor [PMID:25209245]. A separate cis interaction between PlxnA2 and Sema6B on pre-crossing axons may regulate responsiveness [PMID:25209245].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Chick spinal cord commissural neurons per the abstract; curator species fields say human, and the dossier pairs are ortholog-inferred.","localisation_and_range":"Transmembrane semaphorin acting in trans from floorplate to axons, and possibly in cis [PMID:25209245].","caveats":"Abstract only, one paper; the direction is reversed in this system (Sema6B as receptor, PlxnA2 as the cue), and no affinity is reported.","key_references":[{"PMID":"25209245","why":"Sema6B binds floorplate PlxnA2 in chick commissural guidance"}],"covers":["LR001970","LR005300"]},"LR003302":{"pair":"SHBG -> GPRC6A","headline":"SHBG binds GPRC6A and competes with osteocalcin; two abstract-level papers, agonist peptide shown.","interaction_type":"direct binding","direction_and_effect":"Agonist: SHBG141-161 peptide stimulates testosterone and insulin secretion in MA-10 Leydig and beta-TC6 cells, and anti-GPRC6A IgG abolishes the response [PMID:31857654]. Unliganded SHBG bound GPRC6A-transfected membranes and was displaced by ucOC at 100-fold molar excess [PMID:27673554].","molecular_requirements":"The SHBG 141-161 domain is implicated in binding [PMID:31857654]; docking suggested a shared extracellular Venus-flytrap region for SHBG, SHBG141-161 and ucOCN [PMID:31857654].","affinity_potency":[{"value":"100-fold molar excess ucOC displaced SHBG","assay":"competitive displacement","system":"HEK-293 cells transfected with GPRC6A","cite":"PMID:27673554"}],"species_and_systems":"HEK-293 cells expressing human GPRC6A, MA-10 and beta-TC6 mouse cell lines; the dossier lists the pair as human with mouse ortholog-inferred.","localisation_and_range":"SHBG is flagged secreted [flag].","caveats":"Both papers abstract-level, same research group per the curator notes; the peptide response is not full-length SHBG.","key_references":[{"PMID":"27673554","why":"SHBG binds GPRC6A and is displaced by ucOC"},{"PMID":"31857654","why":"SHBG141-161 peptide binds and activates GPRC6A"}],"covers":["LR003302","LR006516"]},"LR003311":{"pair":"SLIT1 -> PLXNA1","headline":"One browser-read paper reports Slit1 binding PlexinA1 via the Slit C-terminal fragment.","interaction_type":"direct binding","direction_and_effect":"Slit1 coimmunoprecipitated with the PlexinA1 extracellular domain; PlexinA1 binds the C-terminal Slit fragment specifically and transduces its signal independently of Robos and Neuropilins, giving a repulsive commissural response [PMID:25485759].","molecular_requirements":"The Sema-PSI extracellular region of PlexinA1 is needed; constructs lacking it did not coprecipitate Slit1. It is the Slit C-terminal fragment that binds, not the N-terminal fragment that binds Robos [PMID:25485759].","affinity_potency":[],"species_and_systems":"COS7 coimmunoprecipitation, spinal cord extracts and ex vivo commissural axons, with knockout mice [PMID:25485759]. Human row is ortholog-inferred.","localisation_and_range":"SLIT1 is flagged secreted [flag]; Slit C-terminal fragment acts as a diffusible guidance cue [PMID:25485759].","caveats":"The curator quote came from a browser read and is unverifiable pending a spot-check. Three other rows were judged a different entity. No affinity.","key_references":[{"PMID":"25485759","why":"PlexinA1 is a receptor for the Slit C-terminal fragment"}],"covers":["LR003311"]},"LR003320":{"pair":"SLURP2 -> CHRNA4","headline":"SLURP-2 co-purifies alpha4 nAChR subunit and inhibits alpha4beta2 currents at micromolar concentrations; one paper.","interaction_type":"direct binding","direction_and_effect":"SLURP-2 inhibits acetylcholine-evoked currents at human alpha4beta2 nAChRs in a concentration-dependent manner; it elicited no current by itself [PMID:27485575].","molecular_requirements":"Alpha4 was co-purified from cortical extracts; functional inhibition was shown for alpha4beta2. Whether alpha4 alone suffices is not reported [PMID:27485575].","affinity_potency":[{"value":"IC50 ~1.7 \u03bcM","assay":"inhibition of ACh-evoked current, alpha4beta2 nAChR","system":"Xenopus oocytes, human receptor","cite":"PMID:27485575"}],"species_and_systems":"Recombinant human SLURP-2 (rSLURP-2); human receptors in Xenopus oocytes and CHO cells, affinity purification from cortical brain extracts, and human oral keratinocyte Het-1A cells [PMID:27485575]. Species of the brain extract is not reported in our evidence.","localisation_and_range":"SLURP2 is flagged as secreted [flag]; the receptor is flagged as a receptor [flag]. Range is not discussed in our evidence.","caveats":"The abstract gives the alpha4beta2 IC50 as ~0.17 and the full text as ~1.7 \u03bcM; the full-text value is used here and the discrepancy is unresolved in our evidence [PMID:27485575]. Single paper.","key_references":[{"PMID":"27485575","why":"Recombinant SLURP-2 pharmacology and binding to acetylcholine receptors"}],"covers":["LR003320"]},"LR002006":{"pair":"SPON2 -> ITGA4","headline":"Mindin (SPON2) engages alpha4 integrin in neutrophil, dendritic cell and macrophage assays; antibody blocking evidence, no isolated alpha4 binding.","interaction_type":"functional only","direction_and_effect":"Neutrophil adhesion to mindin was blocked by anti-integrin alpha4 antibodies and HEK-293 cells expressing the integrins bound mindin more [PMID:16105980]. DC adhesion to mindin was blocked by anti-alpha4, alpha5 and beta1 antibodies [PMID:16917498]. SPON2-alpha4beta1 signalling activated RhoA and Rac1 and promoted M1-like macrophage recruitment [PMID:29440144].","molecular_requirements":"Evidence involves alpha4 with beta1 [PMID:29440144]; alpha4 together with alphaM and beta2 antibodies also blocked neutrophil adhesion [PMID:16105980].","affinity_potency":[],"species_and_systems":"Human neutrophils and HEK-293 [PMID:16105980]; mouse DCs [PMID:16917498]; HCC tumour microenvironment [PMID:29440144]. Both species are represented.","localisation_and_range":"Mindin is an extracellular matrix protein, immobilised matrix binding [PMID:16105980].","caveats":"Abstracts only; antibody blocking is indirect; neutrophil binding was to a mixed integrin set. No affinity.","key_references":[{"PMID":"16105980","why":"Mindin matrix binds neutrophils via alpha4, alphaM, beta2"},{"PMID":"16917498","why":"DC adhesion to mindin blocked by anti-alpha4/alpha5/beta1"},{"PMID":"29440144","why":"SPON2-alpha4beta1 signals RhoA/Rac1"}],"covers":["LR002006","LR005334"]},"LR001403":{"pair":"SPON2 -> ITGB2","headline":"Mindin (SPON2) binds beta2 integrin Mac-1 on macrophages; supported by two papers read as abstracts, one with full-text excerpts.","interaction_type":"direct binding","direction_and_effect":"Mindin serves as a ligand for integrin Mac-1 (CD11b/CD18): 131I-labelled mindin binds Mac-1 and mindin promotes macrophage phagocytosis via Syk activation and NF-kB p65 translocation [PMID:30869196]. Neutrophil adhesion to mindin is blocked by anti-integrin alpha4, alpha(M) and beta2 antibodies [PMID:16105980].","molecular_requirements":"The F-spondin fragment of mindin binds the alphaM-I domain of Mac-1 [PMID:30869196]. ITGB2 pairs with alphaM (CD11b) here, so the receptor is the alphaM/beta2 heterodimer; beta2 alone is not shown to suffice. Anti-alpha4 also blocked neutrophil adhesion [PMID:16105980].","affinity_potency":[],"species_and_systems":"Mindin-null mice impaired in neutrophil and macrophage recruitment in 4 inflammation models; HEK-293 cells transfected with integrin cDNAs bound mindin matrix more [PMID:16105980]. Mac-1 work used mindin-deficient mice, macrophages, RAW264.7 cells and mouse recombinant mindin in HEK293T cells expressing mouse CD11b/CD18 [PMID:30869196]. Dossier lists the experiment species as human for PMID:16105980 but describes mouse models.","localisation_and_range":"SPON2 is flagged secreted and ITGB2 not secreted [flag]; the papers describe mindin as an extracellular matrix protein, immobilised matrix in the adhesion assays [PMID:16105980].","caveats":"Both papers were read as abstracts (the second with full-text excerpts); PMID:16105980 does not name the beta2 partner in the binding claim itself. Human and mouse interactions are both ortholog-inferred.","key_references":[{"PMID":"30869196","why":"Radiolabelled mindin binds Mac-1; FS fragment binds alphaM-I domain"},{"PMID":"16105980","why":"Neutrophil adhesion to mindin blocked by anti-beta2/alphaM antibodies; recruitment in vivo"}],"covers":["LR001403","LR004798"]},"LR001412":{"pair":"SST -> SSTR3","headline":"Somatostatin binds human SSTR3 with high affinity and SSTR3 couples to adenylyl cyclase inhibition; multiple abstract-level papers.","interaction_type":"direct binding","direction_and_effect":"Somatostatin is an agonist; SSTR3 binds [125I]CGP 23996 with rank order somatostatin-28 = CGP 23996 > somatostatin-14 > SMS-201-995, and somatostatin inhibits D1-stimulated cAMP when co-expressed [PMID:1337145]. A second paper reports SST-14 selectivity [PMID:8097479].","molecular_requirements":"SSTR3 alone suffices in transfected cells [PMID:1337145].","affinity_potency":[{"value":"Kd 0.2 nM (about 200 pM)","assay":"saturation binding with [125I]Leu8,D-Trp22,Tyr25 SST-28","system":"COS-7 membranes expressing human SSTR3","cite":"PMID:8097479"},{"value":"pKi 8.7-10.0","assay":"GtoPdb curated range","system":"not reported","cite":"PMID:8097479"}],"species_and_systems":"Human SSTR3 in COS-1, COS-7 and CCL39 cells [PMID:1337145][PMID:8097479][PMID:9650799]. Mouse pair is ortholog-inferred.","localisation_and_range":"SST flagged secreted [flag]; PDB 8ZBI has a structure with chains of P61278 and P32745 [DB:PDB 8ZBI].","caveats":"All abstract-only. The two cloning papers disagree on SST-28 versus SST-14 preference. The Kd is for a SST-28 analogue radioligand. Human SSTR3 differs from rat in pharmacology [PMID:8097479].","key_references":[{"PMID":"1337145","why":"Cloning of SSTR3; adenylyl cyclase coupling"},{"PMID":"8097479","why":"Human SSTR3 binding at about 200 pM"},{"PMID":"9650799","why":"Five human SSTRs, SRIF28 analogue control"}],"covers":["LR001412","LR004807"]},"LR001421":{"pair":"TAC4 -> TACR1","headline":"Hemokinin-1 (TAC4) binds human NK1 (TACR1) with high affinity, equal to substance P, in one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Agonist. HEK-1 inhibited [3H]-substance P binding to human NK(1) receptor with high affinity, similar to SP (Ki=0.13 nM) [PMID:11786503]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 0.175 nM","assay":"[3H]-substance P competition","system":"human NK1 receptor","cite":"PMID:11786503"},{"value":"pKi 9.8000001907","assay":"curated agonist affinity range","system":"GtoPdb record","cite":"DB:GtoPdb"}],"species_and_systems":"Human NK1 receptor binding; functional work in isolated rat, rabbit and guinea-pig tissue [PMID:11786503]. Mouse pair is ortholog-inferred.","localisation_and_range":"TAC4 flagged secreted and TACR1 transmembrane [flag].","caveats":"Abstract only; one paper. Mouse support is inferred.","key_references":[{"PMID":"11786503","why":"HEK-1 pharmacological profile at NK1, NK2 and NK3"}],"covers":["LR001421","LR004816"]},"LR002015":{"pair":"TFF2 -> CXCR4","headline":"TFF2 activates CXCR4 signalling in several cell systems (Ca2+, MAPK/ERK, proliferation); direct binding not measured in our evidence.","interaction_type":"functional only","direction_and_effect":"TFF2 acts as a CXCR4 agonist: both mouse and human TFF2 (approximately 0.5 microM) activate Ca2+ signalling in Jurkat cells, blocked by SDF-1alpha desensitization, AMD3100 or anti-CXCR4 antibody, and TFF2 reduces subsequent SDF-1alpha Ca2+ rise and chemotaxis [PMID:19064997]. CXCR4-negative AGS cells respond only after CXCR4 expression [PMID:19064997]. A CXCR4 antagonist prevented TFF2-peptide-induced ERK1/2 phosphorylation and BrdU incorporation in MIN6 cells [PMID:23183167].","molecular_requirements":"CXCR4 is necessary for the responses shown; co-receptors are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human and mouse TFF2 proteins in Jurkat, AGS, KATO III and AsPC-1 cells [PMID:19064997]; INS-1 cells, MIN6 cells and mouse islets [PMID:23183167].","localisation_and_range":"TFF2 is annotated secreted [flag]; paracrine action is implied but not tested.","caveats":"Both papers were read as abstracts only. No binding assay or affinity is in our evidence; evidence is functional/pharmacological. TFF2 is a noncognate ligand relative to SDF-1alpha per curator notes.","key_references":[{"PMID":"19064997","why":"TFF2 activates CXCR4 in Jurkat, AGS and cancer lines"},{"PMID":"23183167","why":"CXCR4 antagonist blocks TFF2 effects in beta-cells"}],"covers":["LR002015","LR005343"]},"LR001430":{"pair":"TFPI -> LRP1","headline":"High-affinity TFPI binding to LRP (Kd 2.3 nM) was seen only when heparan sulfate was blocked; LRP is required for TFPI degradation.","interaction_type":"direct binding","direction_and_effect":"LRP is absolutely required for degrading 125I-TFPI, i.e. it acts as an endocytic clearance receptor [PMID:8824219]. TFPI cross-links to LRP on hepatoma and LRP-heterozygous cells but not LRP-negative cells [PMID:8824219].","molecular_requirements":"HSPGs are a second TFPI catabolism system; with HSPGs blocked by protamine, TFPI bound in a 39-kDa-protein-inhibitable manner and 5-fold more TFPI cross-linked to LRP [PMID:8824219].","affinity_potency":[{"value":"Kd 2.3 nM","assay":"125I-TFPI binding with HSPGs blocked by protamine; 41,000 sites per cell","system":"hepatoma cells","cite":"PMID:8824219"}],"species_and_systems":"Hepatoma cells and LRP-gene-disrupted mouse embryonic fibroblasts [PMID:8824219]. Human and mouse pairs are both ortholog-inferred.","localisation_and_range":"TFPI is annotated secreted [flag]; endocytosis is cell-surface mediated.","caveats":"LRP-heterozygous and homozygous-negative cells bound 125I-TFPI similarly, and the 39-kDa protein did not alter binding in unblocked conditions, so binding in general is largely LRP-independent [PMID:8824219]. Abstract only.","key_references":[{"PMID":"8824219","why":"LRP knockout fibroblasts; Kd 2.3 nM with HSPGs blocked"}],"covers":["LR001430","LR004825"]},"LR003401":{"pair":"TIMP1 -> ITGB1","headline":"Database-only claim that TIMP-1 acts via integrin beta1; no curated paper confirmed it.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states TIMP1 activates signalling through CD63 and ITGB1 and is found in a complex with CD63 and ITGB1 [DB:UniProt].","molecular_requirements":"The UniProt complex includes CD63 [DB:UniProt]; whether ITGB1 alone is sufficient is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and experimental system not reported in our evidence.","localisation_and_range":"TIMP1 is flagged secreted and ITGB1 as a receptor [flag].","caveats":"Two papers were judged abstract_insufficient, so no paper is confirmed. Support rests on UniProt annotation alone [DB:UniProt].","key_references":[],"covers":["LR003401","LR006602"]},"LR003410":{"pair":"TNC -> FN1","headline":"Tenascin-C binds fibronectin directly, but this is a matrix-matrix interaction rather than a cell-surface receptor pair.","interaction_type":"direct binding","direction_and_effect":"Tenascin-C binds the 13th fibronectin type III repeat (FNIII13) and thereby interferes with syndecan-4 binding to the HepII site of fibronectin, impairing adhesion and increasing tumor-cell proliferation [PMID:11731446]. Binding is not a signalling agonist action on FN1.","molecular_requirements":"FNIII13 of fibronectin is the binding site; adhesion and proliferation were restored by adding FNIII13 [PMID:11731446].","affinity_potency":[],"species_and_systems":"Human ligand and receptor per curator record; glioblastoma and breast carcinoma cells [PMID:11731446]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both partners are flagged secreted [flag]; interaction occurs in the extracellular matrix.","caveats":"Curator notes this is a matrix-matrix interaction, not a classical receptor [PMID:11731446]. Abstract-only read. BioGRID lists reconstituted complex and affinity capture records, and Reactome a binding reaction [DB:BioGRID][DB:Reactome]. Relevance as a CCC signalling pair is doubtful.","key_references":[{"PMID":"11731446","why":"Direct tenascin-C binding to FNIII13 of fibronectin"}],"covers":["LR003410","LR006611"]},"LR002024":{"pair":"TNFRSF14 -> CD160","headline":"HVEM (TNFRSF14) binds CD160, supported by crystal structures and a T-cell study plus database records; CD160 engagement is inhibitory.","interaction_type":"direct binding","direction_and_effect":"HVEM is the receptor engaged by CD160 (the pair is stored with HVEM as 'ligand'). CD160 crosslinking inhibits CD3/CD28-driven activation of human CD4+ T cells, and HVEM acts as a 'bidirectional switch' depending on which ligand engages it [PMID:18193050]. Knockin mice with HVEM muteins that lose BTLA/CD160 binding support a role for the Ig ligands (BTLA/CD160) in limiting liver inflammation [PMID:34709351].","molecular_requirements":"HVEM can bind CD160 and LIGHT at the same time in a human HVEM-LIGHT-CD160 ternary complex [PMID:34709351]. The structures used a single-chain CD160-HVEM fusion because the CD160-HVEM interaction is weak [PMID:34709351]. Inhibition of CD4+ T cells by HVEM-transfected cells depended on both CD160 and BTLA, and on HVEM cysteine-rich domain 1 [PMID:18193050]. PDB 6NG3 and 7MSG contain both chains [DB:PDB 6NG3].","affinity_potency":[],"species_and_systems":"Human proteins and human CD4+ T cells [PMID:18193050]; human structures plus mouse HVEM mutants and knockin mice [PMID:34709351]. Both papers were read as abstracts by curators, though excerpts from the 2021 full text are available.","localisation_and_range":"CD160 is membrane-anchored; the paper discusses GPI-linked and transmembrane forms [PMID:34709351]. HVEM is flagged membrane-bound [flag]. The CD160 entity also carries a secreted flag [flag].","caveats":"Mouse HVEM results use BTLA/CD160 double-loss muteins, so CD160-specific effects cannot be separated from BTLA [PMID:34709351]. The CD4+ T-cell inhibition also needs BTLA [PMID:18193050]. A weak affinity is described but its value is attributed to earlier work in the excerpt.","key_references":[{"PMID":"18193050","why":"HVEM identified as CD160 ligand; inhibitory in human CD4+ T cells"},{"PMID":"34709351","why":"HVEM-LIGHT-CD160 ternary structure and selective mutants"}],"covers":["LR002024","LR005352"]},"LR001502":{"pair":"TNFSF13 -> TNFRSF13B","headline":"APRIL binds TACI with nanomolar affinity and signals NF-kappaB; one abstract-only paper plus several interaction databases.","interaction_type":"direct binding","direction_and_effect":"TACI interacts with APRIL at nanomolar affinity, and APRIL can signal through TACI to NF-kappaB responses in HEK293 cells [PMID:10956646]. Interaction annotated stimulatory [flag].","molecular_requirements":"Reactome lists a complex of soluble BAFF/APRIL with three TACI plus BCMA [DB:Reactome]; subunit requirements are not tested in our papers.","affinity_potency":[{"value":"nanomolar affinity","assay":"binding of APRIL to TACI (abstract wording, no exact value)","system":"human proteins, HEK293T/HEK293 cells","cite":"PMID:10956646"}],"species_and_systems":"Human proteins in HEK293 cells [PMID:10956646]; mouse pair is projected from human by orthology.","localisation_and_range":"APRIL flagged secreted, TACI transmembrane [flag].","caveats":"Paper read as abstract only; APRIL binds TACI about an order of magnitude weaker than BLyS per curator notes. Also supported by BioGRID, IntAct, GtoPdb and Reactome records [DB:BioGRID][DB:IntAct][DB:GtoPdb][DB:Reactome].","key_references":[{"PMID":"10956646","why":"TACI binds APRIL with nanomolar affinity; NF-kappaB signalling"}],"covers":["LR001502","LR004893"]},"LR001511":{"pair":"TNFSF8 -> TNFRSF8","headline":"CD153 binds CD30 with Kd 23 nM; two abstract-only papers plus databases.","interaction_type":"direct binding","direction_and_effect":"Soluble trimeric CD153 bound membrane-anchored CD30 and triggered cell death and TNF-alpha production with cross-linking antibodies [PMID:11754357]. Soluble CD30 blocks cell-death signals from surface CD30 [PMID:11754357].","molecular_requirements":"Trimeric ligand was used; soluble monomeric CD30 binds with high affinity and acts as a decoy [PMID:11754357].","affinity_potency":[{"value":"KD = 23 nM","assay":"soluble trimeric CD153 binding to membrane CD30","system":"cells","cite":"PMID:11754357"},{"value":"KD 4.5 nM","assay":"BIAcore, soluble CD30/CD153","system":"recombinant","cite":"PMID:11754357"}],"species_and_systems":"Species of 11754357 not stated in our evidence; murine CD30L cloned from T cell clone 7B9 [PMID:8391931].","localisation_and_range":"TNFSF8 flagged transmembrane, not secreted; TNFRSF8 transmembrane [flag].","caveats":"Abstracts only; one further pending paper not judged. Also BioGRID, GtoPdb, Reactome records [DB:BioGRID][DB:Reactome].","key_references":[{"PMID":"11754357","why":"Kd 23 nM binding and decoy CD30"},{"PMID":"8391931","why":"Expression cloning of CD30 ligand"}],"covers":["LR001511","LR004901"]},"LR002033":{"pair":"WNT1 -> ROR2","headline":"WNT1 binds ROR2 by co-immunoprecipitation, but ROR2 modulates rather than simply activates WNT1 signalling.","interaction_type":"direct binding","direction_and_effect":"Immunoprecipitation showed physical interaction between human Ror2 and mammalian Wnt1 and Wnt3 [PMID:15388793]. Ror2 antagonised Wnt1-mediated cytosolic beta-catenin stabilisation yet potentiated Wnt1 activity in the reporter assay [PMID:15388793].","molecular_requirements":"Binding did not change Ror2 autophosphorylation [PMID:15388793]. Co-receptor needs not reported in our evidence.","affinity_potency":[],"species_and_systems":"Osteoblastic cells with human Ror2, abstract only [PMID:15388793]. BioGRID has an affinity capture-western record [DB:BioGRID].","localisation_and_range":"WNT1 is flagged as secreted [flag], so signalling would be paracrine or autocrine; this comes from the annotation flag, not from a paper.","caveats":"Co-IP does not prove direct binding; effect depends on the readout step [PMID:15388793].","key_references":[{"PMID":"15388793","why":"Ror2 binds Wnt1; opposite effects on Wnt1 and Wnt3"}],"covers":["LR002033","LR005359"]},"LR011240":{"pair":"WNT10A -> FZD2:LRP5","headline":"Database-asserted only: an IntAct co-IP record, with no confirmed paper for WNT10A with FZD2:LRP5.","interaction_type":"database-asserted only","direction_and_effect":"No confirmed paper. IntAct EBI-54877040 records an association by anti-tag coimmunoprecipitation [DB:IntAct]; the record is not specific to this complex.","molecular_requirements":"Subunit requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system of the IntAct record are not reported in our evidence.","localisation_and_range":"WNT10A is flagged as secreted [flag], so signalling would be paracrine or autocrine; this comes from the annotation flag.","caveats":"Judged papers: pending 3.","key_references":[],"covers":["LR011240"]},"LR002042":{"pair":"WNT2B -> FZD4","headline":"Supported by functional EMT data in human cells and a competition study with Tsukushi; both read from abstracts.","interaction_type":"functional only","direction_and_effect":"WNT2b induced EMT in HT29 cells through FZD4 activation [PMID:31359032]. Tsukushi binds the Fzd4 cysteine-rich domain and competes with Wnt2b, inhibiting Wnt signalling [PMID:21856951][DB:UniProt].","molecular_requirements":"Fzd4 cysteine-rich domain is the Wnt-binding site; LRP5/6 is the co-receptor in the general model, not tested for this pair [PMID:21856951].","affinity_potency":[{"value":"2.3 x 10(-10) M","assay":"Tsukushi binding to Fzd4 cysteine-rich domain (not Wnt2b itself)","system":"not stated in abstract","cite":"PMID:21856951"}],"species_and_systems":"Human cells and Crohn's disease tissue [PMID:31359032]; chick eye and mouse knockout [PMID:21856951].","localisation_and_range":"WNT2B is annotated as secreted [flag].","caveats":"The affinity belongs to Tsukushi-Fzd4, not Wnt2b-Fzd4. Direct Wnt2b-Fzd4 binding is only background in the abstract. Both papers abstract only.","key_references":[{"PMID":"31359032","why":"WNT2b induces EMT through FZD4"},{"PMID":"21856951","why":"Tsukushi competes with Wnt2b for Fzd4"}],"covers":["LR002042","LR005368"]},"LR003500":{"pair":"WNT4 -> FZD7","headline":"WNT4 shows only very weak to intermediate binding to the FZD7 CRD in purified-protein assays.","interaction_type":"direct binding","direction_and_effect":"WNT-4 showed very weak to intermediate binding to the FZD1/2/4/5/7 CRDs [PMID:25605717].","molecular_requirements":"Binding was measured to the CRD-Fc fusion alone [PMID:25605717].","affinity_potency":[],"species_and_systems":"Purified mouse proteins, bio-layer interferometry (Octet) [PMID:25605717]. Mouse pair is direct; human ortholog-inferred.","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"KD values are in a table not shown in our evidence. Browser-read, not spot-checked. Binding only; signalling not reported here.","key_references":[{"PMID":"25605717","why":"BLI of WNT-4 binding to FZD CRDs"}],"covers":["LR003500","LR006700"]},"LR001601":{"pair":"WNT5A -> FZD1","headline":"Wnt5a binds the FZD1 CRD with intermediate affinity and co-immunoprecipitates with FZD1, but does not drive FZD1-dependent TCF signalling.","interaction_type":"conflicting","direction_and_effect":"Wnt-5a coimmunoprecipitated with human Hfz1, yet Wnt-5a did not cooperate with Hfz1 in TCF-dependent transcription, whereas Wnt-3a did [PMID:10557084]. UniProt likewise says FZD1 is apparently not activated by WNT5A [DB:UniProt].","molecular_requirements":"The binding data use the FZD1 cysteine-rich domain (CRD) alone [PMID:25605717]. Co-receptor needs not reported in our evidence.","affinity_potency":[{"value":"KD = 22\u201326 nm","assay":"Bio-layer interferometry, purified WNT-5A binding to FZD CRD-Fc, reported jointly for the FZD1/2/4 CRDs","system":"mouse proteins, in vitro","cite":"PMID:25605717"}],"species_and_systems":"Mouse proteins by bio-layer interferometry [PMID:25605717]; human cells by co-IP [PMID:10557084]. The dossier also lists an inferred ortholog pair in mouse.","localisation_and_range":"WNT5A is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine by this annotation.","caveats":"The affinity paper was read from a browser full text and its quote is flagged unverifiable, spot-check pending [PMID:25605717]. The 10557084 evidence is from the abstract only, and the binding does not translate into canonical signalling. BioGRID has one Affinity Capture-Western record [DB:BioGRID].","key_references":[{"PMID":"25605717","why":"BLI binding of WNT-5A to FZD1 CRD"},{"PMID":"10557084","why":"Co-IP of Hfz1 with Wnt-5a, without TCF activation"}],"covers":["LR001601","LR004990"]},"LR001610":{"pair":"WNT5A -> ROR1","headline":"ROR1 binds Wnt5a and mediates NF-kappaB activation; support from two abstract-only papers plus UniProt.","interaction_type":"direct binding","direction_and_effect":"ROR1 binds Wnt5a, which activated NF-kappaB when coexpressed with ROR1 in HEK293 cells and enhanced CLL cell survival, neutralised by anti-ROR1 antisera [PMID:18287027]. A mutated ROR1 failed to activate NF-kB with WNT5A [PMID:27162350]. UniProt describes ROR1 as a receptor for WNT5A activating NFkB and possibly inhibiting WNT3A signalling [DB:UniProt Q01973].","molecular_requirements":"No co-receptor reported in our evidence.","affinity_potency":[],"species_and_systems":"HEK293 cells and human CLL cells [PMID:18287027]; ROR1 variants tested in cells [PMID:27162350].","localisation_and_range":"ROR1 flagged transmembrane [flag].","caveats":"Both papers abstract-only. Binding was shown by anti-tag co-immunoprecipitation [DB:IntAct P41221-Q01973]; no affinity reported.","key_references":[{"PMID":"18287027","why":"ROR1 binds Wnt5a; NF-kappaB and CLL survival"},{"PMID":"27162350","why":"Mutant ROR1 fails to activate NF-kB with WNT5A"}],"covers":["LR001610","LR004999"]},"LR005003":{"pair":"WNT7A -> FZD5","headline":"Well supported: purified Wnt7a binds Fzd5 CRD in the nanomolar range, with functional data in rat PC12 cells.","interaction_type":"direct binding","direction_and_effect":"Purified Wnt7a binds the extracellular cysteine-rich domain of Fzd5 by ELISA, with a split-eGFP readout of pathway activation [PMID:18230341]. Wnt7a acts via a Frizzled-5.LRP6 complex in PC12 cells, antagonised by Dickkopf-1 and Dickkopf-3 [PMID:12857724]. A CRISPR rescue study found Wnt7a seems to bind FZD5 by TCF4 reporter activity [PMID:28733458].","molecular_requirements":"Fzd5 with LRP6 in PC12 cells [PMID:12857724].","affinity_potency":[{"value":"nanomolar range","assay":"ELISA protein-protein binding to Fzd5 CRD","system":"purified proteins","cite":"PMID:18230341"}],"species_and_systems":"Human proteins for binding; rat PC12 cells for function [PMID:12857724]; HEK cell reporters [PMID:28733458]. Mouse pair projected.","localisation_and_range":"WNT7A is flagged secreted and non-transmembrane [flag]; UniProt lists WNT7A-FZD5 interaction [DB:UniProt].","caveats":"Two of three papers are abstract-only; the reporter evidence is indirect; one dossier row is pending.","key_references":[{"PMID":"18230341","why":"Wnt7a binds Fzd5 CRD, nanomolar"},{"PMID":"12857724","why":"Wnt7a acts via Fzd5.LRP6 in PC12"},{"PMID":"28733458","why":"Wnt-Fzd reporter map"}],"covers":["LR001614","LR005003"]},"LR002051":{"pair":"WNT7B -> FZD5","headline":"WNT7B signals through FZD5 in a FZD-knockout reporter map; functional evidence, no binding data.","interaction_type":"functional only","direction_and_effect":"In HEK293 cells lacking several FZDs, Wnt7b induced signalling via FZD5 and FZD8 [PMID:28733458].","molecular_requirements":"Rescue was tested with single FZDs; co-receptor needs not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human HEK293 reporter with multiplex CRISPR FZD knockout [PMID:28733458]. Mouse pair ortholog-inferred.","localisation_and_range":"Ligand is flagged secreted and non-transmembrane [flag], so paracrine or autocrine action is expected; the paper's own data on range are not reported in our evidence.","caveats":"Reporter activation does not show direct binding. Two further papers were abstract-insufficient.","key_references":[{"PMID":"28733458","why":"FZD-Wnt functional map, WNT7B via FZD5/FZD8"}],"covers":["LR002051","LR005377"]},"LR002060":{"pair":"WNT9B -> FZD5","headline":"WNT9B signals through FZD5 in reporter assays in two independent papers (human HEK293 panel and mouse nephron progenitor-like cells).","interaction_type":"functional only","direction_and_effect":"Wnt9b induced canonical signalling with FZD5 and FZD8, and FZD4 and FZD10 [PMID:28733458]. In M15 mesonephric-mesenchyme cells, co-transfected Fzd5 raised the WNT9b signal to 16.8-fold and Fzd5 siRNA reduced it by 52%; curators label it agonist [PMID:30978219].","molecular_requirements":"RSPO1 treatment augmented the WNT9b response 4.8-fold; Lrp6 knockdown cut the signal 60%, so optimal response needs RSPO1, FZD5 and LRP6 [PMID:30978219].","affinity_potency":[{"value":"16.8-fold","assay":"beta-catenin luciferase reporter, Fzd5 co-transfection with WNT9b","system":"M15 cells","cite":"PMID:30978219"}],"species_and_systems":"HEK293 FZD knockout reporter panel, human [PMID:28733458]; M15 cells from E10.5 mesonephric mesenchyme and CITED1+ NPCs from embryonic mouse kidney [PMID:30978219]. Human and mouse pairs listed.","localisation_and_range":"WNT9B is flagged as secreted [flag], so signalling would be paracrine; the receptor is a membrane receptor [flag].","caveats":"Both studies use functional reporters; no direct binding. The second paper was read as abstract only and shows a minimal response to WNT9b alone without RSPO1 or FZD5 [PMID:30978219].","key_references":[{"PMID":"28733458","why":"FZD knockout/rescue reporter map showing WNT9B signalling"},{"PMID":"30978219","why":"FZD5, LRP6 and RSPO1 needed for WNT9b response in M15 cells"}],"covers":["LR002060","LR005386"]},"LR001322":{"pair":"RSPO4 -> LGR5","headline":"RSPO4 is supported as an LGR5 agonist mainly by R-spondin family papers and databases, with no RSPO4-specific data in the papers.","interaction_type":"direct binding","direction_and_effect":"Stimulatory modulator of Wnt/beta-catenin signalling. LGR4 and LGR5 bind R-spondins with high affinity and potentiate Wnt signalling by enhancing Wnt-induced LRP6 phosphorylation [PMID:21693646]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"LGR5 is not coupled to G proteins or beta-arrestin on R-spondin stimulation [PMID:21693646]. Lgr4/5 associate with the Frizzled/Lrp Wnt receptor complex and enhance Wnt signals [PMID:21727895]. So it modulates Wnt rather than signalling alone.","affinity_potency":[],"species_and_systems":"Human proteins in reporter assays [PMID:21693646]; mouse gut and HEK293 cells [PMID:21727895]. Mouse pair is ortholog-inferred.","localisation_and_range":"RSPO4 is annotated secreted and LGR5 transmembrane [flag]; paracrine. Potency value held in a curated field is not reproduced here.","caveats":"Both papers abstract only and speak of R-spondins generally; RSPO4 itself is named only in UniProt as an LGR5 partner [DB:UniProt]. A pull-down is recorded in IntAct [DB:IntAct]. Reactome records RSPOs binding LGRs [DB:Reactome].","key_references":[{"PMID":"21693646","why":"R-spondins as ligands of LGR4 and LGR5."},{"PMID":"21727895","why":"Lgr4/5 mediate R-spondin signalling with the Wnt receptor complex."}],"covers":["LR001322","LR004719"]},"LR001331":{"pair":"SAA1 -> FPR2","headline":"Direct binding and agonist activity of SAA at FPR2/FPRL1 shown in transfected human cells, with a second paper showing signalling.","interaction_type":"direct binding","direction_and_effect":"SAA selectively induced Ca2+ mobilization and migration of FPRL1-expressing HEK cells and was not a ligand or agonist for FPR; radiolabeled SAA specifically bound FPRL1-transfected 293 cells [PMID:9892621]. SAA also induced ERK phosphorylation in FPR2/ALX cells [PMID:22610094].","molecular_requirements":"FPR2 alone in transfected cells was sufficient [PMID:9892621]. SAA responses depended on extracellular loops I and II of FPR2/ALX [PMID:22610094].","affinity_potency":[{"value":"EC50 250 nM","assay":"Ca2+ mobilization","system":"FPRL1-transfected 293 cells","cite":"PMID:9892621"},{"value":"pEC50 6.599999904632568","assay":"curated affinity field, Ca2+ mobilization","system":"FPRL1-expressing HEK cells","cite":"PMID:9892621"},{"value":"EC50 ~30 nM","assay":"Ca2+ flux","system":"FPR2/ALX HEK293 cells","cite":"PMID:22610094"}],"species_and_systems":"Human ligand and receptor in transfected HEK293 cells; human neutrophils and monocytes also used [PMID:9892621] [PMID:22610094].","localisation_and_range":"SAA1 is flagged secreted and FPR2 transmembrane [flag], so endocrine or paracrine action.","caveats":"SAA is a recombinant human protein (rhSAA) in these assays [PMID:9892621]. A 300 nM Kd was measured on T lymphocytes, not FPR2 [PMID:9892621]. The first paper was classed abstract only but has full text excerpts.","key_references":[{"PMID":"9892621","why":"SAA first chemotactic ligand of FPRL1; binding"},{"PMID":"22610094","why":"SAA signalling via FPR2/ALX loops I and II"}],"covers":["LR001331"]}};